// ============================================================
//  AWS Solutions Architect Associate (SAA-C03) — Question Bank + Flashcards
//  226 practice questions · 186 flashcards
//  Multi-response questions: 5 options, answer = [i, j], text says "Choose TWO"
//  ids are stable (never reuse a retired id); section = COURSES.saa section id
// ============================================================

const SAA_FLASHCARDS = [
  { id: "saa-c-001", term: "SQS Visibility Timeout", definition: "Time a received message stays hidden from other consumers (default 30s). If not deleted before it expires, the message becomes visible again and may be processed twice.", category: "integration", section: "saa-17" },
  { id: "saa-c-002", term: "RDS Multi-AZ vs Read Replicas", definition: "A Multi-AZ DB instance keeps a synchronous standby for automatic failover that serves no reads. Read replicas replicate asynchronously to scale reads. Remember: Multi-AZ for availability, replicas for reads.", category: "database", section: "saa-09" },
  { id: "saa-c-003", term: "RDS Automated Backups", definition: "Daily snapshots plus transaction logs, kept 1 to 35 days, enabling point-in-time restore into a new instance. Manual snapshots last until you delete them.", category: "database", section: "saa-09" },
  { id: "saa-c-004", term: "RDS Proxy", definition: "Fully managed connection pooler for RDS and Aurora. Cuts failover time, enforces IAM authentication, uses Secrets Manager credentials, never public. Remember: Lambda functions exhausting database connections.", category: "database", section: "saa-09" },
  { id: "saa-c-005", term: "RDS Custom", definition: "Managed RDS for Oracle and SQL Server that also lets you access the underlying OS and database for custom patches and settings. Remember: RDS plus OS access.", category: "database", section: "saa-09" },
  { id: "saa-c-006", term: "Aurora Storage and Replicas", definition: "Six copies of data across three Availability Zones, storage that grows automatically, up to 15 low-lag read replicas, and automatic failover to a replica, typically in under 30 seconds.", category: "database", section: "saa-09" },
  { id: "saa-c-007", term: "Aurora Endpoints", definition: "The writer endpoint always points to the primary. The reader endpoint load balances connections across replicas. Custom endpoints target a chosen subset, such as larger replicas for analytics.", category: "database", section: "saa-09" },
  { id: "saa-c-008", term: "Aurora Global Database", definition: "One primary Region plus read-only secondary Regions, replicated with typically under one second of lag. Promote a secondary in under a minute. Remember: cross-Region disaster recovery and low-latency global reads.", category: "database", section: "saa-09" },
  { id: "saa-c-009", term: "Aurora Serverless v2", definition: "Aurora capacity that scales automatically in fine-grained steps and can pause at zero when idle. Remember: unpredictable, intermittent, or new workloads with no capacity planning.", category: "database", section: "saa-09" },
  { id: "saa-c-010", term: "Aurora Backtrack and Cloning", definition: "Backtrack rewinds an Aurora MySQL cluster in place to an earlier time without a restore. Cloning makes a fast copy-on-write copy, ideal for a staging database from production.", category: "database", section: "saa-09" },
  { id: "saa-c-011", term: "ElastiCache Redis vs Memcached", definition: "Redis OSS or Valkey: replication, Multi-AZ failover, persistence, backups, sorted sets for leaderboards. Node-based Memcached: multi-threaded, sharded, no replication or persistence. Remember: Redis for availability.", category: "database", section: "saa-09" },
  { id: "saa-c-012", term: "Lazy Loading vs Write-Through", definition: "Lazy loading fills the cache only on a miss, risking stale data. Write-through updates the cache on every database write, keeping it fresh. TTLs expire old entries.", category: "database", section: "saa-09" },
  { id: "saa-c-013", term: "Purpose-Built Database Quick Picks", definition: "Relational: RDS or Aurora. Key-value at any scale: DynamoDB. MongoDB: DocumentDB. Graph: Neptune. Cassandra: Keyspaces. Time series: Timestream. Analytics warehouse: Redshift.", category: "database", section: "saa-21" },
  { id: "saa-c-014", term: "Amazon Timestream", definition: "Managed time-series database for IoT and operational metrics. New customers now use Timestream for InfluxDB, since Timestream for LiveAnalytics closed to new customers in 2025.", category: "database", section: "saa-21" },
  { id: "saa-c-015", term: "Amazon Athena", definition: "Serverless SQL queries directly on data in S3, priced per terabyte scanned. Cut cost with Parquet or ORC, compression, and partitions. Federated queries reach other sources through Lambda connectors.", category: "analytics", section: "saa-22" },
  { id: "saa-c-016", term: "Amazon Redshift", definition: "Columnar, massively parallel data warehouse for OLAP and BI, provisioned or serverless. Redshift Spectrum queries S3 data without loading it. Remember: complex analytics and joins, not OLTP.", category: "analytics", section: "saa-22" },
  { id: "saa-c-017", term: "Amazon OpenSearch Service", definition: "Managed search and analytics engine for full-text and partial-match search on any field, plus log analytics and dashboards. Often paired with DynamoDB to add search. Provisioned or serverless.", category: "analytics", section: "saa-22" },
  { id: "saa-c-018", term: "Amazon EMR", definition: "Managed Hadoop and Spark clusters on EC2 for big data processing. Keep primary and core nodes stable; task nodes are ideal for Spot. EMR Serverless also exists.", category: "analytics", section: "saa-22" },
  { id: "saa-c-019", term: "Amazon QuickSight", definition: "Serverless BI dashboards powered by the SPICE in-memory engine, with row-level and column-level security. Now named Quick Sight, part of Amazon Quick.", category: "analytics", section: "saa-22" },
  { id: "saa-c-020", term: "AWS Glue", definition: "Serverless ETL, such as converting CSV to Parquet. The Glue Data Catalog holds table metadata for Athena, Redshift Spectrum, and EMR; crawlers fill it. Job bookmarks skip processed data.", category: "analytics", section: "saa-22" },
  { id: "saa-c-021", term: "AWS Lake Formation", definition: "Builds a secure S3 data lake in days on top of Glue, with central fine-grained permissions, including row-level and column-level filters, enforced across Athena, Redshift Spectrum, and EMR.", category: "analytics", section: "saa-22" },
  { id: "saa-c-022", term: "Managed Service for Apache Flink", definition: "Serverless real-time stream processing with Apache Flink, formerly Kinesis Data Analytics. Reads from Kinesis Data Streams or Amazon MSK, not directly from Firehose.", category: "analytics", section: "saa-22" },
  { id: "saa-c-023", term: "Amazon MSK", definition: "Fully managed Apache Kafka, provisioned or serverless, running in your VPC across multiple Availability Zones. Remember: existing Kafka workloads move to MSK without code changes, unlike Kinesis.", category: "analytics", section: "saa-22" },
  { id: "saa-c-024", term: "VPC CIDR size range", definition: "An IPv4 VPC block can range from slash 16, about 65,000 addresses, down to slash 28, 16 addresses. Remember: plan non-overlapping ranges if you will peer or connect on-premises.", category: "network", section: "saa-27" },
  { id: "saa-c-025", term: "Subnet reserved IP addresses", definition: "AWS reserves 5 addresses in every subnet: the first four and the last one. Remember: a slash 27 subnet gives only 27 usable addresses, not 32.", category: "network", section: "saa-27" },
  { id: "saa-c-026", term: "NAT gateway vs NAT instance", definition: "NAT gateway: managed, scales to 100 Gbps, redundant within one zone, no security groups. NAT instance: self-managed EC2, disable source destination check, supports security groups.", category: "network", section: "saa-27" },
  { id: "saa-c-027", term: "Regional NAT gateway", definition: "A single NAT gateway that automatically expands across Availability Zones where you have workloads. Needs no public subnet and one route table target. Remember: public connectivity only, not private NAT.", category: "network", section: "saa-27" },
  { id: "saa-c-028", term: "Security group vs network ACL", definition: "Security groups: instance level, stateful, allow rules only, all rules evaluated. Network ACLs: subnet level, stateless, allow and deny rules, evaluated in number order, first match wins.", category: "security", section: "saa-27" },
  { id: "saa-c-029", term: "Ephemeral ports and NACLs", definition: "Clients receive responses on temporary high ports, typically 1024 to 65535. Remember: because network ACLs are stateless, you must allow these ports for return traffic.", category: "security", section: "saa-27" },
  { id: "saa-c-030", term: "VPC peering rules", definition: "Private connection between two VPCs, even across accounts or Regions. No overlapping CIDRs, and update both route tables. Remember: not transitive, so each pair needs its own peering.", category: "network", section: "saa-27" },
  { id: "saa-c-031", term: "Gateway vs interface endpoint", definition: "Gateway endpoint: route table target, S3 and DynamoDB only, free, not reachable from on-premises. Interface endpoint: ENI with private IP, most services, paid, reachable over VPN and Direct Connect.", category: "network", section: "saa-27" },
  { id: "saa-c-032", term: "AWS PrivateLink", definition: "Exposes one VPC's service to many consumer VPCs through interface endpoints, fronted by a Network Load Balancer. Remember: no peering, overlapping CIDRs are fine, consumers reach only that service.", category: "network", section: "saa-27" },
  { id: "saa-c-033", term: "AWS Transit Gateway", definition: "Regional hub that connects thousands of VPCs, VPNs and Direct Connect with transitive routing. Share across accounts with AWS RAM. Remember: choose it for IP multicast and ECMP VPN bandwidth.", category: "network", section: "saa-27" },
  { id: "saa-c-034", term: "Site-to-Site VPN components", definition: "Encrypted IPsec tunnels over the internet. AWS side: virtual private gateway or transit gateway. Your side: customer gateway device. Remember: enable route propagation; CloudHub links multiple branch sites.", category: "network", section: "saa-27" },
  { id: "saa-c-035", term: "AWS Direct Connect", definition: "Private dedicated network link to AWS, often weeks to provision. Not encrypted by default: add an IPsec VPN over it, or MACsec on 10 Gbps and faster dedicated ports.", category: "network", section: "saa-27" },
  { id: "saa-c-036", term: "Direct Connect gateway", definition: "Global resource that lets one Direct Connect connection reach VPCs in many Regions and accounts. Remember: it does not route traffic between the VPCs attached to it.", category: "network", section: "saa-27" },
  { id: "saa-c-037", term: "Direct Connect resiliency patterns", definition: "High resiliency: one connection at each of two locations. Maximum resiliency: two connections on separate devices at each of two locations. Cheapest backup: a Site-to-Site VPN.", category: "network", section: "saa-27" },
  { id: "saa-c-038", term: "VPC Flow Logs", definition: "Logs IP traffic metadata, not packets, for a VPC, subnet or network interface. Sends to CloudWatch Logs, S3 or Data Firehose. Remember: inbound accepted, outbound rejected means a network ACL.", category: "management", section: "saa-27" },
  { id: "saa-c-039", term: "Egress-only internet gateway", definition: "IPv6-only gateway that allows outbound connections and blocks connections started from the internet. Remember: it is the IPv6 counterpart of a NAT gateway.", category: "network", section: "saa-27" },
  { id: "saa-c-040", term: "AWS Network Firewall", definition: "Managed firewall for whole VPCs at layers 3 to 7: stateful rules, domain filtering, intrusion prevention. Remember: WAF protects web apps; Network Firewall protects the VPC.", category: "security", section: "saa-27" },
  { id: "saa-c-041", term: "Networking cost rules of thumb", definition: "Inbound data is free. Same-zone traffic over private IPs is free; cross-zone and public IP traffic is charged. Remember: use an S3 gateway endpoint instead of NAT.", category: "network", section: "saa-27" },
  { id: "saa-c-042", term: "IAM role for EC2", definition: "An instance profile delivers temporary, auto-rotated role credentials to an EC2 instance. Remember: never store access keys on instances; attach a role instead.", category: "security", section: "saa-04" },
  { id: "saa-c-043", term: "Credentials report vs Access Advisor", definition: "Credentials report lists every user and their password, key and MFA status account-wide. Access Advisor shows which services one identity actually used, to trim permissions.", category: "security", section: "saa-04" },
  { id: "saa-c-044", term: "Access keys, CLI and SDK", definition: "Access keys let the CLI and SDKs call AWS as an IAM user. Treat them like passwords. Remember: prefer roles and CloudShell over long-term keys.", category: "security", section: "saa-04" },
  { id: "saa-c-045", term: "Permissions boundary", definition: "A managed policy that sets the maximum permissions a user or role can get. It grants nothing by itself. Remember: stops developers creating over-privileged roles.", category: "security", section: "saa-25" },
  { id: "saa-c-046", term: "Service control policy", definition: "Organizations guardrail that limits what member accounts can do, even their root users. It grants nothing and never affects the management account.", category: "security", section: "saa-25" },
  { id: "saa-c-047", term: "IAM policy evaluation logic", definition: "An explicit deny anywhere wins. Otherwise the action must pass organization policies, permissions boundaries and session policies, and be allowed by an identity or resource-based policy.", category: "security", section: "saa-25" },
  { id: "saa-c-048", term: "aws:PrincipalOrgID condition", definition: "Condition key that allows access only to principals from accounts in your organization. Remember: one bucket policy line covers all current and future accounts.", category: "security", section: "saa-25" },
  { id: "saa-c-049", term: "Resource-based policy vs role", definition: "Assuming a role replaces your original permissions for that session. A resource-based policy lets you keep them. Remember: needed to read in one account and write in another.", category: "security", section: "saa-25" },
  { id: "saa-c-050", term: "Tag policies", definition: "Organizations policies that standardize tag keys, capitalization and allowed values across accounts and report noncompliant resources. Remember: fixes messy cost allocation tags.", category: "management", section: "saa-25" },
  { id: "saa-c-051", term: "IAM Identity Center", definition: "Formerly AWS SSO. One sign-in for all accounts in an organization and business apps, using permission sets. Identity source: built-in, Active Directory, or an external provider like Entra ID.", category: "security", section: "saa-25" },
  { id: "saa-c-052", term: "AWS Managed Microsoft AD", definition: "Real Microsoft Active Directory run by AWS across two Availability Zones. Supports trusts with on-premises AD. Users stored in it can still sign in if the on-premises link fails.", category: "security", section: "saa-25" },
  { id: "saa-c-053", term: "AD Connector vs Simple AD", definition: "AD Connector is a proxy to on-premises AD and stores nothing in AWS. Simple AD is a cheap standalone directory that cannot trust on-premises AD.", category: "security", section: "saa-25" },
  { id: "saa-c-054", term: "AWS Control Tower", definition: "Sets up a governed multi-account landing zone on Organizations. Preventive controls use service control policies, detective controls use AWS Config, with a compliance dashboard.", category: "management", section: "saa-25" },
  { id: "saa-c-055", term: "KMS key types", definition: "AWS owned keys are invisible and free. AWS managed keys rotate yearly automatically. Customer managed keys give you key policies, optional rotation and cross-account sharing.", category: "security", section: "saa-26" },
  { id: "saa-c-056", term: "Envelope encryption", definition: "KMS Encrypt handles only about 4 kilobytes. For bigger data, GenerateDataKey returns a data key that encrypts locally. Remember: large files mean envelope encryption.", category: "security", section: "saa-26" },
  { id: "saa-c-057", term: "KMS multi-Region keys", definition: "Related keys in several Regions sharing one key ID and key material, so data encrypted in one Region decrypts in another. Each replica is managed independently, not global.", category: "security", section: "saa-26" },
  { id: "saa-c-058", term: "Sharing encrypted AMIs and snapshots", definition: "Share the AMI or snapshot and grant the other account use of the customer managed key in its key policy. AWS managed keys cannot be shared across accounts.", category: "security", section: "saa-26" },
  { id: "saa-c-059", term: "S3 Bucket Keys", definition: "A bucket-level key that generates data keys locally for SSE-KMS. Remember: cuts KMS request costs and throttling for high-volume S3 buckets.", category: "storage", section: "saa-26" },
  { id: "saa-c-060", term: "Parameter Store tiers", definition: "Standard parameters are free, up to 4 kilobytes. Advanced cost extra, allow 8 kilobytes and parameter policies like expiration. SecureString encrypts with KMS. No built-in rotation.", category: "management", section: "saa-26" },
  { id: "saa-c-061", term: "AWS Secrets Manager", definition: "Stores secrets with a per-secret monthly charge and rotates them automatically, natively for RDS, Aurora, Redshift and DocumentDB. Remember: rotation requirement means Secrets Manager.", category: "security", section: "saa-26" },
  { id: "saa-c-062", term: "ACM certificates", definition: "Free public TLS certificates that auto-renew on load balancers, CloudFront and API Gateway. Imported certificates do not auto-renew. Remember: CloudFront certificates must be in us-east-1.", category: "security", section: "saa-26" },
  { id: "saa-c-063", term: "AWS CloudHSM", definition: "Single-tenant hardware security modules in your VPC. You alone manage the keys; AWS cannot see them. Remember: exclusive control or dedicated HSM means CloudHSM.", category: "security", section: "saa-26" },
  { id: "saa-c-064", term: "AWS WAF", definition: "Layer 7 firewall with web ACLs on CloudFront, Application Load Balancer, API Gateway, AppSync and Cognito. Blocks SQL injection, cross-site scripting, geographies and floods with rate-based rules.", category: "security", section: "saa-26" },
  { id: "saa-c-065", term: "Shield Standard vs Advanced", definition: "Standard is free, automatic layer 3 and 4 protection. Advanced is paid, adds the Shield Response Team, application layer mitigation and DDoS cost protection.", category: "security", section: "saa-26" },
  { id: "saa-c-066", term: "AWS Firewall Manager", definition: "Centrally applies WAF rules, Shield Advanced, security groups and Network Firewall policies across all accounts in an organization, including new ones automatically.", category: "security", section: "saa-26" },
  { id: "saa-c-067", term: "GuardDuty vs Inspector vs Macie", definition: "GuardDuty detects threats from logs like crypto mining. Inspector scans EC2, container images and Lambda for vulnerabilities. Macie finds personal data in S3.", category: "security", section: "saa-26" },
  { id: "saa-c-068", term: "Spot Instances", definition: "Spare EC2 capacity at up to 90 percent off On-Demand. AWS can reclaim it with a two-minute warning. Remember: use it only for fault-tolerant, interruptible work like batch jobs.", category: "compute", section: "saa-05" },
  { id: "saa-c-069", term: "Compute vs EC2 Instance Savings Plans", definition: "Compute Savings Plans work across any family, Region, Fargate, and Lambda, up to 66 percent off. EC2 Instance Savings Plans lock one family in one Region, up to 72 percent.", category: "compute", section: "saa-05" },
  { id: "saa-c-070", term: "On-Demand Capacity Reservation", definition: "Reserves EC2 capacity in one Availability Zone for any length of time, with no term commitment. You pay On-Demand rates whether used or not. Remember: guarantees capacity, not a discount.", category: "compute", section: "saa-05" },
  { id: "saa-c-071", term: "Cluster placement group", definition: "Packs instances close together in one Availability Zone for the lowest latency and highest throughput between them. Remember: ideal for HPC, but one hardware or zone failure hits everything.", category: "compute", section: "saa-06" },
  { id: "saa-c-072", term: "Spread vs partition placement group", definition: "Spread: each instance on distinct hardware, max seven running per Availability Zone, for small critical sets. Partition: up to seven rack-separated partitions per zone, for Hadoop, Cassandra, Kafka.", category: "compute", section: "saa-06" },
  { id: "saa-c-073", term: "Elastic Network Interface (ENI)", definition: "A virtual network card with its own private IP, MAC address, and security groups, bound to one Availability Zone. Remember: move a secondary ENI to a standby instance for failover.", category: "network", section: "saa-06" },
  { id: "saa-c-074", term: "EC2 Hibernate", definition: "Saves RAM to an encrypted EBS root volume, so the instance resumes with memory intact. Must be enabled at launch. Remember: instance store roots cannot hibernate.", category: "compute", section: "saa-06" },
  { id: "saa-c-075", term: "EBS volume types at a glance", definition: "gp3 and gp2 are general purpose SSD. io1 and io2 give sustained high IOPS. st1 suits throughput-heavy big data. sc1 is cheapest for cold data. Only SSD types can boot.", category: "storage", section: "saa-07" },
  { id: "saa-c-076", term: "gp3 vs io2 Block Express", definition: "gp3 sets IOPS and throughput independently of size, now up to 80,000 IOPS. io2 Block Express reaches 256,000 IOPS with sub-millisecond latency and 99.999 percent durability.", category: "storage", section: "saa-07" },
  { id: "saa-c-077", term: "EBS Multi-Attach", definition: "Attach one io1 or io2 volume to up to 16 Nitro instances in the same Availability Zone. Needs a cluster-aware file system. Remember: not gp3, and never across zones.", category: "storage", section: "saa-07" },
  { id: "saa-c-078", term: "EC2 instance store", definition: "Physical disks on the EC2 host with very high IOPS. Data survives a reboot but is lost on stop, hibernate, or termination. Remember: buffers, caches, and scratch data only.", category: "storage", section: "saa-07" },
  { id: "saa-c-079", term: "EBS Snapshots Archive", definition: "Moves rarely needed snapshots to a tier about 75 percent cheaper. Restoring takes 24 to 72 hours, with a 90-day minimum. Remember: long-term compliance retention.", category: "storage", section: "saa-07" },
  { id: "saa-c-080", term: "EBS Recycle Bin", definition: "Retention rules keep deleted EBS snapshots and AMIs recoverable for 1 day to 1 year. Remember: the answer for protection against accidental deletion.", category: "storage", section: "saa-07" },
  { id: "saa-c-081", term: "Encrypt an existing EBS volume", definition: "You cannot encrypt a volume in place. Snapshot it, copy or restore with encryption using a KMS key, then attach the new volume. Encryption by default only covers new volumes.", category: "security", section: "saa-07" },
  { id: "saa-c-082", term: "EFS vs EBS", definition: "EBS is block storage for one instance in one Availability Zone. EFS is a shared NFS file system for many Linux instances across zones. Remember: EFS does not support Windows.", category: "storage", section: "saa-07" },
  { id: "saa-c-083", term: "EFS storage classes", definition: "Standard for active files, Infrequent Access for files read a few times a quarter, Archive for a few times a year. Lifecycle management moves files between them automatically.", category: "storage", section: "saa-07" },
  { id: "saa-c-084", term: "ALB vs NLB vs GWLB", definition: "ALB is layer 7 HTTP with path and host routing. NLB is layer 4 TCP and UDP with static IPs per zone. GWLB is layer 3, for third-party appliances.", category: "network", section: "saa-08" },
  { id: "saa-c-085", term: "Cross-zone load balancing", definition: "Spreads traffic evenly across all registered targets in every zone. ALB: on by default, no inter-zone charge. NLB and GWLB: off by default, inter-zone data is billed.", category: "network", section: "saa-08" },
  { id: "saa-c-086", term: "ELB sticky sessions", definition: "Sends a client to the same target each time, using a cookie on ALB or source IP on NLB. Remember: helps with local session state but can unbalance load.", category: "network", section: "saa-08" },
  { id: "saa-c-087", term: "SNI on load balancers", definition: "Server Name Indication lets one listener serve many TLS certificates, chosen by hostname. Supported by ALB, NLB, and CloudFront. Remember: Classic Load Balancer allows only one certificate.", category: "security", section: "saa-08" },
  { id: "saa-c-088", term: "Deregistration delay", definition: "Also called connection draining. Lets in-flight requests finish before a deregistering target is removed. Default 300 seconds, range 0 to 3600. Set it low for short requests.", category: "network", section: "saa-08" },
  { id: "saa-c-089", term: "ASG scaling policy types", definition: "Target tracking holds a metric at a target value. Step and simple scaling react to CloudWatch alarms. Scheduled handles known times. Predictive forecasts recurring patterns from history.", category: "compute", section: "saa-08" },
  { id: "saa-c-090", term: "ASG scaling cooldown", definition: "After a simple scaling activity, the group waits, 300 seconds by default, before scaling again. Target tracking and step policies use instance warmup instead. A golden AMI shortens startup.", category: "compute", section: "saa-08" },
  { id: "saa-c-091", term: "Alias vs CNAME Record", definition: "CNAME points to any hostname but not at the zone apex. Alias points to AWS resources, works at the apex, has free queries, and cannot target an EC2 DNS name.", category: "network", section: "saa-10" },
  { id: "saa-c-092", term: "Route 53 TTL", definition: "How long resolvers cache a record. A high TTL means fewer queries and lower cost, but changes take longer to reach users. Remember: lower it before a migration.", category: "network", section: "saa-10" },
  { id: "saa-c-093", term: "Simple vs Multi-Value Routing", definition: "Simple returns every value in the record with no health checks, and the client picks one. Multi-value returns up to eight healthy records. Remember: neither replaces a load balancer.", category: "network", section: "saa-10" },
  { id: "saa-c-094", term: "Latency vs Geolocation Routing", definition: "Latency sends each user to the AWS Region with the lowest latency for them. Geolocation routes by user country or continent. Remember: add a default record for unmatched locations.", category: "network", section: "saa-10" },
  { id: "saa-c-095", term: "Geoproximity Routing Bias", definition: "Routes users to the nearest resource by distance. A positive bias from 1 to 99 grows the area served by a resource; a negative bias shrinks it.", category: "network", section: "saa-10" },
  { id: "saa-c-096", term: "Route 53 Health Checks", definition: "Probe HTTP, HTTPS, or TCP endpoints. Healthy when over 18 percent of checkers get a 200 or 300 range status. String matching reads only the first 5,120 bytes.", category: "network", section: "saa-10" },
  { id: "saa-c-097", term: "Private Endpoint Health Checks", definition: "Route 53 health checkers are on the public internet and cannot reach private resources. Create a CloudWatch metric and alarm, then a health check that monitors the alarm.", category: "network", section: "saa-10" },
  { id: "saa-c-098", term: "Route 53 Resolver Endpoints", definition: "Inbound endpoint: on-premises DNS servers forward queries to it to resolve private hosted zones. Outbound endpoint: VPC resources resolve on-premises names through forwarding rules. Remember: inbound flows into AWS.", category: "network", section: "saa-10" },
  { id: "saa-c-099", term: "Stateless Web Tier Sessions", definition: "Store session data in ElastiCache or DynamoDB, not on the instance, so any instance can serve any user. Sticky sessions work but lose sessions when instances terminate.", category: "database", section: "saa-11" },
  { id: "saa-c-100", term: "Golden AMI vs User Data", definition: "A golden AMI has software preinstalled, so instances boot ready fast. User data runs scripts at boot for dynamic settings. Restore RDS and EBS from snapshots to skip data loading.", category: "compute", section: "saa-11" },
  { id: "saa-c-101", term: "Beanstalk Web vs Worker Tier", definition: "Web server tier serves HTTP requests behind a load balancer. Worker tier pulls tasks from an SQS queue for long-running background jobs. Beanstalk is free; pay only for resources.", category: "compute", section: "saa-11" },
  { id: "saa-c-102", term: "CloudFront Origin Access Control", definition: "Lets only your CloudFront distribution read a private S3 bucket, granted through a bucket policy for the CloudFront service principal. Replaces legacy OAI and supports SSE-KMS encrypted objects.", category: "security", section: "saa-15" },
  { id: "saa-c-103", term: "CloudFront VPC Origins", definition: "Lets CloudFront reach an ALB, NLB, or EC2 instance in private subnets over a private connection, so CloudFront becomes the only public entry point to the application.", category: "network", section: "saa-15" },
  { id: "saa-c-104", term: "CloudFront Price Classes", definition: "Price Class All uses every edge location. Price Class 200 skips the most expensive regions. Price Class 100 uses only the cheapest: North America, Europe, and Israel.", category: "network", section: "saa-15" },
  { id: "saa-c-105", term: "Invalidation vs Versioned File Names", definition: "Invalidation removes cached files before their TTL expires; the first 1,000 paths a month are free, and a wildcard counts as one path. Versioned file names are cheaper and preferred.", category: "network", section: "saa-15" },
  { id: "saa-c-106", term: "Global Accelerator vs CloudFront", definition: "Global Accelerator gives two static anycast IPs and proxies TCP or UDP to endpoints without caching. CloudFront caches HTTP content at the edge. Choose Accelerator for gaming, IoT, or VoIP.", category: "network", section: "saa-15" },
  { id: "saa-c-107", term: "CRR vs SRR", definition: "Cross-Region Replication copies objects to another Region for compliance, latency, or disaster recovery. Same-Region Replication aggregates logs or syncs accounts. Both need versioning on source and destination.", category: "storage", section: "saa-12" },
  { id: "saa-c-108", term: "S3 replication gotchas", definition: "Only new objects replicate; S3 Batch Replication handles existing or failed ones. Version deletes and chained replication never replicate. Need a 15-minute SLA? Use Replication Time Control.", category: "storage", section: "saa-12" },
  { id: "saa-c-109", term: "S3 One Zone-IA", definition: "Infrequent-access class kept in a single Availability Zone, cheaper than Standard-IA, with retrieval fees and a 30-day minimum. Remember: only for re-creatable data, like secondary backup copies.", category: "storage", section: "saa-12" },
  { id: "saa-c-110", term: "S3 Glacier retrieval times", definition: "Instant Retrieval: milliseconds, 90-day minimum. Flexible Retrieval: 1 minute to 12 hours, 90-day minimum. Deep Archive: 12 to 48 hours, 180-day minimum, lowest cost.", category: "storage", section: "saa-12" },
  { id: "saa-c-111", term: "S3 Express One Zone", definition: "High-performance class using directory buckets in one Availability Zone you choose, for consistent single-digit millisecond latency. Remember: put compute in the same zone; data is not multi-AZ resilient.", category: "storage", section: "saa-12" },
  { id: "saa-c-112", term: "S3 Intelligent-Tiering", definition: "Automatically moves each object between access tiers based on its usage, for a small per-object monitoring fee and no retrieval fees. Remember: unknown or changing access patterns.", category: "storage", section: "saa-13" },
  { id: "saa-c-113", term: "S3 event notification targets", definition: "S3 events go directly to SNS, SQS standard queues, or Lambda. Use EventBridge for advanced filtering, many targets, and archive and replay. Remember: FIFO queues are not direct targets.", category: "integration", section: "saa-13" },
  { id: "saa-c-114", term: "S3 per-prefix request rates", definition: "At least 3,500 write and 5,500 read requests per second per partitioned prefix, with unlimited prefixes. Spread keys across prefixes. Remember: SSE-KMS may hit KMS quotas first.", category: "storage", section: "saa-13" },
  { id: "saa-c-115", term: "Multipart upload vs byte-range fetch", definition: "Multipart upload splits an upload into parallel parts, recommended over 100 MB and required over 5 GB. Byte-range fetches parallelize downloads or read just part of an object.", category: "storage", section: "saa-13" },
  { id: "saa-c-116", term: "S3 Requester Pays", definition: "The requester, not the bucket owner, pays for requests and data downloaded; the owner still pays for storage. Requesters must be authenticated AWS identities, never anonymous.", category: "storage", section: "saa-13" },
  { id: "saa-c-117", term: "Forcing HTTPS on an S3 bucket", definition: "Add a bucket policy that denies any request where aws:SecureTransport is false, so every request must use HTTPS. Remember: encryption in transit is enforced with a bucket policy.", category: "security", section: "saa-14" },
  { id: "saa-c-118", term: "SSE-C", definition: "You send your own key with every request over HTTPS; S3 encrypts, then discards the key. Since April 2026, new buckets have SSE-C disabled until you turn it on.", category: "security", section: "saa-14" },
  { id: "saa-c-119", term: "S3 Object Lock modes", definition: "WORM protection that needs versioning. Compliance mode: nobody, even root, can delete or shorten retention. Governance mode: permitted users can override. Legal hold: no end date until removed.", category: "security", section: "saa-14" },
  { id: "saa-c-120", term: "Glacier Vault Lock", definition: "Locks a WORM policy on a legacy Glacier vault so it can never change. The vault service closed to new customers in December 2025, so use S3 Object Lock instead.", category: "security", section: "saa-14" },
  { id: "saa-c-121", term: "S3 presigned URL", definition: "Temporary link carrying its creator's permissions to download or upload one object. Console links last up to 12 hours; CLI or SDK links up to 7 days.", category: "security", section: "saa-14" },
  { id: "saa-c-122", term: "S3 CORS", definition: "Bucket rule letting a web page from one origin request objects from a bucket on another origin. Remember: configure CORS on the bucket being requested, not the site's bucket.", category: "security", section: "saa-14" },
  { id: "saa-c-123", term: "AWS Snowball Edge", definition: "Rugged device for offline transfer when moving data online would take over a week. Imports land in S3, not Glacier. Closed to new customers since November 2025.", category: "storage", section: "saa-16" },
  { id: "saa-c-124", term: "Amazon FSx for Lustre", definition: "Parallel file system for HPC and machine learning with sub-millisecond latency. Links to S3 to read objects as files and write results back. Scratch is temporary; Persistent is replicated.", category: "storage", section: "saa-16" },
  { id: "saa-c-125", term: "FSx ONTAP vs OpenZFS", definition: "FSx for NetApp ONTAP speaks NFS, SMB, and iSCSI, ideal for NetApp migrations. FSx for OpenZFS speaks NFS only, for ZFS or Linux workloads. Both offer snapshots and instant clones.", category: "storage", section: "saa-16" },
  { id: "saa-c-126", term: "Storage Gateway types", definition: "S3 File Gateway: NFS or SMB files saved as S3 objects. Volume Gateway: iSCSI block volumes backed up as EBS snapshots. Tape Gateway: virtual tapes for existing backup software.", category: "storage", section: "saa-16" },
  { id: "saa-c-127", term: "DataSync vs Transfer Family", definition: "DataSync: scheduled, agent-based copies from NFS, SMB, or HDFS into S3, EFS, or FSx, keeping metadata. Transfer Family: managed SFTP, FTPS, FTP, or AS2 endpoints into S3 or EFS.", category: "storage", section: "saa-16" },
  { id: "saa-c-128", term: "SQS Standard vs FIFO", definition: "Standard: nearly unlimited throughput, at-least-once delivery, best-effort order. FIFO: strict order per message group, exactly-once processing, lower throughput, and the queue name ends in .fifo.", category: "integration", section: "saa-17" },
  { id: "saa-c-129", term: "SQS Long Polling", definition: "A receive call waits up to 20 seconds for a message instead of returning empty. Fewer API calls, lower cost and latency. Remember: many empty receives means enable long polling.", category: "integration", section: "saa-17" },
  { id: "saa-c-130", term: "SQS Dead-Letter Queue", definition: "Receives messages that failed processing more than maxReceiveCount times, isolating poison messages for debugging. Redrive moves them back later. A FIFO queue needs a FIFO dead-letter queue.", category: "integration", section: "saa-17" },
  { id: "saa-c-131", term: "SNS Plus SQS Fan-Out", definition: "Publish once to an SNS topic and every subscribed SQS queue gets its own copy. Each queue access policy must allow the topic. Remember: one S3 event, many consumers.", category: "integration", section: "saa-17" },
  { id: "saa-c-132", term: "Kinesis Data Streams", definition: "Real-time stream made of shards. Order is kept per partition key, retention is 24 hours by default and up to 365 days, and many consumers can replay data.", category: "analytics", section: "saa-17" },
  { id: "saa-c-133", term: "Amazon Data Firehose", definition: "Fully managed, auto-scaling delivery of streaming data to S3, Redshift, OpenSearch, Splunk or HTTP endpoints. Can transform with Lambda and convert to Parquet. Buffers data, no replay.", category: "analytics", section: "saa-17" },
  { id: "saa-c-134", term: "Amazon MQ", definition: "Managed Apache ActiveMQ or RabbitMQ brokers using open protocols like AMQP, MQTT and STOMP. Remember: migrate on-premises messaging without code changes. Scales less than SQS and SNS.", category: "integration", section: "saa-17" },
  { id: "saa-c-135", term: "ECS Task Role vs Execution Role", definition: "Task role: permissions your application code uses, set per task definition. Execution role: lets ECS pull images, send logs and read secrets. Remember: app calls S3, use the task role.", category: "security", section: "saa-18" },
  { id: "saa-c-136", term: "ECS Capacity Providers", definition: "Decide where tasks run: Fargate, Fargate Spot or an EC2 Auto Scaling group. Managed scaling adds instances when tasks cannot be placed. Fargate Spot saves up to 70 percent.", category: "compute", section: "saa-18" },
  { id: "saa-c-137", term: "Amazon EKS", definition: "Managed Kubernetes control plane. Pods run on managed node groups, self-managed EC2 nodes, Fargate, or EKS Auto Mode. Remember: already using Kubernetes or need cloud-agnostic tooling, choose EKS.", category: "compute", section: "saa-18" },
  { id: "saa-c-138", term: "AWS App Runner Status", definition: "Deploys web apps from source code or a container with built-in scaling and HTTPS. Closed to new customers since April 30, 2026. AWS now points to Amazon ECS Express Mode.", category: "compute", section: "saa-18" },
  { id: "saa-c-139", term: "Lambda Key Limits", definition: "Up to 15 minutes per invocation, memory 128 MB to 10 GB, temporary storage and container images up to 10 GB, and 1,000 concurrent executions per Region by default.", category: "compute", section: "saa-19" },
  { id: "saa-c-140", term: "Reserved vs Provisioned Concurrency", definition: "Reserved: guarantees and caps concurrency for one function, free. Provisioned: keeps environments initialized to remove cold starts, extra cost. Remember: throttling means reserved; cold starts means provisioned.", category: "compute", section: "saa-19" },
  { id: "saa-c-141", term: "Lambda SnapStart", definition: "Snapshots the initialized function when a version is published, then resumes from that snapshot to cut cold starts. Supports Java, Python and .NET. No extra charge for Java.", category: "compute", section: "saa-19" },
  { id: "saa-c-142", term: "CloudFront Functions vs Lambda@Edge", definition: "CloudFront Functions: JavaScript, viewer events only, sub-millisecond, cheapest, no network calls. Lambda@Edge: Node.js or Python, viewer and origin events, longer runtime, network access allowed.", category: "network", section: "saa-19" },
  { id: "saa-c-143", term: "DynamoDB Accelerator (DAX)", definition: "In-memory cache for DynamoDB giving microsecond reads through a compatible API, so little code change. Remember: DAX caches items and queries; ElastiCache suits computed aggregation results.", category: "database", section: "saa-19" },
  { id: "saa-c-144", term: "DynamoDB TTL", definition: "Deletes items automatically after the expiry timestamp in a chosen attribute passes, using no write capacity. Remember: session data or temporary records that should expire on their own.", category: "database", section: "saa-19" },
  { id: "saa-c-145", term: "API Gateway Authorization Options", definition: "IAM for AWS users and roles. Cognito user pool authorizer for app users. Lambda authorizer for custom or third-party tokens. Remember: API keys identify clients but do not authenticate them.", category: "security", section: "saa-19" },
  { id: "saa-c-146", term: "Step Functions Standard vs Express", definition: "Standard: runs up to one year, exactly-once execution, suits long workflows and human approval. Express: up to five minutes, very high volume, cheaper for short bursts.", category: "integration", section: "saa-19" },
  { id: "saa-c-147", term: "Cognito User vs Identity Pools", definition: "User pools: sign-up and sign-in, returning JWT tokens for API Gateway or ALB. Identity pools: exchange an identity for temporary AWS credentials to call S3 or DynamoDB directly.", category: "security", section: "saa-19" },
  { id: "saa-c-148", term: "Serverless Welcome Email Pattern", definition: "A new user item in DynamoDB is captured by DynamoDB Streams, which triggers Lambda to send the email through Amazon SES. Asynchronous, with no change to the write path.", category: "integration", section: "saa-20" },
  { id: "saa-c-149", term: "EC2 Metrics and CloudWatch Agent", definition: "Default EC2 metrics arrive every 5 minutes, or every minute with detailed monitoring. Remember: memory and disk space need the unified CloudWatch agent, which also ships log files.", category: "management", section: "saa-24" },
  { id: "saa-c-150", term: "CloudWatch Logs Subscription Filter", definition: "Streams matching log events in near real time to Kinesis Data Streams, Data Firehose, or Lambda, even across accounts. Remember: export to S3 is a slow batch job.", category: "management", section: "saa-24" },
  { id: "saa-c-151", term: "CloudWatch Contributor Insights", definition: "Analyzes log data to show the top contributors, such as the IP addresses sending the most traffic in VPC Flow Logs. Remember: think \"top N talkers\".", category: "management", section: "saa-24" },
  { id: "saa-c-152", term: "CloudTrail Event History vs Trail", definition: "Event history keeps 90 days of management events for free. For longer retention, create a trail to S3 and query it with Athena. Remember: data events are off by default.", category: "management", section: "saa-24" },
  { id: "saa-c-153", term: "CloudTrail vs Config vs CloudWatch", definition: "CloudTrail answers who made which API call. Config answers how a resource was configured over time and whether it complies. CloudWatch covers performance metrics, logs, and alarms.", category: "management", section: "saa-24" },
  { id: "saa-c-154", term: "AWS Config Rules and Remediation", definition: "Config rules check resource settings against managed or custom rules, and can auto-remediate with Systems Manager Automation. Remember: Config detects and fixes afterwards; it never blocks API calls.", category: "management", section: "saa-24" },
  { id: "saa-c-155", term: "DR Strategies, RPO and RTO", definition: "Cheapest to fastest: backup and restore, pilot light, warm standby, multi-site. RPO is how much data you can lose. RTO is how long you can be down.", category: "management", section: "saa-28" },
  { id: "saa-c-156", term: "Pilot Light vs Warm Standby", definition: "Pilot light runs only the core, like a replicated database, and launches servers during failover. Warm standby runs a scaled-down full copy that can serve traffic immediately.", category: "management", section: "saa-28" },
  { id: "saa-c-157", term: "Elastic Disaster Recovery vs MGN", definition: "Both use continuous block-level replication into a low-cost staging area. Elastic Disaster Recovery keeps servers ready for failover. Application Migration Service moves them to AWS once, for lift and shift.", category: "compute", section: "saa-28" },
  { id: "saa-c-158", term: "AWS DMS Full Load and CDC", definition: "Database Migration Service copies existing data, then change data capture keeps the target in sync while the source stays online. Remember: different engines need schema conversion first.", category: "database", section: "saa-28" },
  { id: "saa-c-159", term: "AWS Backup Vault Lock", definition: "Write once, read many protection for a backup vault. Remember: in compliance mode, once the grace period ends, nobody, including the root user, can delete backups or shorten retention.", category: "storage", section: "saa-28" },
  { id: "saa-c-160", term: "Transcribe vs Polly", definition: "Transcribe turns speech into text and can automatically redact personal data. Polly turns text into lifelike speech, tuned with SSML and pronunciation lexicons.", category: "analytics", section: "saa-23" },
  { id: "saa-c-161", term: "Comprehend vs Comprehend Medical", definition: "Comprehend finds sentiment, entities, key phrases, and language in text. Comprehend Medical extracts medical terms and protected health information from clinical notes.", category: "analytics", section: "saa-23" },
  { id: "saa-c-162", term: "Amazon Textract", definition: "Extracts printed and handwritten text, forms, and tables from scanned documents such as invoices, IDs, and tax forms. Remember: documents in, structured data out.", category: "analytics", section: "saa-23" },
  { id: "saa-c-163", term: "Amazon Kendra", definition: "Machine learning document search that answers natural language questions. Closed to new customers since July 2026; AWS suggests Amazon Bedrock Knowledge Bases instead. It may still appear on the exam.", category: "analytics", section: "saa-23" },
  { id: "saa-c-164", term: "CloudFormation Service Role", definition: "An IAM role that CloudFormation assumes to create stack resources. Users only need the iam:PassRole permission for it, so they can deploy stacks without holding those permissions directly.", category: "management", section: "saa-30" },
  { id: "saa-c-165", term: "AWS Outposts", definition: "AWS-managed racks or servers in your own data center that run services like EC2 and EBS, for low latency or data residency. Remember: you handle physical security.", category: "compute", section: "saa-30" },
  { id: "saa-c-166", term: "Amazon Pinpoint Retirement", definition: "Email, SMS, and push campaigns. Closed to new customers in May 2025, ending October 30, 2026. SMS and push move to AWS End User Messaging, email to SES.", category: "integration", section: "saa-30" },
  { id: "saa-c-167", term: "Blocking an IP Behind CloudFront", definition: "With CloudFront in front, use an AWS WAF IP set, because network ACLs only see CloudFront addresses. Without CloudFront, a network ACL deny works. Security groups cannot deny.", category: "security", section: "saa-29" },
  { id: "saa-c-168", term: "Well-Architected Framework Pillars", definition: "Six pillars: operational excellence, security, reliability, performance efficiency, cost optimization, and sustainability. Remember: the free Well-Architected Tool reviews workloads against them.", category: "management", section: "saa-31" },
  { id: "saa-c-169", term: "IAM policy structure", definition: "A JSON document with a Version and one or more Statements. Each statement has Effect, Action and Resource, plus optional Sid and Condition. Resource-based policies also require a Principal.", category: "security", section: "saa-04" },
  { id: "saa-c-170", term: "AWS CloudShell", definition: "A browser-based shell in the console with the AWS CLI preinstalled. It uses your signed-in credentials, so no access keys, and keeps a small persistent home folder per Region.", category: "management", section: "saa-04" },
  { id: "saa-c-171", term: "Beanstalk single-instance vs high availability", definition: "Single-instance mode runs one EC2 instance with an Elastic IP, good for development. High availability mode adds a load balancer and Auto Scaling across several Availability Zones.", category: "compute", section: "saa-11" },
  { id: "saa-c-172", term: "Beanstalk application, version, environment", definition: "An application is the container of components; an application version is one deployable code bundle; an environment runs one version, such as dev or prod.", category: "compute", section: "saa-11" },
  { id: "saa-c-173", term: "ECS Launch Types: EC2 vs Fargate", definition: "EC2 launch type: you provision and manage the container instances. Fargate: serverless, you only define task CPU and memory. Remember: no servers to manage means Fargate.", category: "compute", section: "saa-18" },
  { id: "saa-c-174", term: "ECS Service Auto Scaling", definition: "Scales the number of ECS tasks with target tracking, step, scheduled, or predictive policies, using CPU, memory, or load balancer requests per target. It scales tasks, not EC2 instances.", category: "compute", section: "saa-18" },
  { id: "saa-c-175", term: "Amazon ECR", definition: "Private and public container image registry, backed by S3 and secured with IAM. Supports vulnerability scanning, lifecycle policies to expire images, and cross-Region or cross-account replication.", category: "compute", section: "saa-18" },
  { id: "saa-c-176", term: "Amazon EFS for ECS Tasks", definition: "Mount an EFS file system into ECS tasks, including Fargate, for persistent storage shared across tasks and Availability Zones. Data survives task restarts. Classic exam answer for shared container storage.", category: "storage", section: "saa-18" },
  { id: "saa-c-177", term: "CloudFront Signed URLs vs Cookies", definition: "Both restrict private CloudFront content to authorized users. Signed URL: access to one file. Signed cookies: access to many files without changing URLs. Not the same as S3 presigned URLs.", category: "security", section: "saa-20" },
  { id: "saa-c-178", term: "Synchronous vs Asynchronous Microservices", definition: "Synchronous: API Gateway or load balancers, and the caller waits. Asynchronous: SQS, SNS, Kinesis, or EventBridge, and the caller moves on. Asynchronous decouples services and absorbs spikes.", category: "integration", section: "saa-20" },
  { id: "saa-c-179", term: "Amazon DocumentDB", definition: "Managed document database compatible with MongoDB. Built like Aurora: storage grows automatically and is replicated across three Availability Zones. Remember: MongoDB on AWS means DocumentDB.", category: "database", section: "saa-21" },
  { id: "saa-c-180", term: "Amazon Keyspaces", definition: "Serverless, managed database compatible with Apache Cassandra, using Cassandra Query Language. Data is replicated across three Availability Zones, with on-demand or provisioned capacity.", category: "database", section: "saa-21" },
  { id: "saa-c-181", term: "Amazon QLDB Retirement", definition: "Amazon QLDB, the ledger database, reached end of support on July 31, 2025. AWS points ledger workloads to Aurora PostgreSQL. Older practice questions may still show QLDB.", category: "database", section: "saa-21" },
  { id: "saa-c-182", term: "EC2 High Availability with Elastic IP", definition: "Auto Scaling group with minimum, maximum and desired of one across two Availability Zones. User data plus an instance role reattaches the Elastic IP address to the replacement instance.", category: "compute", section: "saa-29" },
  { id: "saa-c-183", term: "Caching Layers in AWS", definition: "Cache at the CloudFront edge, in API Gateway, then ElastiCache or DAX near the database. Caching closer to users is faster but risks staler data; tune time to live values.", category: "network", section: "saa-29" },
  { id: "saa-c-184", term: "AWS Trusted Advisor", definition: "Automated account checks for cost optimization, performance, security, fault tolerance, service limits and operational excellence. The full set of checks needs Business Support Plus or higher.", category: "management", section: "saa-31" },
  { id: "saa-c-185", term: "AWS Well-Architected Tool", definition: "Free console tool: answer questions about a workload for each pillar, get high and medium risks flagged, and track an improvement plan with milestones. Supports extra lenses such as serverless.", category: "management", section: "saa-31" },
  { id: "saa-c-186", term: "Well-Architected Design Principles", definition: "Stop guessing capacity, test systems at production scale, automate experiments, allow evolutionary architectures, drive decisions with data, and improve through game days.", category: "management", section: "saa-31" },
];

const SAA_QUESTIONS = [
  { id: "saa-q-001", question: "A company needs to decouple an order service from an inventory service so that orders are not lost if the inventory service is down. Which solution meets this requirement with the LEAST operational overhead?", options: ["Amazon SQS standard queue between the services","An Application Load Balancer in front of the inventory service","Amazon EC2 instances running RabbitMQ","AWS Direct Connect between the services"], answer: 0, explanation: "SQS is fully managed and buffers messages durably until the consumer is available — the classic decoupling answer. RabbitMQ on EC2 adds operational overhead; ALB and Direct Connect do not buffer messages.", domain: "saa2", section: "saa-17" },
  { id: "saa-q-002", question: "Which TWO actions improve the security of data stored in an Amazon S3 bucket? (Choose TWO.)", options: ["Enable S3 Block Public Access","Enable S3 Transfer Acceleration","Enable default encryption with SSE-KMS","Enable S3 Requester Pays","Use S3 Intelligent-Tiering"], answer: [0,2], explanation: "Block Public Access prevents accidental public exposure and SSE-KMS encrypts objects at rest with auditable key usage. Transfer Acceleration, Requester Pays and Intelligent-Tiering are performance/cost features.", domain: "saa1", section: "saa-14" },
  { id: "saa-q-003", question: "A company runs an Amazon RDS for MySQL DB instance that was created without encryption. A new compliance rule requires the data to be encrypted at rest with an AWS KMS key. What should a solutions architect do?", options: ["Modify the DB instance and enable encryption at rest from the RDS console","Create an encrypted read replica of the instance and promote it to primary","Restore a new DB instance from an encrypted copy of a DB snapshot","Enable default encryption on the S3 bucket that stores the automated backups"], answer: 2, explanation: "RDS encryption can only be chosen when an instance is created, so you copy a snapshot with encryption turned on and restore from that copy. You cannot simply modify the instance, and a read replica of an unencrypted instance cannot be encrypted. RDS backups are not kept in a bucket you manage.", domain: "saa1", section: "saa-09" },
  { id: "saa-q-004", question: "A serverless application uses AWS Lambda functions that connect to an Amazon RDS for PostgreSQL database. During traffic spikes the database runs out of connections. The security team also requires IAM authentication for database connections and no passwords in function code. Which solution meets these requirements?", options: ["Place Amazon RDS Proxy in front of the database and enable IAM authentication","Add two read replicas and store the database password in Lambda environment variables","Put Amazon ElastiCache in front of the database and enable Redis AUTH for the functions","Convert the instance to a Multi-AZ deployment and enable IAM database authentication"], answer: 0, explanation: "RDS Proxy pools and shares connections, so Lambda bursts no longer exhaust the database, and it can enforce IAM authentication while reading database credentials from Secrets Manager. Multi-AZ with IAM database authentication removes passwords but does nothing about connection exhaustion.", domain: "saa1", section: "saa-09" },
  { id: "saa-q-005", question: "A company has built a data lake in Amazon S3 that analysts query with Amazon Athena. The HR team must see all columns, but other analysts must not see the salary column and may only see rows for their own country. Which solution provides this with the LEAST operational overhead?", options: ["Write S3 bucket policies that restrict each analyst group to specific object prefixes","Create separate copies of the dataset for each country with AWS Glue ETL jobs","Enable Amazon Macie to detect the salary column and block access to it","Use AWS Lake Formation data filters for column-level and row-level access"], answer: 3, explanation: "Lake Formation centrally grants fine-grained permissions, including column-level and row-level data filters, and Athena enforces them. Bucket policies work on objects and prefixes, not columns or rows. Copying data per country with Glue adds pipelines and storage to maintain. Macie discovers sensitive data but does not control query access.", domain: "saa1", section: "saa-22" },
  { id: "saa-q-006", question: "An application runs on Amazon EC2 instances in an Auto Scaling group and connects to an Amazon RDS for PostgreSQL DB instance in a private subnet. Which configuration is the MOST secure way to allow only the application to reach the database?", options: ["Allow inbound TCP 5432 on the database security group from the VPC CIDR range","Allow inbound TCP 5432 on the database security group from the application security group","Make the DB instance publicly accessible and require SSL for every connection","Allow inbound TCP 3306 on the database security group from the application security group"], answer: 1, explanation: "Referencing the application's security group admits only instances that carry that group, even as Auto Scaling replaces them, and PostgreSQL listens on port 5432. The VPC CIDR rule is broader than needed, port 3306 is the MySQL port, and public accessibility needlessly exposes the database.", domain: "saa1", section: "saa-09" },
  { id: "saa-q-007", question: "A healthcare company is launching an Amazon RDS for PostgreSQL DB instance to store patient records. Data must be encrypted at rest, and all client connections must be encrypted in transit. Which TWO actions should a solutions architect take? (Choose TWO.)", options: ["Enable encryption with an AWS KMS key when creating the DB instance","Enable a Multi-AZ deployment with a standby in a second Availability Zone","Enable Enhanced Monitoring and publish database logs to CloudWatch Logs","Set the DB parameter group to require SSL for all client connections","Create a read replica of the DB instance in a second AWS Region"], answer: [0,3], explanation: "Encryption at rest is chosen at creation with a KMS key and then covers storage, snapshots and replicas. Requiring SSL in the parameter group rejects unencrypted client connections. Multi-AZ, Enhanced Monitoring and cross-Region replicas improve availability or visibility, not encryption.", domain: "saa1", section: "saa-09" },
  { id: "saa-q-008", question: "A company loads data into an Amazon Redshift cluster from Amazon S3 with the COPY command. A security policy requires this traffic to avoid the public internet and to be subject to the company's network ACLs and endpoint policies. What should a solutions architect do?", options: ["Enable Enhanced VPC Routing and add an S3 gateway endpoint to the VPC","Enable Redshift Spectrum and query the data in place in Amazon S3","Turn on cross-Region snapshot copy for the Redshift cluster","Route the COPY traffic through a NAT gateway in a public subnet"], answer: 0, explanation: "Enhanced VPC Routing forces COPY and UNLOAD traffic through the VPC, where security groups, network ACLs and endpoint policies apply, and an S3 gateway endpoint keeps it off the internet. A NAT gateway still sends traffic to public S3 endpoints over the internet, Spectrum does not change routing, and snapshot copy is for disaster recovery.", domain: "saa1", section: "saa-22" },
  { id: "saa-q-009", question: "A company publishes one Amazon QuickSight sales dashboard to all of its regional managers. Each manager must see only the sales figures for their own region. Which solution meets this requirement with the LEAST operational overhead?", options: ["Configure column-level security on the QuickSight dataset for each region","Build and share a separate dashboard and dataset for each regional manager","Apply row-level security rules to the shared QuickSight dataset","Create an Amazon Athena workgroup for each region with its own query limits"], answer: 2, explanation: "QuickSight row-level security filters dataset rows per user or group, so one dashboard shows each manager only their region. Column-level security hides columns, not rows. Separate dashboards per manager work but multiply maintenance, and Athena workgroups control query settings and cost, not which rows a viewer sees.", domain: "saa1", section: "saa-22" },
  { id: "saa-q-010", question: "A company runs a production Amazon RDS for MySQL DB instance in a single Availability Zone. The database must fail over automatically, without losing committed transactions, if that Availability Zone becomes unavailable. What should a solutions architect do?", options: ["Create a read replica in another Availability Zone and promote it during an outage","Convert the DB instance to a Multi-AZ deployment with a synchronous standby","Enable automated backups and restore to another Availability Zone during an outage","Create a cross-Region read replica and update the DNS record during an outage"], answer: 1, explanation: "A Multi-AZ deployment keeps a synchronously replicated standby in another Availability Zone and fails over automatically behind the same DNS endpoint. A read replica uses asynchronous replication, so recent writes can be lost, and promoting it is a manual step. Restoring from backups is slow and loses recent data.", domain: "saa2", section: "saa-09" },
  { id: "saa-q-011", question: "A global company runs an Amazon Aurora MySQL database in one AWS Region. It needs a disaster recovery plan for a Regional outage with an RPO of about 1 second and an RTO of under 1 minute. Users in other Regions also need low-latency reads. Which solution meets these requirements?", options: ["Add Aurora Replicas in every Availability Zone of the primary Region","Copy automated cluster snapshots to a second Region every hour","Configure an Amazon Aurora Global Database with secondary Regions","Place Amazon ElastiCache clusters in each Region in front of Aurora"], answer: 2, explanation: "Aurora Global Database replicates storage to secondary Regions with typically under 1 second of lag, serves local reads there, and a secondary can be promoted in under a minute. Replicas in one Region do not survive a Regional outage, hourly snapshots miss the RPO, and caches do not provide recovery.", domain: "saa2", section: "saa-09" },
  { id: "saa-q-012", question: "A developer accidentally dropped a table in an Amazon RDS for PostgreSQL DB instance at 14:05. Automated backups are enabled with a 7-day retention period. The company wants to recover the table with the least data loss. What should a solutions architect do?", options: ["Fail over the Multi-AZ deployment to the standby instance","Promote the existing read replica to a standalone instance","Restore the most recent manual snapshot, taken last week","Perform a point-in-time restore to 14:04 into a new DB instance"], answer: 3, explanation: "Automated backups plus transaction logs allow a point-in-time restore to any second in the retention window, up to about five minutes ago, always into a new instance. The standby and the read replica already applied the drop, and last week's snapshot would lose a week of changes.", domain: "saa2", section: "saa-09" },
  { id: "saa-q-013", question: "A gaming company stores player profiles in Amazon DynamoDB. Players in North America, Europe, and Asia must read and write their profiles with low latency, and the data must stay available if an entire AWS Region fails. Which solution meets these requirements with the LEAST operational overhead?", options: ["Enable DynamoDB global tables with replicas in the three Regions","Enable DynamoDB Streams and use AWS Lambda to copy items between Regions","Use DynamoDB Accelerator clusters in each Region in front of one table","Schedule on-demand backups and restore them into the other Regions"], answer: 0, explanation: "Global tables are fully managed, multi-active replicas, so every Region accepts local reads and writes and keeps working if another Region fails. Custom replication with Streams and Lambda is extra code to build and run, DAX only caches reads, and restoring backups is slow and loses recent changes.", domain: "saa2", section: "saa-21" },
  { id: "saa-q-014", question: "A company runs a provisioned Amazon Redshift cluster encrypted with an AWS KMS key. The company must be able to restore the data warehouse in a different AWS Region if the primary Region becomes unavailable. What should a solutions architect do?", options: ["Configure a Multi-AZ deployment for the Redshift cluster","Enable cross-Region snapshot copy with a snapshot copy grant for KMS","Use Redshift Spectrum to query the data from S3 in the other Region","Increase the automated snapshot retention period to 35 days"], answer: 1, explanation: "Redshift can automatically copy snapshots to another Region, and for KMS-encrypted clusters a snapshot copy grant lets it encrypt the copies with a key in the destination Region. Multi-AZ protects only against an Availability Zone failure, and longer retention still keeps the snapshots in the same Region.", domain: "saa2", section: "saa-22" },
  { id: "saa-q-015", question: "A web application behind an Application Load Balancer keeps user session data in memory on each EC2 instance, and users are logged out when Auto Scaling replaces instances. The company wants a highly available, low-latency session store that survives a node failure. Which solution meets these requirements?", options: ["An ElastiCache for Memcached cluster with nodes spread across Availability Zones","Sticky sessions enabled on the Application Load Balancer target group","An ElastiCache for Redis OSS cluster with replicas and Multi-AZ automatic failover","Session files stored on EC2 instance store volumes attached to each instance"], answer: 2, explanation: "Redis OSS replicates data to replicas and fails over automatically across Availability Zones, so sessions survive a node failure. A node-based Memcached cluster shards data without replication, so a failed node loses its sessions. Sticky sessions and instance store still lose data when an instance is replaced.", domain: "saa2", section: "saa-09" },
  { id: "saa-q-016", question: "An Amazon Aurora PostgreSQL cluster has a writer and four Aurora Replicas. Two replicas use large instance classes for nightly analytics, and two use smaller classes for application reads. Analytics queries must run only on the large replicas. What should a solutions architect configure?", options: ["Point the analytics tool at the Aurora cluster reader endpoint","Create a custom endpoint that includes only the two large replicas","Point the analytics tool at the cluster writer endpoint","Enable Aurora Auto Scaling for the reader replicas in the cluster"], answer: 1, explanation: "A custom endpoint load balances connections across a chosen subset of instances, such as the large analytics replicas. The reader endpoint spreads connections over all replicas, including the small ones, and the writer endpoint would put analytics load on the primary. Auto Scaling adds replicas but does not route queries.", domain: "saa3", section: "saa-09" },
  { id: "saa-q-017", question: "An e-commerce site uses an Amazon RDS for MySQL Multi-AZ DB instance. Product catalog pages issue many repeated read queries, and database CPU is high during peaks while writes stay light. Which TWO actions will improve read performance? (Choose TWO.)", options: ["Send the read queries to the Multi-AZ standby instance","Increase the automated backup retention period","Add read replicas and send catalog read queries to them","Enable RDS storage autoscaling on the DB instance","Cache frequent query results in Amazon ElastiCache"], answer: [2,4], explanation: "Read replicas take read traffic off the primary, and ElastiCache serves repeated query results from memory, cutting database load. In a Multi-AZ DB instance deployment the standby cannot serve reads, and backup retention and storage autoscaling do nothing for CPU spent on reads.", domain: "saa3", section: "saa-09" },
  { id: "saa-q-018", question: "An online store keeps its product catalog in Amazon DynamoDB. Customers need to search products by partial words across any attribute, such as name, description, or brand. Which solution provides this capability?", options: ["Add global secondary indexes for the name, description, and brand attributes","Use DynamoDB Accelerator to cache the results of Scan operations","Query the DynamoDB table with Amazon Athena using SQL LIKE filters","Stream table changes to Amazon OpenSearch Service and search there"], answer: 3, explanation: "OpenSearch indexes every field and supports full-text and partial-match search, and DynamoDB Streams or the zero-ETL integration keeps the index in sync. Global secondary indexes need exact key lookups, DAX caches but adds no search, and Athena federated queries are too slow for customer-facing search.", domain: "saa3", section: "saa-22" },
  { id: "saa-q-019", question: "A company ingests clickstream events into Amazon Kinesis Data Streams. It needs to compute rolling five-minute metrics and detect anomalies in real time with a fully managed service, without managing servers or clusters. Which service should a solutions architect use?", options: ["Amazon Managed Service for Apache Flink","Amazon Athena with scheduled queries","Amazon EMR with a long-running cluster","AWS Glue with nightly batch ETL jobs"], answer: 0, explanation: "Managed Service for Apache Flink, formerly Kinesis Data Analytics, runs Flink applications serverlessly on Kinesis or MSK streams, which suits windowed metrics and real-time anomaly detection. EMR means managing a cluster, and Athena queries and nightly Glue jobs work on data at rest, not in real time.", domain: "saa3", section: "saa-22" },
  { id: "saa-q-020", question: "A company runs a self-managed Apache Kafka cluster on Amazon EC2 instances. The team wants to reduce operational overhead by moving to a managed service while keeping its existing Kafka producers and consumers unchanged. Which service should a solutions architect recommend?", options: ["Amazon Kinesis Data Streams in on-demand mode","Amazon MQ with RabbitMQ brokers","Amazon Managed Streaming for Apache Kafka","Amazon Data Firehose delivery streams"], answer: 2, explanation: "Amazon MSK runs Apache Kafka for you, provisioned or serverless, and exposes the native Kafka APIs, so producers and consumers keep working. Kinesis Data Streams and Firehose use different APIs and would need code changes, and Amazon MQ supports ActiveMQ and RabbitMQ, not Kafka.", domain: "saa3", section: "saa-22" },
  { id: "saa-q-021", question: "A social media startup needs a database that stores users and their relationships. It must answer queries such as finding friends of friends who like the same band with low latency. Which AWS database is the BEST fit?", options: ["Amazon DocumentDB","Amazon Keyspaces","Amazon Redshift","Amazon Neptune"], answer: 3, explanation: "Neptune is a managed graph database built for highly connected data and fast relationship queries like friends of friends. DocumentDB stores JSON documents with MongoDB compatibility, Keyspaces is managed Apache Cassandra, and Redshift is a data warehouse for analytics, not low-latency relationship lookups.", domain: "saa3", section: "saa-21" },
  { id: "saa-q-022", question: "A company stores several terabytes of uncompressed CSV log files in Amazon S3 and runs Amazon Athena queries that usually filter on a date range. Query costs keep rising. Which TWO actions will MOST reduce Athena costs? (Choose TWO.)", options: ["Enable S3 Transfer Acceleration on the bucket that stores the logs","Convert the files to a compressed columnar format such as Apache Parquet","Move the log files to the S3 Glacier Flexible Retrieval storage class","Partition the data in S3 by date and filter on the partition column","Create an Athena workgroup for each analyst team with its own output location"], answer: [1,3], explanation: "Athena charges for data scanned. Compressed columnar formats like Parquet read only the needed columns and fewer bytes, and date partitions let queries skip irrelevant data. Transfer Acceleration only speeds uploads, Glacier objects must be restored before Athena can read them, and separate workgroups do not reduce scanning.", domain: "saa4", section: "saa-22" },
  { id: "saa-q-023", question: "A company is launching an internal application with an unpredictable workload. Its relational database is busy for short periods during the day and idle most nights and weekends. The company wants a MySQL-compatible database that minimizes cost and needs no capacity planning. Which solution meets these requirements?", options: ["Amazon RDS for MySQL on a 3-year Reserved Instance","Amazon Aurora Serverless v2 with MySQL compatibility","An Amazon Aurora provisioned cluster sized for peak load","Amazon RDS for MySQL as a Multi-AZ DB cluster deployment"], answer: 1, explanation: "Aurora Serverless v2 scales capacity up and down automatically in small steps and can pause at zero capacity when idle, so you pay mostly for what you use. Reserved Instances and peak-sized clusters pay for idle capacity, and a Multi-AZ DB cluster adds cost without handling variable load.", domain: "saa4", section: "saa-09" },
  { id: "saa-q-024", question: "A company runs a nightly Apache Spark job on Amazon EMR that takes about three hours. The job can be retried if some capacity is lost, and the cluster sits idle for the rest of the day. Which TWO actions will MOST reduce cost? (Choose TWO.)", options: ["Purchase Reserved Instances for every node in the cluster","Use Spot Instances for the task nodes of the cluster","Enable termination protection so the cluster is never lost","Use Provisioned IOPS EBS volumes for the core nodes","Run a transient cluster that terminates when the job finishes"], answer: [1,4], explanation: "Task nodes only run compute and hold no HDFS data, so Spot interruptions are cheap to absorb. A transient cluster stops charges once the job ends instead of idling all day. Reserved Instances pay around the clock for mostly idle capacity, termination protection keeps the cluster running, and Provisioned IOPS adds cost.", domain: "saa4", section: "saa-22" },
  { id: "saa-q-025", question: "An AWS Glue ETL job runs every hour to convert new CSV files in an Amazon S3 bucket to Parquet. Each run reprocesses every file in the bucket, which increases cost and run time. What should a solutions architect do so that only new files are processed?", options: ["Enable job bookmarks for the AWS Glue job","Run an AWS Glue crawler before each job run","Increase the number of DPUs allocated to the job","Replace the job with a long-running Amazon EMR cluster"], answer: 0, explanation: "Glue job bookmarks track data already processed, so each run picks up only new files, cutting cost and run time. A crawler updates the Data Catalog but does not track processed files, more DPUs make the same full reprocessing faster but not cheaper, and EMR adds a cluster to manage.", domain: "saa4", section: "saa-22" },
  { id: "saa-q-026", question: "A startup is launching a mobile app backed by Amazon DynamoDB. Traffic is unpredictable, with sudden spikes after marketing campaigns and almost no usage overnight. The company wants to pay only for the requests it actually makes. Which configuration is the MOST cost-effective?", options: ["Provisioned capacity mode sized for the expected peak","Reserved capacity purchased for a one-year term","A DynamoDB Accelerator cluster in front of the table","On-demand capacity mode for the table"], answer: 3, explanation: "On-demand mode charges per read and write request and absorbs sudden spikes without capacity planning, which suits new or unpredictable workloads. Provisioning for peak pays for idle capacity overnight, reserved capacity needs steady predictable use, and DAX adds cost for caching rather than lowering request charges.", domain: "saa4", section: "saa-21" },
  { id: "saa-q-027", question: "A security team detects malicious traffic from a specific IP address range reaching web servers in a public subnet. The servers are not behind a load balancer. The team must block that range for every instance in the subnet immediately. What should a solutions architect do?", options: ["Add a deny rule for the range to the inbound rules of the web servers' security group","Add a deny rule for the range to the subnet's network ACL, numbered before the allow rules","Change the route table so that traffic from the range bypasses the internet gateway","Enable VPC Flow Logs on the subnet with a filter that rejects traffic from the range"], answer: 1, explanation: "Network ACLs support explicit deny rules, evaluated in number order, and apply to every instance in the subnet. Security groups only support allow rules, so they cannot block one range. Route tables cannot filter by source address, and flow logs only record traffic.", domain: "saa1", section: "saa-27" },
  { id: "saa-q-028", question: "Application servers in private subnets must read objects from an Amazon S3 bucket in the same Region. The traffic must not traverse the internet, and the bucket must reject requests that do not come through the VPC. Which combination of steps meets these requirements? (Choose TWO.)", options: ["Create a NAT gateway in a public subnet and route the S3 traffic through it","Create a gateway VPC endpoint for S3 and add it to the private subnets' route tables","Enable S3 Transfer Acceleration on the bucket and use the accelerate endpoint","Add a bucket policy that denies requests unless aws:SourceVpce matches the endpoint","Add a security group outbound rule on the servers that allows HTTPS to S3"], answer: [1,3], explanation: "A gateway endpoint keeps S3 traffic on the AWS network through a route table entry, and an aws:SourceVpce condition in the bucket policy rejects requests from anywhere else. A NAT gateway sends traffic to the public S3 endpoint, Transfer Acceleration uses edge locations over the internet, and a security group rule restricts nothing at the bucket.", domain: "saa1", section: "saa-27" },
  { id: "saa-q-029", question: "A company uses a bastion host in a public subnet so that administrators can SSH into Amazon EC2 instances in private subnets. Administrators connect only from the corporate network. Which TWO security group rules follow the principle of least privilege? (Choose TWO.)", options: ["On the bastion's security group, allow inbound port 22 from the corporate public IP range","On the bastion's security group, allow inbound port 22 from any address on the internet","On the private instances' security group, allow inbound port 22 from the corporate public IP range","On the bastion's security group, allow outbound port 22 only to the corporate public IP range","On the private instances' security group, allow inbound port 22 from the bastion's security group"], answer: [0,4], explanation: "The bastion should accept SSH only from the corporate range, and private instances should accept SSH only from the bastion's security group, which survives bastion IP changes. Opening port 22 to the internet breaks least privilege, corporate addresses cannot reach private subnets directly, and the bastion needs outbound SSH to the private instances, not the corporate network.", domain: "saa1", section: "saa-27" },
  { id: "saa-q-030", question: "A company must inspect all traffic leaving its VPCs, block outbound requests to disallowed domain names, and apply intrusion prevention rules. The solution must be managed by AWS and protect entire VPCs rather than individual applications. Which service should the company use?", options: ["AWS WAF","AWS Shield Advanced","Amazon GuardDuty","AWS Network Firewall"], answer: 3, explanation: "AWS Network Firewall protects whole VPCs at layers 3 to 7 with stateful rules, domain name filtering and Suricata-compatible intrusion prevention. AWS WAF only filters web requests to resources such as CloudFront, Application Load Balancers and API Gateway. Shield Advanced targets DDoS, and GuardDuty detects threats without blocking them.", domain: "saa1", section: "saa-27" },
  { id: "saa-q-031", question: "A web server in a public subnet has a security group that allows inbound HTTPS from anywhere. The subnet uses a new custom network ACL that contains only the default deny rules. Users cannot connect to the website. Which TWO changes will allow HTTPS traffic to work? (Choose TWO.)", options: ["Add a security group outbound rule that allows TCP ports 1024 to 65535 to anywhere","Add a network ACL outbound rule that allows TCP port 443 to anywhere","Add a network ACL inbound rule that allows TCP port 443 from anywhere","Add a network ACL outbound rule that allows TCP ports 1024 to 65535 to anywhere","Add a security group inbound rule that allows TCP ports 1024 to 65535 from anywhere"], answer: [2,3], explanation: "Network ACLs are stateless, so the subnet needs an inbound rule for port 443 and an outbound rule for the client's ephemeral ports. Security groups are stateful, so return traffic is allowed automatically. An outbound port 443 rule does not match responses, which go to the client's ephemeral port.", domain: "saa1", section: "saa-27" },
  { id: "saa-q-032", question: "A company connects its data center to a VPC through an AWS Direct Connect hosted connection from a partner. A new compliance rule requires all traffic between the data center and the VPC to be encrypted in transit. What should a solutions architect do?", options: ["Set up an IPsec Site-to-Site VPN connection that runs over the Direct Connect link","Attach a Direct Connect gateway in front of the existing virtual private gateway","Order a second hosted connection from a different Direct Connect partner","Enable Direct Connect SiteLink on the existing private virtual interface"], answer: 0, explanation: "Direct Connect traffic is private but not encrypted by default. An IPsec VPN running over the Direct Connect link adds encryption in transit while keeping the dedicated path. MACsec is not offered on hosted connections, and a Direct Connect gateway, SiteLink or a second connection changes routing or resilience, not encryption.", domain: "saa1", section: "saa-27" },
  { id: "saa-q-033", question: "Instances in private subnets across two Availability Zones reach the internet through a single NAT instance. The operations team wants to remove this single point of failure and stop patching the NAT instance. Which solution meets these requirements?", options: ["Create a single NAT gateway in one Availability Zone and route every private subnet to it","Run NAT instances in an Auto Scaling group in both zones with scripts that update routes","Create a NAT gateway in each Availability Zone and route each private subnet to its local one","Attach a second internet gateway and add a route to it from each private subnet"], answer: 2, explanation: "NAT gateways are managed and redundant within their zone, so one per zone removes both the patching work and the single point of failure. A single NAT gateway still fails with its zone, scripted NAT instances keep the operational burden, and a VPC can have only one internet gateway.", domain: "saa2", section: "saa-27" },
  { id: "saa-q-034", question: "A company is redesigning a VPC. Workloads in private subnets need outbound IPv4 internet access. The security team wants no public subnets in the VPC, and the network team wants NAT to follow workloads into new Availability Zones without route table changes. Which solution meets these requirements with the LEAST operational overhead?", options: ["Create a zonal NAT gateway in each Availability Zone and add per-zone routes as zones are added","Launch NAT instances from a hardened AMI in each Availability Zone with Elastic IP addresses","Create a regional NAT gateway in automatic mode and point all private route tables at its ID","Create an egress-only internet gateway and point all private route tables at its ID"], answer: 2, explanation: "A regional NAT gateway expands across Availability Zones automatically, needs no public subnet, and uses one ID in every route table. Zonal NAT gateways and NAT instances sit in public subnets and need per-zone work, while an egress-only internet gateway only handles IPv6 traffic.", domain: "saa2", section: "saa-27" },
  { id: "saa-q-035", question: "A bank runs critical workloads that depend on AWS Direct Connect. It needs maximum resiliency so that the failure of a device, a connection, or an entire Direct Connect location does not interrupt connectivity. Which design meets this requirement?", options: ["Separate connections terminating on separate devices in at least two Direct Connect locations","Two connections terminating on separate devices in a single Direct Connect location","A link aggregation group of four dedicated connections at a single Direct Connect location","Two hosted connections from the same partner at a single Direct Connect location"], answer: 0, explanation: "The AWS maximum resiliency model uses separate connections on separate devices in more than one Direct Connect location, so no single device, connection or location failure breaks connectivity. Any design that uses only one location, including a link aggregation group, still fails if that location goes down.", domain: "saa2", section: "saa-27" },
  { id: "saa-q-036", question: "A company has one AWS Direct Connect connection between its data center and a VPC. It wants a backup path in case the connection fails, and it accepts lower throughput on the backup path. Which solution is the MOST cost-effective?", options: ["Order a second Direct Connect connection at another location","Configure VPC peering between the VPC and a backup VPC","Deploy AWS Global Accelerator in front of the VPC resources","Set up an AWS Site-to-Site VPN connection as the backup path"], answer: 3, explanation: "A Site-to-Site VPN over the internet is quick and inexpensive to set up and can take over if the Direct Connect link fails. A second Direct Connect connection performs better but costs much more. VPC peering and Global Accelerator do not connect an on-premises data center to the VPC.", domain: "saa2", section: "saa-27" },
  { id: "saa-q-037", question: "A company has 40 VPCs across several accounts in one Region and a Site-to-Site VPN to its data center. Every VPC must reach the other VPCs and the data center. The current full mesh of VPC peering connections is hard to manage. Which solution is the MOST scalable?", options: ["Keep VPC peering and enable transitive routing through a central shared VPC","Attach the VPCs and the VPN to an AWS Transit Gateway shared through AWS RAM","Create a Direct Connect gateway and associate every VPC with it","Expose each VPC's services through AWS PrivateLink endpoint services"], answer: 1, explanation: "Transit Gateway is a regional hub with transitive routing between thousands of VPCs and on-premises VPN or Direct Connect links, and it can be shared across accounts with AWS Resource Access Manager. VPC peering is never transitive, a Direct Connect gateway does not route between VPCs, and PrivateLink exposes single services one way.", domain: "saa2", section: "saa-27" },
  { id: "saa-q-038", question: "A company connects its data center to AWS with a Site-to-Site VPN on a virtual private gateway. The VPN tunnels are saturated during nightly transfers, and AWS Direct Connect is not an option. How can the company increase VPN throughput to AWS?", options: ["Move the VPN to a transit gateway and use ECMP across multiple VPN tunnels","Add more VPN connections to the virtual private gateway to spread the load","Enable jumbo frames on the VPN tunnels so that each packet carries more data","Switch the customer gateway from BGP dynamic routing to static routing"], answer: 0, explanation: "A transit gateway supports equal-cost multipath routing across VPN tunnels, adding their bandwidth together, and also offers larger tunnels of up to five gigabits per second. A virtual private gateway does not use ECMP, VPN tunnels do not support jumbo frames, and ECMP requires BGP rather than static routing.", domain: "saa3", section: "saa-27" },
  { id: "saa-q-039", question: "A company has an AWS Direct Connect connection in us-east-1. It now also needs private connectivity from its data center to VPCs in us-west-2 and eu-west-1, without ordering new connections. What should a solutions architect use?", options: ["Inter-Region VPC peering from the us-east-1 VPC to the VPCs in the other Regions","A Direct Connect gateway associated with the virtual private gateway of each VPC","A Site-to-Site VPN from the us-east-1 virtual private gateway to the other Regions","A public virtual interface on the existing Direct Connect connection"], answer: 1, explanation: "A Direct Connect gateway is a global resource that lets one Direct Connect connection reach VPCs in many Regions through their virtual private gateways or transit gateways. Peering is not transitive, so on-premises traffic cannot pass through the us-east-1 VPC, and a public virtual interface reaches public AWS endpoints, not private VPC addresses.", domain: "saa3", section: "saa-27" },
  { id: "saa-q-040", question: "A SaaS provider must expose an API running in its VPC to hundreds of customer VPCs. Many customer VPCs use CIDR ranges that overlap with the provider's. Traffic must stay on the AWS network, and customers must not reach any other provider resources. Which solution meets these requirements?", options: ["Create a VPC peering connection from the provider VPC to each customer VPC","Attach the provider VPC and every customer VPC to a shared AWS Transit Gateway","Put the API behind a Network Load Balancer and publish it as a PrivateLink endpoint service","Put the API behind a public Application Load Balancer that allows only customer IP ranges"], answer: 2, explanation: "PrivateLink exposes one service through an interface endpoint in each consumer VPC, so overlapping CIDR ranges do not matter and consumers reach only that service. VPC peering and Transit Gateway need non-overlapping ranges and open broader network access, and a public load balancer sends traffic over the internet.", domain: "saa3", section: "saa-27" },
  { id: "saa-q-041", question: "An on-premises application connects to a VPC through AWS Direct Connect with a private virtual interface. The application must upload data to Amazon S3 using private IP addresses only, with no public internet path. Which solution meets this requirement?", options: ["Create a gateway VPC endpoint for S3 and route the on-premises traffic to it","Create a NAT gateway in the VPC and route on-premises S3 traffic through it","Enable S3 Transfer Acceleration and send requests to the accelerate endpoint","Create an interface VPC endpoint for S3 and send requests to its endpoint DNS name"], answer: 3, explanation: "Interface endpoints place private IP addresses in the VPC, so on-premises clients can reach S3 over Direct Connect or VPN. Gateway endpoints only work through VPC route tables and cannot be used from on-premises networks. NAT gateways and Transfer Acceleration use public S3 endpoints.", domain: "saa3", section: "saa-27" },
  { id: "saa-q-042", question: "A company runs dual-stack Amazon EC2 instances in a private subnet. The instances must download updates from IPv6 addresses on the internet, but nothing on the internet may start a connection to them over IPv6. What should be added to the route table for this IPv6 traffic?", options: ["A NAT gateway","An internet gateway","A virtual private gateway","An egress-only internet gateway"], answer: 3, explanation: "An egress-only internet gateway allows outbound IPv6 connections and blocks connections started from the internet, much like NAT does for IPv4. Amazon IPv6 addresses are public, so a regular internet gateway would allow inbound connections, and a NAT gateway is meant for IPv4 destinations.", domain: "saa3", section: "saa-27" },
  { id: "saa-q-043", question: "A network team wants to run ad hoc SQL queries on several months of VPC Flow Logs to find rejected connections. The solution must have the LEAST operational overhead and require no servers to manage. What should the team do?", options: ["Publish the flow logs to CloudWatch Logs and export them into Amazon RDS","Publish the flow logs to Amazon S3 and query them with Amazon Athena","Enable VPC Traffic Mirroring and analyze the packets on an EC2 fleet","Stream the flow logs through Amazon Data Firehose into a provisioned Amazon Redshift cluster"], answer: 1, explanation: "Flow logs delivered to S3 can be queried in place with Athena, which is serverless and charges per query. Redshift and RDS require provisioning and loading data, and Traffic Mirroring copies full packets for deep inspection instead of analyzing connection records.", domain: "saa3", section: "saa-27" },
  { id: "saa-q-044", question: "Amazon EC2 instances in private subnets send several terabytes per day to Amazon S3 in the same Region through a NAT gateway. The NAT gateway data processing charges are high. What is the MOST cost-effective way to reduce these charges?", options: ["Add an S3 gateway VPC endpoint to the private subnets' route tables","Replace the NAT gateway with a larger NAT instance in a public subnet","Create an S3 interface VPC endpoint in each of the private subnets","Enable S3 Transfer Acceleration on the destination S3 bucket"], answer: 0, explanation: "An S3 gateway endpoint has no hourly or data processing charge, and it takes S3 traffic off the NAT gateway. An interface endpoint also bypasses the NAT gateway but adds hourly and per-gigabyte charges. A NAT instance adds management work, and Transfer Acceleration adds cost.", domain: "saa4", section: "saa-27" },
  { id: "saa-q-045", question: "Two Amazon EC2 instances in the same Availability Zone exchange large amounts of data using each other's public IPv4 addresses. The finance team sees data transfer charges for this traffic. What should a solutions architect do to reduce the cost?", options: ["Assign Elastic IP addresses to both instances and use those addresses","Move one of the instances to another Availability Zone in the Region","Configure the instances to communicate using their private IP addresses","Route the traffic between the instances through a NAT gateway"], answer: 2, explanation: "Traffic between instances in the same Availability Zone is free when it uses private IP addresses, while traffic sent to public or Elastic IP addresses is charged as regional data transfer. Moving to another zone adds cross-zone charges, and a NAT gateway adds processing fees.", domain: "saa4", section: "saa-27" },
  { id: "saa-q-046", question: "A company has two VPCs in the same Region that exchange large volumes of data. No more VPCs will be added. The company needs private connectivity between the two VPCs at the LOWEST cost. Which solution should a solutions architect choose?", options: ["An AWS Transit Gateway with both VPCs attached","A VPC peering connection between the two VPCs","A Site-to-Site VPN between two virtual private gateways","AWS PrivateLink endpoint services in both of the VPCs"], answer: 1, explanation: "VPC peering has no hourly or data processing charge, and traffic that stays in one Availability Zone is free. Transit Gateway charges per attachment hour and per gigabyte processed, which pays off only when connecting many VPCs. PrivateLink adds endpoint charges and exposes single services only.", domain: "saa4", section: "saa-27" },
  { id: "saa-q-047", question: "A company needs encrypted connectivity between its office network and a VPC within one week. Bandwidth needs are modest and the budget is small. Which solution meets these requirements MOST cost-effectively?", options: ["An AWS Site-to-Site VPN connection over the internet","An AWS Direct Connect dedicated connection","An AWS Direct Connect hosted connection from a partner","An AWS Client VPN endpoint for every office user"], answer: 0, explanation: "Site-to-Site VPN can be set up in minutes over the existing internet link, is encrypted with IPsec, and costs little. Direct Connect often takes weeks to provision, costs more and is not encrypted by default. Client VPN connects individual users rather than a whole office network.", domain: "saa4", section: "saa-27" },
  { id: "saa-q-048", question: "An application running on Amazon EC2 instances must read objects from an Amazon S3 bucket in the same account. Which solution is the MOST secure way to give the application access?", options: ["Attach an IAM role with the required S3 permissions to the instances through an instance profile.","Create an IAM user, generate access keys, and store the keys in environment variables on each instance.","Create an IAM user, generate access keys, and run aws configure on each instance to save the keys.","Add a bucket policy that allows access from the public IP addresses of the EC2 instances."], answer: 0, explanation: "An instance profile delivers temporary, automatically rotated role credentials to the instance, so no long-term secrets exist. Storing IAM user access keys on instances, even in environment variables, creates long-lived credentials that can leak.", domain: "saa1", section: "saa-04" },
  { id: "saa-q-049", question: "A company lets developers create IAM roles for their AWS Lambda functions. The security team must guarantee that no role a developer creates can ever exceed a defined set of permissions, while other teams in the same account are unaffected. What should the security team use?", options: ["A service control policy attached to the account that contains the developers","IAM permissions boundaries that developers must attach to every role they create","An IAM Access Analyzer policy validation check run on each new role","An AWS Config rule that deletes roles with administrator permissions"], answer: 1, explanation: "A permissions boundary caps the maximum permissions an identity can have, so developer-created roles cannot escalate privileges. A service control policy applies to every principal in the account, which would also restrict the other teams.", domain: "saa1", section: "saa-25" },
  { id: "saa-q-050", question: "A company uses AWS Organizations. The security team must prevent every member account, including the root user of each member account, from stopping AWS CloudTrail logging or leaving the organization. Which solution meets these requirements?", options: ["Attach an IAM policy that denies these actions to the administrator groups in every account.","Attach a permissions boundary that denies these actions to every IAM role in every account.","Attach a service control policy that denies these actions to the root of the organization.","Deploy AWS Config rules with automatic remediation that re-enable CloudTrail logging."], answer: 2, explanation: "Service control policies limit every principal in member accounts, including their root users, and cannot be bypassed by account administrators. IAM policies and permissions boundaries cannot be applied to a root user and can be removed by local administrators.", domain: "saa1", section: "saa-25" },
  { id: "saa-q-051", question: "An Amazon S3 bucket must allow read access only to principals from accounts in the company’s AWS organization. New accounts are added to the organization every week. Which solution requires the LEAST ongoing maintenance?", options: ["Add a bucket policy that lists the account ID of every account in the organization as a principal.","Create an IAM role in each account and add each role ARN to the bucket policy as it is created.","Enable S3 Access Grants and create a grant for each new account when it joins the organization.","Add a bucket policy with an aws:PrincipalOrgID condition that matches the organization ID."], answer: 3, explanation: "The aws:PrincipalOrgID condition automatically covers every current and future account in the organization. Listing account IDs or role ARNs in the bucket policy needs an update every time an account is added.", domain: "saa1", section: "saa-25" },
  { id: "saa-q-052", question: "An IAM user in a member account of an AWS organization has the AdministratorAccess managed policy attached. No permissions boundary is set. The user receives an access denied error when creating an Amazon DynamoDB table. What is the MOST likely cause?", options: ["A service control policy on the account or its OU does not allow DynamoDB actions.","The user has not configured multi-factor authentication for console sign-in.","DynamoDB table creation requires a resource-based policy that names the user.","The AdministratorAccess policy excludes DynamoDB unless an inline policy is added."], answer: 0, explanation: "An action must be allowed by every applicable service control policy before identity policies matter, so an SCP can block even an administrator. AdministratorAccess grants all actions, and DynamoDB table creation needs no resource-based policy.", domain: "saa1", section: "saa-25" },
  { id: "saa-q-053", question: "A company’s public web application runs on EC2 instances in an Auto Scaling group behind an Application Load Balancer. The company wants to make the application more resilient to layer 7 DDoS attacks. Which combination of actions should a solutions architect take? (Choose TWO.)", options: ["Serve the application through an Amazon CloudFront distribution in front of the load balancer.","Enable Amazon GuardDuty to automatically block malicious traffic to the load balancer.","Add deny rules for attacking IP addresses to the security groups of the instances.","Associate an AWS WAF web ACL that has rate-based rules with the CloudFront distribution.","Enable Amazon Macie to monitor the load balancer access logs for attacks."], answer: [0,3], explanation: "CloudFront absorbs and spreads traffic across edge locations, and AWS WAF rate-based rules block floods of HTTP requests. GuardDuty only detects threats and does not block traffic, and security groups cannot contain deny rules.", domain: "saa2", section: "saa-26" },
  { id: "saa-q-054", question: "A process in Account A reads data from an Amazon DynamoDB table in Account A and must write the results to an Amazon S3 bucket in Account B. The process must keep its Account A permissions while it writes. Which solution meets these requirements?", options: ["Have the process assume an IAM role in Account B that has write access to the bucket.","Add a bucket policy in Account B that grants write access to the Account A role.","Enable S3 Cross-Region Replication from a bucket in Account A to the bucket in Account B.","Share the Account B bucket with Account A by using AWS Resource Access Manager."], answer: 1, explanation: "With a resource-based policy the principal keeps its own permissions while accessing the other account’s bucket. Assuming a role in Account B would give up the Account A permissions needed to read DynamoDB for the duration of the session.", domain: "saa1", section: "saa-25" },
  { id: "saa-q-055", question: "A company has 40 AWS accounts in AWS Organizations and uses Microsoft Entra ID for workforce identities. Employees need single sign-on to the AWS accounts with centrally managed permission levels per account. Which solution requires the LEAST operational overhead?", options: ["Create IAM users in each account and synchronize their passwords with Entra ID.","Configure a SAML identity provider and IAM roles separately in each of the 40 accounts.","Use IAM Identity Center with Entra ID as the identity source and assign permission sets.","Deploy AWS Managed Microsoft AD and create a forest trust with Entra ID."], answer: 2, explanation: "IAM Identity Center federates with an external identity provider once and pushes permission sets to any account in the organization. Configuring SAML federation in each account separately works but multiplies setup and maintenance.", domain: "saa1", section: "saa-25" },
  { id: "saa-q-056", question: "A company runs Windows applications on Amazon EC2 that must authenticate users with their existing on-premises Active Directory credentials. Authentication in AWS must keep working if the connection to the on-premises data center is lost. Which solution meets these requirements?", options: ["Deploy AD Connector in the VPC and point it to the on-premises domain controllers.","Deploy Simple AD in the VPC and import the on-premises user accounts.","Deploy AWS Managed Microsoft AD and create a trust with the on-premises domain.","Extend the on-premises domain with domain controllers on EC2 in two Availability Zones."], answer: 3, explanation: "Domain controllers for the same domain running in AWS hold replicated copies of the user accounts, so sign-ins continue during an outage. AD Connector is only a proxy, and a trust with a separate directory still sends on-premises users back to on-premises controllers.", domain: "saa2", section: "saa-25" },
  { id: "saa-q-057", question: "A company is starting a multi-account environment. It wants a preconfigured landing zone with account vending, centralized logging, preventive and detective guardrails, and a dashboard showing compliance. Which solution requires the LEAST operational overhead?", options: ["Set up AWS Control Tower and enable the required controls.","Create accounts with AWS Organizations and write custom service control policies.","Deploy AWS Config conformance packs in each account with AWS CloudFormation StackSets.","Use AWS Firewall Manager to apply security policies to every new account."], answer: 0, explanation: "Control Tower builds a well-architected landing zone automatically and applies controls that use service control policies and AWS Config, with a compliance dashboard. Building the same thing from Organizations and custom policies is far more work.", domain: "saa1", section: "saa-25" },
  { id: "saa-q-058", question: "A finance team cannot allocate AWS costs because teams tag resources inconsistently, for example CostCenter, costcenter, and cost-center. The company uses AWS Organizations. How can the company standardize tag keys and values across all accounts?", options: ["Activate AWS generated cost allocation tags in the Billing console.","Create tag policies in AWS Organizations and attach them to the relevant OUs.","Use AWS Resource Groups to regroup resources with inconsistent tags.","Create a budget in AWS Budgets that filters on each tag variation."], answer: 1, explanation: "Tag policies define the allowed tag keys, capitalization and values across the organization and report noncompliant resources, fixing cost allocation at the source. AWS generated tags only add creator tags and do not standardize the ones teams apply.", domain: "saa4", section: "saa-25" },
  { id: "saa-q-059", question: "A security team must automatically find software vulnerabilities in EC2 instances and container images in Amazon ECR. The team must also discover personally identifiable information stored in Amazon S3 buckets. Which services should the team use? (Choose TWO.)", options: ["Amazon GuardDuty","Amazon Inspector","Amazon Detective","AWS Trusted Advisor","Amazon Macie"], answer: [1,4], explanation: "Inspector continuously scans EC2 instances, ECR images and Lambda functions for known vulnerabilities, and Macie uses machine learning to discover sensitive data in S3. GuardDuty detects threats from logs rather than scanning for vulnerabilities or personal data.", domain: "saa1", section: "saa-26" },
  { id: "saa-q-060", question: "An application must encrypt 200 MB files with a customer managed AWS KMS key before storing them on premises. Calls to the KMS Encrypt API fail for these files. What should a solutions architect recommend?", options: ["Request a service quota increase for the maximum payload size of the Encrypt API.","Split each file into small chunks and call the Encrypt API once for every chunk.","Use envelope encryption with a data key from GenerateDataKey to encrypt locally.","Replace the customer managed key with an AWS managed key that supports larger payloads."], answer: 2, explanation: "The KMS Encrypt API only accepts a few kilobytes of data. Envelope encryption uses a KMS-protected data key to encrypt the file locally. Chunking would be slow, costly and throttled, and no key type raises the payload limit.", domain: "saa1", section: "saa-26" },
  { id: "saa-q-061", question: "A company uses Amazon DynamoDB global tables in two Regions and encrypts sensitive attributes on the client side. Applications in each Region must decrypt data locally with the lowest latency, without calling KMS in another Region. Which solution meets these requirements?", options: ["Create a separate single-Region KMS key in each Region and share them by key policy.","Use the AWS owned key that DynamoDB uses for default encryption at rest.","Store a copy of the key material in AWS Secrets Manager in each Region.","Use an AWS KMS multi-Region key with a replica key in each Region."], answer: 3, explanation: "Multi-Region keys share the same key ID and key material, so data encrypted in one Region can be decrypted locally in another. Separate single-Region keys have different material and cannot decrypt each other’s data.", domain: "saa3", section: "saa-26" },
  { id: "saa-q-062", question: "A company must share an AMI with a partner account. The AMI’s snapshots are encrypted with a customer managed AWS KMS key. What must the company do so the partner can launch instances from the AMI?", options: ["Grant the partner account AMI launch permission and use of the KMS key in its key policy.","Add the partner account to the AMI launch permissions and make the snapshots public.","Copy the AMI with the AWS managed key for Amazon EBS and share the new copy.","Export the KMS key material and import it into a new key in the partner account."], answer: 0, explanation: "The partner needs both launch permission on the AMI and permission to use the customer managed key that encrypted it. AWS managed keys cannot be shared across accounts, and encrypted snapshots cannot be made public.", domain: "saa1", section: "saa-26" },
  { id: "saa-q-063", question: "An application needs to store about 300 configuration values, including some encrypted API endpoints. Values are under 4 KB, change rarely, and do not need automatic rotation. Which solution is the MOST cost-effective?", options: ["AWS Secrets Manager, with one secret for each configuration value","Parameter Store standard parameters, with SecureString for encrypted values","Parameter Store advanced parameters, with parameter policies for expiration","An Amazon DynamoDB table encrypted with a customer managed KMS key"], answer: 1, explanation: "Standard parameters have no storage charge, hold values up to 4 KB, and SecureString encrypts values with KMS. Secrets Manager charges per secret per month and is only worth it when you need its built-in rotation. Advanced parameters add a charge.", domain: "saa4", section: "saa-26" },
  { id: "saa-q-064", question: "A company stores the master credentials for an Amazon RDS for MySQL database in application configuration. A new policy requires the password to be rotated automatically every 30 days. Which solution requires the LEAST operational overhead?", options: ["Store the credentials in Parameter Store and schedule a Lambda function to change them.","Store the credentials in an encrypted S3 object and rotate them with an EventBridge rule.","Store the credentials in AWS Secrets Manager and enable automatic rotation.","Use AWS KMS automatic key rotation for the key that encrypts the credentials."], answer: 2, explanation: "Secrets Manager has built-in rotation for Amazon RDS that updates both the secret and the database password on a schedule. Parameter Store has no built-in rotation, and KMS key rotation changes the encryption key, not the database password.", domain: "saa1", section: "saa-26" },
  { id: "saa-q-065", question: "A third-party monitoring vendor needs read-only access to resources in a company’s AWS account. The vendor serves many customers from its own AWS account. Which combination of steps provides access MOST securely? (Choose TWO.)", options: ["Create an IAM role in the company account with a trust policy that allows the vendor’s account.","Create an IAM user for the vendor and provide long-term access keys.","Require a unique external ID in the role trust policy condition.","Invite the vendor’s account to join the company’s AWS organization.","Attach a permissions boundary to the vendor’s account root user."], answer: [0,2], explanation: "A cross-account role gives the vendor temporary credentials, and a unique external ID prevents the confused deputy problem where another vendor customer tricks the vendor into using your role. Long-term access keys for an IAM user are harder to secure and rotate.", domain: "saa1", section: "saa-25" },
  { id: "saa-q-066", question: "A company serves a website through an Amazon CloudFront distribution with a custom domain name, and its origin is an Application Load Balancer in eu-west-1. Where must the company request the AWS Certificate Manager certificate that is attached to the distribution?", options: ["In eu-west-1, the Region where the origin runs","In any Region, because ACM certificates are global","In each edge location that serves the distribution","In the US East (N. Virginia) Region, us-east-1"], answer: 3, explanation: "CloudFront only accepts ACM certificates from us-east-1, regardless of where the origin runs. The load balancer itself would need its own certificate in eu-west-1, which is the tempting but wrong choice for the distribution.", domain: "saa1", section: "saa-26" },
  { id: "saa-q-067", question: "A regulated company must store its encryption keys in dedicated, single-tenant hardware security modules. The company must have exclusive control of the keys, and AWS must have no access to them. Which service meets these requirements?", options: ["AWS CloudHSM","AWS KMS with customer managed keys","AWS KMS with imported key material","AWS Secrets Manager with a customer managed key"], answer: 0, explanation: "CloudHSM gives you single-tenant hardware security modules in your VPC where only your users manage the keys. KMS, even with imported key material, is a multi-tenant managed service where AWS operates the hardware and key usage is controlled through KMS.", domain: "saa1", section: "saa-26" },
  { id: "saa-q-068", question: "A public web application behind an Application Load Balancer is receiving SQL injection attempts and bursts of requests from a small number of IP addresses. Which solution addresses both issues with the LEAST operational overhead?", options: ["Update the load balancer security group to deny the offending IP addresses and SQL keywords.","Associate an AWS WAF web ACL with a SQL injection rule group and a rate-based rule.","Enable Amazon GuardDuty and create an EventBridge rule that blocks the offending IP addresses.","Add network ACL deny rules for the offending IP addresses and enable AWS Shield Standard."], answer: 1, explanation: "AWS WAF inspects HTTP requests, so managed rules block SQL injection and a rate-based rule throttles noisy IP addresses automatically. Security groups cannot deny traffic or inspect request content, and network ACLs cannot see SQL payloads.", domain: "saa1", section: "saa-26" },
  { id: "saa-q-069", question: "A company’s revenue-critical application runs on CloudFront, Application Load Balancers, and Amazon EC2 Auto Scaling. The company wants help from AWS DDoS experts during attacks and protection from scaling charges caused by DDoS traffic. What should the company use?", options: ["AWS Shield Standard","AWS WAF with managed rule groups","AWS Shield Advanced","Amazon GuardDuty with Extended Threat Detection"], answer: 2, explanation: "Shield Advanced adds access to the Shield Response Team and cost protection that credits scaling charges caused by DDoS attacks. Shield Standard is free and automatic but provides neither expert response nor cost protection.", domain: "saa2", section: "saa-26" },
  { id: "saa-q-070", question: "A security team wants continuous detection of compromised EC2 instances, such as instances communicating with known malicious IP addresses or mining cryptocurrency. The solution must not require installing agents. Which service should the team enable?", options: ["Amazon Inspector","Amazon Macie","Amazon Detective","Amazon GuardDuty"], answer: 3, explanation: "GuardDuty uses machine learning and threat intelligence on CloudTrail events, VPC Flow Logs and DNS logs to flag threats such as crypto mining. Inspector finds software vulnerabilities and exposure, not active threats, and Detective investigates findings after the fact.", domain: "saa1", section: "saa-26" },
  { id: "saa-q-071", question: "A company runs a web application on EC2 instances behind an Application Load Balancer. A new policy requires client traffic to be encrypted in transit with a certificate that renews automatically, and every new EBS volume to be encrypted at rest. Which combination of steps meets these requirements with the LEAST operational overhead? (Choose TWO.)", options: ["Store a purchased certificate in AWS Secrets Manager and install it on each instance.","Request a public certificate in AWS Certificate Manager and add an HTTPS listener to the load balancer.","Store the certificate private key in AWS CloudHSM and load it into the load balancer.","Turn on Amazon EBS encryption by default in each Region that the account uses.","Create an AWS Config rule that reports unencrypted EBS volumes after they are created."], answer: [1,3], explanation: "Public ACM certificates on a load balancer renew automatically, and EBS encryption by default encrypts every new volume in that Region. Certificates installed on instances must be renewed by hand, and a Config rule only reports unencrypted volumes after they already exist.", domain: "saa1", section: "saa-26" },
  { id: "saa-q-072", question: "An application uploads millions of small objects per hour to an Amazon S3 bucket that uses SSE-KMS with a customer managed key. Uploads intermittently fail with KMS throttling errors. Which change reduces the number of requests to AWS KMS?", options: ["Enable S3 Bucket Keys for the bucket.","Enable automatic rotation for the customer managed key.","Replace the key with a KMS multi-Region key.","Switch the bucket default encryption to DSSE-KMS."], answer: 0, explanation: "An S3 Bucket Key generates a bucket-level key that creates data keys locally, cutting KMS requests and cost dramatically. Key rotation and multi-Region keys do not reduce request volume, and dual-layer encryption with KMS still calls KMS for every object.", domain: "saa3", section: "saa-26" },
  { id: "saa-q-073", question: "A team launched Spot Instances from a persistent Spot request. Every time the team terminates the instances, new Spot Instances launch to replace them. How should the team stop these instances permanently?", options: ["Terminate the instances first, then cancel the Spot request","Change the interruption behavior to terminate, then terminate the instances","Cancel the Spot request first, then terminate the instances","Stop the instances, then lower the maximum price of the Spot request"], answer: 2, explanation: "A persistent Spot request keeps relaunching capacity while it stays open, and cancelling it does not terminate running instances. So cancel the request first, then terminate the instances. Terminating first only lets the still-open request launch replacements.", domain: "saa4", section: "saa-05" },
  { id: "saa-q-074", question: "A company runs a steady web tier on Amazon EC2 around the clock and expects this usage for at least 3 years. Over that time it plans to move to newer instance families and shift part of the workload to AWS Fargate. Which purchasing option is the MOST cost-effective while supporting these changes?", options: ["EC2 Instance Savings Plan with a 3-year term","Compute Savings Plan with a 3-year term","Convertible Reserved Instances with a 3-year term","Standard Reserved Instances with a 3-year term"], answer: 1, explanation: "A Compute Savings Plan applies automatically across instance families, sizes, Regions, and operating systems, and also covers Fargate and Lambda. Convertible Reserved Instances allow family exchanges but never cover Fargate. EC2 Instance Savings Plans and Standard Reserved Instances stay locked to one instance family, so they cannot follow the planned changes.", domain: "saa4", section: "saa-05" },
  { id: "saa-q-075", question: "A company is migrating a commercial database product to Amazon EC2. The vendor licenses the software per physical CPU socket and core, and the company wants to bring its existing licenses. Which EC2 option should a solutions architect choose?", options: ["Dedicated Instances in a dedicated-tenancy VPC","On-Demand Instances with shared tenancy","Spot Instances with a persistent request","Dedicated Hosts allocated to the account"], answer: 3, explanation: "Dedicated Hosts give you an entire physical server with visibility into its sockets and cores, which per-socket and per-core bring your own license terms require. Dedicated Instances also run on single-tenant hardware, but you cannot see or control the underlying sockets and cores, so they do not satisfy these licenses.", domain: "saa4", section: "saa-05" },
  { id: "saa-q-076", question: "A company has two workloads on Amazon EC2. A nightly image-rendering job is fault tolerant, checkpoints its progress, and can restart at any time. A self-managed database runs continuously on the same instance type in one Region and will for the next 3 years. Which TWO purchasing options are the MOST cost-effective? (Choose TWO.)", options: ["Spot Instances for the rendering job","On-Demand Capacity Reservations for the rendering job","Dedicated Hosts for the database","3-year Standard Reserved Instances for the database","On-Demand Instances for the database"], answer: [0,3], explanation: "Spot Instances give the deepest discount, up to 90 percent, and suit interruptible, checkpointed jobs. A database running nonstop on a fixed instance type for 3 years fits 3-year Standard Reserved Instances. Capacity Reservations and On-Demand bill at full On-Demand rates, and Dedicated Hosts add cost without any licensing need.", domain: "saa4", section: "saa-05" },
  { id: "saa-q-077", question: "A research team runs a tightly coupled high performance computing simulation on dozens of EC2 instances. The nodes exchange data constantly and need the lowest possible network latency and the highest throughput between them. Which configuration should a solutions architect use?", options: ["Launch the instances in a cluster placement group in one Availability Zone","Launch the instances in a spread placement group across three Availability Zones","Launch the instances in a partition placement group across two Availability Zones","Launch the instances in an Auto Scaling group that spans every Availability Zone"], answer: 0, explanation: "A cluster placement group packs instances close together inside one Availability Zone, giving the lowest latency and highest per-flow throughput between nodes. Spread and partition groups separate instances across hardware for resilience, and spanning Availability Zones adds latency, which is the opposite of what tightly coupled computing needs.", domain: "saa3", section: "saa-06" },
  { id: "saa-q-078", question: "A company is deploying a 90-node Apache Cassandra cluster on Amazon EC2. The architect wants to limit the impact of a rack failure and let the database place replicas based on which hardware group each node runs on. Which placement strategy meets these requirements?", options: ["A cluster placement group in a single Availability Zone","A spread placement group across three Availability Zones","A partition placement group across three Availability Zones","Instances on Dedicated Hosts with no placement group"], answer: 2, explanation: "Partition placement groups split instances into partitions that never share racks, support hundreds of instances, and expose the partition number through instance metadata, so topology-aware systems like Cassandra, HDFS, and Kafka can place replicas. A spread group allows only seven running instances per Availability Zone, far too few for 90 nodes.", domain: "saa2", section: "saa-06" },
  { id: "saa-q-079", question: "A legacy application runs on a single EC2 instance, and its software license is tied to a MAC address. The company keeps a standby instance running in the same Availability Zone and wants to fail over quickly without requesting a new license. What should a solutions architect do?", options: ["Reassociate the Elastic IP address of the failed instance with the standby instance","Tie the license to a secondary elastic network interface and move it to the standby","Create an AMI of the failed instance and launch a replacement in another Availability Zone","Register both instances with a Network Load Balancer that routes around failed health checks"], answer: 1, explanation: "An elastic network interface keeps its MAC address, private IP, and security groups when it moves to another instance in the same Availability Zone, so the license follows it. Moving an Elastic IP changes only the public address, and a new instance or load balancer target has a different MAC address.", domain: "saa2", section: "saa-06" },
  { id: "saa-q-080", question: "A company runs analytics workers on Linux EC2 instances with 64 GiB of RAM. Each worker spends 20 minutes loading a large in-memory dataset after boot. The company wants to stop the instances overnight and have them resume the next morning with memory intact. Which TWO configurations are required? (Choose TWO.)", options: ["Use an instance store volume as the root volume","Use an encrypted Amazon EBS root volume","Launch the instances in a cluster placement group","Attach an Elastic IP address to each instance","Enable hibernation when the instances are launched"], answer: [1,4], explanation: "Hibernation saves RAM to the root volume, so the root must be an encrypted EBS volume large enough to hold memory, and hibernation can only be enabled at launch. Instance store data is lost when an instance stops, and placement groups or Elastic IP addresses do nothing to preserve memory.", domain: "saa3", section: "saa-06" },
  { id: "saa-q-081", question: "A company is moving a critical OLTP database to a single Nitro-based EC2 instance. The database volume needs 180,000 sustained IOPS with consistent sub-millisecond latency, and the data must persist when the instance is stopped. Which storage option meets these requirements?", options: ["An Amazon EBS gp3 General Purpose SSD volume","An Amazon EBS io1 Provisioned IOPS SSD volume","Amazon EC2 instance store NVMe volumes","An Amazon EBS io2 Block Express volume"], answer: 3, explanation: "io2 Block Express supports up to 256,000 IOPS per volume with sub-millisecond latency and 99.999 percent durability. gp3 now tops out at 80,000 IOPS and io1 at 64,000, so neither reaches 180,000. Instance store is very fast but loses its data when the instance stops.", domain: "saa3", section: "saa-07" },
  { id: "saa-q-082", question: "A log processing application on Amazon EC2 reads large files sequentially every hour. The workload needs high throughput rather than high IOPS, and the data set is 8 TiB. Which EBS volume type is the MOST cost-effective?", options: ["st1 Throughput Optimized HDD","sc1 Cold HDD","gp3 General Purpose SSD","io2 Block Express Provisioned IOPS SSD"], answer: 0, explanation: "st1 is built for frequently accessed, throughput-heavy sequential workloads such as big data and log processing, at a far lower cost per gigabyte than SSD volumes. sc1 is cheaper but intended for infrequently accessed data, and this data is read every hour. gp3 and io2 charge for IOPS performance the job does not need.", domain: "saa4", section: "saa-07" },
  { id: "saa-q-083", question: "A video processing application on Amazon EC2 writes large temporary scratch files that need the highest possible random read and write performance. If the files are lost, they can be regenerated from source data in Amazon S3. Which storage option provides the BEST performance for the scratch space?", options: ["An Amazon EFS file system using Elastic throughput","An Amazon EBS gp3 volume with maximum provisioned IOPS","Instance store volumes on a storage optimized instance","An Amazon EBS st1 volume sized for maximum throughput"], answer: 2, explanation: "Instance store disks are physically attached to the host, delivering very high IOPS and low latency at no extra charge. They lose data on stop or termination, which is acceptable here because the files can be rebuilt from S3. EBS and EFS are network-attached storage, so they add latency.", domain: "saa3", section: "saa-07" },
  { id: "saa-q-084", question: "An application runs on an EC2 instance in one Availability Zone and stores its data on a 500 GiB EBS volume. The company must move the workload to a new instance in a different Availability Zone in the same Region and keep the data. What should a solutions architect do?", options: ["Detach the volume and attach it to the new instance in the other zone","Enable Multi-Attach on the volume and attach it to both instances","Modify the volume and change its Availability Zone to the new zone","Create a snapshot and restore it as a new volume in the other zone"], answer: 3, explanation: "EBS volumes are locked to the Availability Zone where they were created. A snapshot is stored at the Regional level, so it can be restored as a new volume in any Availability Zone of that Region. Multi-Attach works only within a single zone, and a volume cannot be moved to another zone.", domain: "saa2", section: "saa-07" },
  { id: "saa-q-085", question: "A security audit found an unencrypted Amazon EBS data volume attached to a production EC2 instance. The volume must be encrypted with an AWS KMS key. What should a solutions architect do?", options: ["Snapshot the volume, create an encrypted volume from the snapshot, and swap it in","Modify the existing volume in place to turn on encryption with the KMS key","Turn on EBS encryption by default so the attached volume becomes encrypted","Create an AMI of the instance, which encrypts the attached data volume by default"], answer: 0, explanation: "An existing unencrypted volume cannot be encrypted in place. Take a snapshot, create a new volume from it with encryption and the KMS key selected, or copy the snapshot with encryption, then attach the new volume. Encryption by default applies only to volumes created afterwards.", domain: "saa1", section: "saa-07" },
  { id: "saa-q-086", question: "A company runs a content management system on Linux EC2 instances in an Auto Scaling group across three Availability Zones. All instances must read and write the same uploaded files, and the storage must stay available if one Availability Zone fails. Which storage solution meets these requirements?", options: ["An Amazon EBS io2 volume with Multi-Attach enabled","An Amazon EFS file system with mount targets in each zone","Instance store volumes kept in sync by a cron job","An Amazon EBS gp3 volume shared by the Auto Scaling group"], answer: 1, explanation: "Amazon EFS is a managed NFS file system that many Linux instances in multiple Availability Zones can mount at once, and a Regional EFS file system stores data redundantly across zones. EBS Multi-Attach works only inside one Availability Zone, and instance store data is lost when instances stop.", domain: "saa2", section: "saa-07" },
  { id: "saa-q-087", question: "A development team stores build artifacts on an Amazon EFS file system. Most files are never read again after a few weeks, and the environment does not need to survive the loss of an Availability Zone. Which TWO actions will reduce storage cost the MOST? (Choose TWO.)", options: ["Switch the file system to Provisioned throughput mode","Change the performance mode to Max I/O","Enable lifecycle management to move files to EFS Infrequent Access","Add a mount target in every Availability Zone","Recreate the data on an EFS One Zone file system"], answer: [2,4], explanation: "Lifecycle management automatically moves files that have not been accessed for a set period into the cheaper Infrequent Access class, and One Zone file systems cost less than Regional ones when multi-zone resilience is not required. Provisioned throughput adds charges, and changing performance mode or adding mount targets does not lower storage prices.", domain: "saa4", section: "saa-07" },
  { id: "saa-q-088", question: "An administrator accidentally deleted several Amazon EBS snapshots that were needed for recovery. The company wants to be able to recover deleted snapshots for up to 30 days, with the LEAST operational overhead. Which solution meets this requirement?", options: ["Move all snapshots to the EBS Snapshots Archive tier","Enable Fast Snapshot Restore on the important snapshots","Create a Recycle Bin retention rule for EBS snapshots","Copy every snapshot to a second Region each night"], answer: 2, explanation: "A Recycle Bin retention rule keeps deleted snapshots recoverable for a period you choose, from 1 day to 1 year, with no scripts to maintain. Snapshots Archive lowers storage cost and Fast Snapshot Restore speeds up new volumes, but neither protects against deletion. Nightly cross-Region copies add cost and effort.", domain: "saa1", section: "saa-07" },
  { id: "saa-q-089", question: "A company builds a hardened golden AMI in its primary AWS Region. For disaster recovery, it must be able to launch identical instances in a second Region. What should a solutions architect do?", options: ["Copy the AMI to the second Region and launch instances from the copy","Launch instances in the second Region using the original AMI ID","Modify the AMI launch permissions to include the second Region","Attach the root snapshot of the AMI to an instance in the second Region"], answer: 0, explanation: "AMIs are Regional resources, so the image must be copied to the second Region, which creates a new AMI ID there. An AMI ID from one Region cannot be used in another, launch permissions share an AMI with accounts rather than Regions, and snapshots cannot be attached across Regions.", domain: "saa2", section: "saa-07" },
  { id: "saa-q-090", question: "A company stores sensitive files on an Amazon EFS file system that is mounted by application servers in an Auto Scaling group. Only these application servers may connect to the file system over the network. What should a solutions architect do?", options: ["Allow NFS on port 2049 in the mount target security group from the app servers’ security group","Allow NFS on port 2049 in the mount target security group from the VPC CIDR range","Turn on encryption at rest for the file system with an AWS KMS key","Allow SSH on port 22 in the mount target security group from the app servers’ security group"], answer: 0, explanation: "EFS mount targets are protected by security groups. Allowing NFS on port 2049 only from the application servers’ security group limits access to those instances even as the group scales. The VPC range admits every host in the VPC, encryption at rest does not control who connects, and EFS uses NFS, not SSH.", domain: "saa1", section: "saa-07" },
  { id: "saa-q-091", question: "A web application runs on EC2 instances behind an internet-facing Application Load Balancer. The security team requires that the instances accept HTTP traffic only from the load balancer. Which configuration meets this requirement?", options: ["Allow inbound HTTP to the instances from any IPv4 address","Allow HTTP in a network ACL rule that names the load balancer DNS name","Allow inbound HTTP from the Elastic IP addresses of the load balancer","Allow inbound HTTP from the load balancer’s security group"], answer: 3, explanation: "Referencing the load balancer’s security group in the instance security group admits traffic only from load balancer nodes, even as their IP addresses change. Application Load Balancers have no fixed Elastic IP addresses, network ACLs cannot use DNS names, and opening HTTP to any address ignores the requirement.", domain: "saa1", section: "saa-08" },
  { id: "saa-q-092", question: "A company hosts three websites with different domain names, such as example.com and example.org, on one fleet of EC2 instances. Each site must use its own TLS certificate, and the company wants a single load balancer. Which solution meets these requirements?", options: ["A Classic Load Balancer with one HTTPS listener holding all three certificates","An Application Load Balancer with one HTTPS listener and three certificates using SNI","An Application Load Balancer with one wildcard certificate covering all three domains","A Gateway Load Balancer that terminates TLS with a certificate for each domain"], answer: 1, explanation: "Server Name Indication lets an Application or Network Load Balancer choose the right certificate for each hostname on one listener. A wildcard certificate covers subdomains of a single domain, not different domains. Classic Load Balancers support only one certificate per listener, and Gateway Load Balancers do not terminate TLS.", domain: "saa1", section: "saa-08" },
  { id: "saa-q-093", question: "A company must send all inbound traffic for its VPC through a fleet of third-party firewall appliances for deep packet inspection. The appliance fleet must scale out and stay highly available, and the inspection must be transparent to the applications. Which solution meets these requirements with the LEAST operational overhead?", options: ["Place the appliances behind a Network Load Balancer with TLS listeners","Place the appliances behind a Gateway Load Balancer with endpoints in the VPC","Place the appliances behind an Application Load Balancer with path rules","Run the appliances in an Auto Scaling group with scripted route updates"], answer: 1, explanation: "Gateway Load Balancer works at the network layer, using the GENEVE protocol on port 6081 to pass IP packets transparently through a scalable, health-checked fleet of virtual appliances, with its endpoints as route targets. Application and Network Load Balancers serve applications rather than insert inspection into the traffic path, and scripted routes add operational overhead.", domain: "saa1", section: "saa-08" },
  { id: "saa-q-094", question: "A partner will only allow connections to a company’s trading API from IP addresses on its firewall allow list. The API uses TCP, must handle millions of requests per second with ultra-low latency, and runs on EC2 instances in two Availability Zones. Which solution meets these requirements?", options: ["An Application Load Balancer, sharing its DNS name with the partner","A Gateway Load Balancer with endpoints in each Availability Zone","A Network Load Balancer with an Elastic IP in each Availability Zone","An Application Load Balancer with an Elastic IP in each Availability Zone"], answer: 2, explanation: "A Network Load Balancer operates at layer 4, handles millions of requests per second with very low latency, and provides one static IP per Availability Zone, which can be an Elastic IP. Application Load Balancers cannot use Elastic IPs and their addresses change, so a firewall allow list would break.", domain: "saa3", section: "saa-08" },
  { id: "saa-q-095", question: "A web application runs on EC2 instances in an Auto Scaling group behind an Application Load Balancer. Some instances fail the load balancer health check when the application hangs, but the Auto Scaling group does not replace them. Also, users uploading large files lose their connections when instances are removed during scale-in. Which TWO actions will resolve these issues? (Choose TWO.)", options: ["Enable cross-zone load balancing on the target group","Turn on Elastic Load Balancing health checks for the Auto Scaling group","Enable duration-based sticky sessions on the target group","Increase the deregistration delay on the target group","Shorten the scaling cooldown period to 60 seconds"], answer: [1,3], explanation: "By default an Auto Scaling group uses only EC2 status checks, so turning on Elastic Load Balancing health checks makes it replace instances the load balancer reports as unhealthy. Deregistration delay, also called connection draining, lets in-flight requests finish before an instance is removed. Stickiness, cross-zone balancing, and cooldown address neither problem.", domain: "saa2", section: "saa-08" },
  { id: "saa-q-096", question: "An online learning platform on EC2 has a daily traffic pattern: load climbs sharply every weekday morning and drops at night. The pattern repeats reliably but shifts gradually over the semester. Instances take several minutes to initialize, and the company wants capacity in place before the load arrives without maintaining schedules by hand. Which scaling approach meets these requirements?", options: ["A target tracking policy on average CPU utilization","Scheduled actions that an administrator updates weekly","A step scaling policy triggered by CloudWatch alarms","A predictive scaling policy based on historical load"], answer: 3, explanation: "Predictive scaling uses machine learning on historical metrics to forecast recurring daily and weekly patterns and launches capacity ahead of demand, adapting as the pattern shifts. Scheduled actions also scale ahead but must be maintained by hand, while target tracking and step scaling only react after load has already increased.", domain: "saa3", section: "saa-08" },
  { id: "saa-q-097", question: "A company hosts its website on an Application Load Balancer and uses Amazon Route 53 for DNS. Users must be able to reach the site at the root domain, example.com, and not only at www.example.com. Which Route 53 record meets this requirement?", options: ["A CNAME record for example.com that points to the load balancer DNS name","An A record for example.com that lists the load balancer's current IP addresses","An alias A record for example.com that targets the load balancer","An NS record for example.com that delegates to the load balancer"], answer: 2, explanation: "An alias record can be created at the zone apex and automatically follows the load balancer's changing IP addresses. A CNAME record is not allowed at the zone apex, and hardcoded load balancer IP addresses break when they change.", domain: "saa3", section: "saa-10" },
  { id: "saa-q-098", question: "A company has dozens of subdomains in Route 53, each a CNAME record that points to the same Amazon CloudFront distribution. The records already use a 24-hour TTL, but DNS query charges keep growing with traffic. Which change will MOST reduce the Route 53 query cost?", options: ["Replace each CNAME record with an alias record for the distribution","Lower the TTL on every CNAME record from 24 hours to 60 seconds","Convert the records to multivalue answer routing with health checks","Move the CNAME records into a private hosted zone in the same account"], answer: 0, explanation: "Route 53 does not charge for alias queries that resolve to AWS resources such as a CloudFront distribution, so switching to alias records removes those query charges. Lowering the TTL does the opposite, because resolvers would query Route 53 more often.", domain: "saa4", section: "saa-10" },
  { id: "saa-q-099", question: "A company runs its web application behind an Application Load Balancer in us-east-1. If the application becomes unhealthy, users must automatically be sent to a static maintenance page hosted as an Amazon S3 static website. Which Route 53 configuration meets this requirement?", options: ["Latency routing, with one record for the load balancer and one for the S3 website endpoint","Multivalue answer routing, with health checks on the load balancer and S3 website records","Simple routing, with a single record that contains both the load balancer and the S3 website","Failover routing, with a health check on the load balancer and the S3 website as secondary"], answer: 3, explanation: "Failover routing is active-passive. Route 53 answers with the primary record while its health check passes and switches to the secondary when it fails. Multivalue routing would hand out the maintenance page even while the application is healthy, and simple routing cannot use health checks.", domain: "saa2", section: "saa-10" },
  { id: "saa-q-100", question: "A company uses Route 53 failover routing for an internal application. The application endpoints run in private subnets and are not reachable from the internet. How should the company monitor the health of the primary endpoint so that failover works?", options: ["Create an HTTP health check that targets the private IP address of the primary endpoint","Allow the Route 53 health checker IP ranges in the security group of the endpoint","Create a CloudWatch alarm on an application metric and a health check that monitors it","Create a calculated health check that combines TCP checks of each private endpoint"], answer: 2, explanation: "Route 53 health checkers run on the public internet and cannot reach private endpoints. Instead, publish a CloudWatch metric, create an alarm, and base the health check on that alarm. Opening the security group to health checker IP ranges does not help when there is no public path.", domain: "saa2", section: "saa-10" },
  { id: "saa-q-101", question: "A company deploys identical application stacks in us-east-1, eu-west-1, and ap-southeast-1. Users around the world should be directed to whichever stack gives them the fastest response time. Which Route 53 routing policy should a solutions architect use?", options: ["Latency-based routing","Geolocation routing","Geoproximity routing","Weighted routing"], answer: 0, explanation: "Latency-based routing answers with the Region that has the lowest measured network latency for each user. Geolocation and geoproximity route by where users are, which suits compliance rules or shifting traffic, but the closest Region is not always the fastest one.", domain: "saa3", section: "saa-10" },
  { id: "saa-q-102", question: "To meet data residency rules, a company must ensure that users in Germany are always served by its application stack in eu-central-1, while all other users are served by a stack in us-east-1. Which Route 53 configuration meets this requirement?", options: ["Latency-based routing with one record for eu-central-1 and one for us-east-1","Geoproximity routing with a large positive bias on the eu-central-1 record","Weighted routing that sends 90 percent of traffic to the eu-central-1 record","Geolocation routing with a Germany record and a default record for us-east-1"], answer: 3, explanation: "Geolocation routing answers based on the user's country, so German users always receive the eu-central-1 record and the default record serves everyone else. Latency routing can send users to either Region as conditions change, and a geoproximity bias would also pull in users from neighboring countries.", domain: "saa1", section: "saa-10" },
  { id: "saa-q-103", question: "A company connects its data center to a VPC with AWS Direct Connect. On-premises servers must resolve DNS names that are defined in a Route 53 private hosted zone associated with that VPC. Which solution meets this requirement?", options: ["Create a Route 53 Resolver outbound endpoint with a forwarding rule for the on-premises domain","Create a Route 53 Resolver inbound endpoint and forward on-premises DNS queries to it","Associate the private hosted zone with the on-premises network through Direct Connect","Convert the private hosted zone into a public hosted zone that allows only company IP ranges"], answer: 1, explanation: "An inbound endpoint gives on-premises DNS servers IP addresses inside the VPC to which they forward queries for private hosted zone names. An outbound endpoint works in the opposite direction, letting resources in the VPC resolve on-premises domain names.", domain: "saa3", section: "saa-10" },
  { id: "saa-q-104", question: "A company uses a Route 53 health check for a public web server, but the check reports the server as unhealthy even though the application is running. The check uses HTTPS with string matching, and the server sits behind an on-premises firewall with an IP allowlist. Which TWO issues could cause the failed health check? (Choose TWO.)", options: ["The endpoint presents a self-signed TLS certificate to the health checkers","The firewall does not allow the Route 53 health checker IP ranges","The DNS record for the site uses a TTL of 300 seconds instead of 60","The search string appears only after the first 5,120 bytes of the body","The health check uses the standard 30-second interval instead of fast checks"], answer: [1,3], explanation: "Health checkers probe from AWS locations, so the firewall must allow their published IP ranges, and string matching searches only the first 5,120 bytes of the response body. HTTPS health checks do not validate certificates, and the record TTL and check interval do not cause failures.", domain: "saa2", section: "saa-10" },
  { id: "saa-q-105", question: "An e-commerce application runs on EC2 instances in an Auto Scaling group behind an Application Load Balancer. Customers lose their shopping carts when instances are terminated during scale-in. Which TWO solutions keep cart data while allowing the web tier to scale freely? (Choose TWO.)", options: ["Store session data in Amazon ElastiCache","Enable sticky sessions on the load balancer","Store session data in Amazon DynamoDB","Store session data on each instance's EBS volume","Increase the target group deregistration delay"], answer: [0,2], explanation: "A shared session store such as ElastiCache or DynamoDB makes the web instances stateless, so any instance can serve any user and scale-in loses nothing. Sticky sessions still tie each user to one instance, so the cart disappears when that instance terminates.", domain: "saa2", section: "saa-11" },
  { id: "saa-q-106", question: "EC2 instances in an Auto Scaling group take about 15 minutes to become ready because their user data script installs operating system updates, the application, and its dependencies at boot. The company needs new instances to start serving traffic much sooner during scale-out. What should a solutions architect do?", options: ["Launch from a golden AMI that already has the updates and application installed","Increase the Auto Scaling group health check grace period to cover the full boot time","Change the launch template to a larger instance type with more vCPUs and memory","Enable detailed monitoring so that scaling alarms react to demand more quickly"], answer: 0, explanation: "A golden AMI already contains the updates and the application, so new instances boot ready to serve and user data handles only quick, instance-specific settings. A longer grace period hides slow boots instead of fixing them, and faster alarms or bigger instances do not remove the long installation.", domain: "saa3", section: "saa-11" },
  { id: "saa-q-107", question: "A small team wants to deploy a Java web application by uploading only its code. AWS should handle the load balancer, Auto Scaling, and health monitoring, but the team must keep full access to the underlying EC2 instances and their configuration, without containerizing the application. Which solution meets these requirements?", options: ["AWS CloudFormation templates that define the load balancer and Auto Scaling group","An AWS Elastic Beanstalk environment with a load balancer and Auto Scaling","An Auto Scaling group built from a launch template that the team maintains","Amazon ECS on AWS Fargate behind an Application Load Balancer"], answer: 1, explanation: "Elastic Beanstalk takes uploaded code and provisions the load balancer, Auto Scaling group, and health monitoring, while the EC2 instances stay visible and configurable. CloudFormation or a hand-built Auto Scaling group means maintaining infrastructure yourself, and Fargate needs containers and hides the instances.", domain: "saa2", section: "saa-11" },
  { id: "saa-q-108", question: "A development team deploys a web application with AWS Elastic Beanstalk. The development environment should cost as little as possible, while production must be highly available across multiple Availability Zones. Which configuration meets these requirements?", options: ["Load-balanced, multi-AZ environments for development and production","Single-instance environments for development and production","Single-instance for development, load-balanced multi-AZ for production","Worker environment for development, single-instance for production"], answer: 2, explanation: "Elastic Beanstalk itself is free; you pay for the resources it creates. A single-instance environment avoids load balancer and extra instance costs in development, while a load-balanced environment with Auto Scaling across multiple Availability Zones gives production high availability.", domain: "saa4", section: "saa-11" },
  { id: "saa-q-109", question: "A streaming company distributes licensed videos through Amazon CloudFront. Its licensing agreements forbid viewers in three specific countries from accessing the content. Which solution meets this requirement with the LEAST operational overhead?", options: ["Use Route 53 geolocation routing to return no answer for those countries","Add an S3 bucket policy that denies the IP address ranges of those countries","Set an AWS Global Accelerator traffic dial of zero for those countries","Enable CloudFront geographic restrictions with a blocklist of those countries"], answer: 3, explanation: "CloudFront geographic restrictions block requests by viewer country at the edge with a simple blocklist or allowlist. Route 53 geolocation only changes DNS answers, so viewers could still reach the distribution another way, and maintaining country IP ranges yourself is error-prone.", domain: "saa1", section: "saa-15" },
  { id: "saa-q-110", question: "A company wants Amazon CloudFront to be the only entry point to a web application that runs behind an Application Load Balancer. The load balancer must not be reachable from the internet at all. Which solution meets these requirements with the LEAST operational overhead?", options: ["Keep the load balancer internet-facing and allow only the CloudFront managed prefix list","Place the load balancer in private subnets and add it to CloudFront as a VPC origin","Attach an origin access control to the load balancer origin in the distribution","Keep the load balancer internet-facing and enable geo restriction on the distribution"], answer: 1, explanation: "CloudFront VPC origins reach a load balancer or EC2 instance in private subnets over a private connection, so the origin has no public exposure. A prefix list in the security group narrows access, but the load balancer stays internet-facing. Origin access control applies to origins such as S3, not load balancers.", domain: "saa1", section: "saa-15" },
  { id: "saa-q-111", question: "A company uses Amazon CloudFront to deliver its website. Almost all of its users are in North America and Europe. The company wants to lower its CloudFront costs and accepts slightly higher latency for the few users elsewhere. What should a solutions architect do?", options: ["Change the distribution to Price Class All","Change the distribution to Price Class 100","Enable Origin Shield in the Region closest to the origin","Replace CloudFront with S3 Cross-Region Replication"], answer: 1, explanation: "Price Class 100 serves viewers only from the least expensive edge locations, covering North America, Europe, and Israel, while users elsewhere are still served with somewhat higher latency. Price Class All uses every edge location, including the most expensive ones, and Origin Shield adds cost rather than removing it.", domain: "saa4", section: "saa-15" },
  { id: "saa-q-112", question: "A company deploys updated CSS and JavaScript files several times a day to an S3 origin behind Amazon CloudFront. It currently submits an invalidation for every changed file after each deployment, which adds cost. Users must get new files right away, and the cache hit ratio must stay high. Which approach is MOST cost-effective?", options: ["Invalidate every file in the distribution after each deployment","Enable S3 Versioning on the origin bucket to track the changes","Set the default, minimum, and maximum TTL values to zero","Use versioned file names and update the references to them"], answer: 3, explanation: "Versioned file names, such as a new name for each build, are fetched as new objects immediately and need no invalidation, so other files keep caching well. Invalidating everything empties the cache, a zero TTL sends every request to the origin, and S3 Versioning does not change what CloudFront has cached.", domain: "saa4", section: "saa-15" },
  { id: "saa-q-113", question: "A gaming company runs UDP-based multiplayer game servers behind Network Load Balancers in three AWS Regions. Players worldwide report high latency and jitter. The company also needs a small, fixed set of IP addresses that partners can allowlist. Which solution meets these requirements?", options: ["Deploy AWS Global Accelerator with an endpoint group for each Region","Deploy an Amazon CloudFront distribution with the load balancers as origins","Use Route 53 latency-based routing to the three load balancers","Assign Elastic IP addresses to the load balancers in each Region"], answer: 0, explanation: "Global Accelerator provides two static anycast IP addresses and carries TCP and UDP traffic over the AWS global network from the nearest edge location, cutting latency and jitter. CloudFront does not proxy UDP game traffic, and Route 53 latency routing gives neither fixed IP addresses nor an optimized network path.", domain: "saa3", section: "saa-15" },
  { id: "saa-q-114", question: "A company serves a static website through Amazon CloudFront from an S3 bucket in us-east-1. S3 Cross-Region Replication keeps a copy of the bucket in us-west-2. If the primary bucket returns server errors, CloudFront must automatically serve content from the replica. Which solution meets this requirement with the LEAST operational overhead?", options: ["Route 53 failover routing between the two S3 website endpoints","AWS Global Accelerator with an endpoint group for each S3 bucket","A CloudFront origin group with the replica bucket as the secondary origin","A Lambda@Edge function that rewrites the origin whenever errors occur"], answer: 2, explanation: "An origin group makes CloudFront retry a failed GET or HEAD request against the secondary origin when the primary returns chosen error codes, with no custom code. Global Accelerator does not support S3 buckets as endpoints, and a Lambda@Edge rewrite adds code to build and maintain.", domain: "saa2", section: "saa-15" },
  { id: "saa-q-115", question: "A company serves files from a private Amazon S3 bucket through an Amazon CloudFront distribution. Users must be able to download the files only through CloudFront, never directly from S3. Which TWO steps should a solutions architect take? (Choose TWO.)", options: ["Enable S3 Transfer Acceleration and use its endpoint as the origin","Create an origin access control and attach it to the S3 origin","Use the bucket's S3 static website endpoint as the origin","Turn on CloudFront geo restriction with a country allowlist","Update the bucket policy to allow only the CloudFront distribution"], answer: [1,4], explanation: "Origin access control signs CloudFront's requests to S3, and the bucket policy lets only the CloudFront service principal for that distribution read objects, so Block Public Access can stay on. A static website endpoint is a custom origin that cannot use origin access control and needs public objects.", domain: "saa1", section: "saa-15" },
  { id: "saa-q-116", question: "A media company stores raw footage that is accessed about once every quarter. When a producer requests a file, it must be available within milliseconds, and the data must survive the loss of an Availability Zone. Which S3 storage class is MOST cost-effective?", options: ["S3 Standard-Infrequent Access","S3 One Zone-Infrequent Access","S3 Glacier Instant Retrieval","S3 Glacier Flexible Retrieval"], answer: 2, explanation: "Glacier Instant Retrieval gives millisecond access at a lower storage price than Standard-IA, and is designed for data read about once a quarter. Standard-IA works but costs more to store. One Zone-IA fails the Availability Zone requirement, and Flexible Retrieval takes minutes to hours.", domain: "saa4", section: "saa-12" },
  { id: "saa-q-117", question: "A company enables S3 Cross-Region Replication on a bucket that already holds 40 million objects. The disaster recovery plan requires that the existing objects also exist in the destination Region. What should a solutions architect do with the LEAST operational overhead?", options: ["Create an S3 Batch Replication job for the bucket","Enable S3 Replication Time Control on the replication rule","Enable delete marker replication on the replication rule","Run a Lambda function that copies every object to the destination"], answer: 0, explanation: "Replication rules only copy objects written after the rule is enabled. S3 Batch Replication backfills existing objects and retries failed ones with no custom code. Replication Time Control only adds a time guarantee for new objects, and a custom Lambda copier adds code to maintain.", domain: "saa2", section: "saa-12" },
  { id: "saa-q-118", question: "A machine learning team runs training jobs on EC2 instances in a single Availability Zone. The jobs read millions of small files and need consistent single-digit millisecond latency at very high request rates. The dataset can be regenerated from source. Which storage option meets these requirements?", options: ["S3 Standard bucket with Transfer Acceleration enabled","S3 Express One Zone directory bucket in the same AZ","S3 One Zone-IA storage class for the dataset","S3 Glacier Instant Retrieval with byte-range fetches"], answer: 1, explanation: "S3 Express One Zone stores re-creatable data in directory buckets in an Availability Zone you choose, giving consistent single-digit millisecond latency at very high request rates. One Zone-IA lowers storage cost, not latency, and adds retrieval fees. Transfer Acceleration only speeds long-distance transfers.", domain: "saa3", section: "saa-12" },
  { id: "saa-q-119", question: "An application running in AWS Account B must read objects from a private S3 bucket in Account A. The bucket must stay private. Which solution is MOST secure?", options: ["Create an IAM user in Account A and embed its access keys in the app","Turn off Block Public Access and allow public reads in the bucket policy","Enable S3 Requester Pays and share the bucket name with Account B","Grant the Account B role access in both the bucket and role policies"], answer: 3, explanation: "Cross-account access must be allowed on both sides: the bucket policy in Account A names the Account B role, and the role's IAM policy permits the S3 actions. Embedded access keys are long-lived credentials, public reads break the private requirement, and Requester Pays only changes billing.", domain: "saa1", section: "saa-12" },
  { id: "saa-q-120", question: "Application logs are queried often for 30 days, rarely for the next 60 days, and then must be kept for 7 years for audits. Logs must always be stored across multiple Availability Zones, and audit retrievals can take up to 12 hours. Which approach is MOST cost-effective?", options: ["Lifecycle to Standard-IA at 30 days, Glacier Instant Retrieval at 90 days, expire at 7 years","Lifecycle to Standard-IA at 30 days, Glacier Flexible Retrieval at 90 days, expire at 7 years","Store in S3 Intelligent-Tiering from day one and expire objects at 7 years","Lifecycle to Standard-IA at 30 days, Glacier Deep Archive at 90 days, expire at 7 years"], answer: 3, explanation: "The access pattern is known, so lifecycle transitions fit best. Standard-IA covers the rarely read period, then Glacier Deep Archive, the cheapest class, meets the 12-hour retrieval window. Instant and Flexible Retrieval cost more to store for seven years, and Intelligent-Tiering adds monitoring fees for a predictable pattern.", domain: "saa4", section: "saa-13" },
  { id: "saa-q-121", question: "A company is launching a new analytics dataset in S3. Access patterns are unknown and will change over time; some objects will be read heavily for months and then not at all. The company wants to minimize storage cost without retrieval fees or manual analysis. Which storage class should be used?", options: ["S3 Standard-IA with no lifecycle rules","S3 Intelligent-Tiering","S3 Glacier Instant Retrieval","S3 Standard with a lifecycle rule to Standard-IA"], answer: 1, explanation: "Intelligent-Tiering moves each object between access tiers based on its own usage, charges a small monitoring fee, and has no retrieval fees, which suits unknown or changing patterns. Standard-IA and Glacier Instant Retrieval charge retrieval fees, and a fixed lifecycle rule would also move objects that are still hot.", domain: "saa4", section: "saa-13" },
  { id: "saa-q-122", question: "A versioning-enabled S3 bucket keeps growing in cost. Analysis shows many old noncurrent object versions and a large amount of storage used by multipart uploads that never completed. Which TWO actions will reduce storage costs? (Choose TWO.)", options: ["Suspend versioning on the bucket to remove the existing old versions","Add a lifecycle rule that expires noncurrent versions after 30 days","Enable S3 Transfer Acceleration so uploads finish more reliably","Add a lifecycle rule that aborts incomplete multipart uploads after 7 days","Enable S3 Replication Time Control on the bucket"], answer: [1,3], explanation: "Lifecycle expiration actions permanently remove noncurrent versions and clean up incomplete multipart uploads, whose parts are billed until aborted. Suspending versioning only stops new versions; existing ones remain and keep costing money. Transfer Acceleration and Replication Time Control add cost rather than remove data.", domain: "saa4", section: "saa-13" },
  { id: "saa-q-123", question: "Users around the world upload video files of 2 to 20 GB to a single S3 bucket in one Region. Uploads are slow and often fail partway through, forcing a full restart. Which TWO actions will improve upload speed and reliability? (Choose TWO.)", options: ["Use multipart upload to send parts in parallel","Use byte-range fetches for each upload","Enable S3 Transfer Acceleration on the bucket","Enable S3 Versioning so failed uploads can resume","Enable S3 Requester Pays on the bucket"], answer: [0,2], explanation: "Multipart upload sends parts in parallel and retries only failed parts, and it is required for objects over 5 GB. Transfer Acceleration routes uploads through the nearest edge location and the AWS backbone. Byte-range fetches speed up downloads, not uploads, and versioning cannot resume a failed upload.", domain: "saa3", section: "saa-13" },
  { id: "saa-q-124", question: "When images are uploaded to an S3 bucket, a company must trigger three separate workflows. The workflows need to filter events by object size, and the team wants to archive and replay events for troubleshooting. Which solution meets these requirements with the LEAST operational overhead?", options: ["Turn on Amazon EventBridge for the bucket with one rule per workflow","Send S3 Event Notifications to one SQS FIFO queue shared by all workflows","Send S3 Event Notifications with suffix filters to three Lambda functions","Enable server access logging and have each workflow parse the log files"], answer: 0, explanation: "Sending S3 events to EventBridge enables rules with advanced filtering such as object size, multiple targets, and event archive and replay. Native S3 Event Notifications only filter on prefix and suffix, cannot replay events, and cannot target SQS FIFO queues directly. Parsing access logs is slow and needs custom code.", domain: "saa2", section: "saa-13" },
  { id: "saa-q-125", question: "A bucket created in 2019 holds 50 million objects that were uploaded without encryption. A new policy requires every object, including existing ones, to be encrypted with an AWS KMS key. What is the MOST operationally efficient solution?", options: ["Enable default bucket encryption with SSE-KMS using a customer managed key","Enable S3 Bucket Keys on the bucket so existing objects use the KMS key","Use S3 Inventory and S3 Batch Operations to copy the objects with SSE-KMS","Run a script on EC2 that downloads and re-uploads every object"], answer: 2, explanation: "S3 Inventory lists the unencrypted objects, and S3 Batch Operations copies them in place with SSE-KMS at scale, with tracking and a completion report. Default encryption only applies to new uploads, so existing objects stay unencrypted. Bucket Keys only reduce KMS calls, and a custom EC2 script adds operational overhead.", domain: "saa1", section: "saa-13" },
  { id: "saa-q-126", question: "A company stores critical legal documents in S3. It must be able to recover any document that is accidentally overwritten or deleted, and permanently deleting a version must require an extra authentication factor. Which TWO actions meet these requirements? (Choose TWO.)", options: ["Enable S3 server access logging","Enable S3 Intelligent-Tiering","Enable S3 Versioning on the bucket","Enable default encryption with SSE-KMS","Enable MFA Delete on the bucket"], answer: [2,4], explanation: "Versioning keeps prior versions, so overwritten or deleted objects can be restored. MFA Delete, which needs versioning and is enabled by the root user, requires an MFA code to permanently delete a version or suspend versioning. Access logs only record requests, and encryption does not prevent deletion.", domain: "saa1", section: "saa-14" },
  { id: "saa-q-127", question: "A government contractor must meet a compliance rule that requires two independent layers of server-side encryption for data at rest in Amazon S3. The company wants S3 to apply both layers with the LEAST operational overhead. Which option meets the requirement?", options: ["SSE-KMS with S3 Bucket Keys enabled","DSSE-KMS with an AWS KMS key","SSE-S3 with default bucket encryption","SSE-KMS with a multi-Region KMS key"], answer: 1, explanation: "DSSE-KMS, dual-layer server-side encryption, applies two independent layers of encryption to each object using AWS KMS keys, built for standards that demand multilayer encryption. SSE-KMS with Bucket Keys or a multi-Region key is still a single layer, and SSE-S3 is the single-layer default.", domain: "saa1", section: "saa-14" },
  { id: "saa-q-128", question: "A company's security policy states that encryption keys must be generated and stored only in its on-premises key management system and must never be stored by AWS. Amazon S3 should still perform the encryption and decryption. Which option should be used?", options: ["SSE-KMS with imported key material","SSE-KMS with a CloudHSM custom key store","SSE-C with the key supplied in each request","Client-side encryption with the AWS Encryption SDK"], answer: 2, explanation: "With SSE-C the company sends its key over HTTPS in every request; S3 encrypts or decrypts, then discards the key. Imported key material and CloudHSM key stores keep keys inside AWS, and with client-side encryption S3 never encrypts anything. Remember that new buckets now have SSE-C disabled until you enable it.", domain: "saa1", section: "saa-14" },
  { id: "saa-q-129", question: "A financial firm must store trade records in Amazon S3 in a write-once-read-many format for 7 years. No user, including the AWS account root user, may delete the records or shorten the retention period. Which solution meets these requirements?", options: ["S3 Object Lock in governance mode with a 7-year retention period","S3 Object Lock legal holds placed on every object","S3 Versioning with MFA Delete enabled on the bucket","S3 Object Lock in compliance mode with a 7-year retention period"], answer: 3, explanation: "Compliance mode stops anyone, including the root user, from deleting a locked version or shortening its retention. Governance mode lets users with a special permission bypass the lock, legal holds can be removed by authorized users, and MFA Delete still lets the root user delete versions.", domain: "saa1", section: "saa-14" },
  { id: "saa-q-130", question: "A shared data lake bucket is used by dozens of teams, and its single bucket policy has become too large and error-prone. Each team needs access only to its own prefix, and some teams must reach the data only from their VPC. Which solution is the MOST manageable?", options: ["Create one S3 access point per team with its own policy","Split the data into one bucket per team and use S3 Replication","Enable object ACLs and grant each team access to its objects","Generate presigned URLs for every object in each team's prefix"], answer: 0, explanation: "Access points give each team its own endpoint and policy scoped to its prefix, which keeps the bucket policy simple, and an access point can be limited to a VPC network origin. Separate buckets add replication overhead, ACLs are disabled by default and hard to manage, and presigned URLs work per object.", domain: "saa1", section: "saa-14" },
  { id: "saa-q-131", question: "A company sells e-books stored in a private Amazon S3 bucket. After a customer pays, the web application must let that customer download only the purchased file for the next 15 minutes. Customers have no AWS credentials. Which solution meets these requirements with the LEAST operational overhead?", options: ["Have the application generate an S3 presigned URL for the object that expires in 15 minutes","Make the object public, then remove public access 15 minutes later with a scheduled function","Create a temporary IAM user for each customer and delete the user after 15 minutes","Add a bucket policy that allows the customer's IP address, then remove it after 15 minutes"], answer: 0, explanation: "A presigned URL uses the application's own permissions for one object and expires at the time you choose, so customers need no AWS credentials. Temporarily making objects public or editing policies and IAM users exposes data and adds fragile cleanup work.", domain: "saa1", section: "saa-14" },
  { id: "saa-q-132", question: "A genomics company runs HPC jobs on thousands of EC2 instances. Input data is stored in Amazon S3. The jobs need a shared POSIX file system with sub-millisecond latency and hundreds of gigabytes per second of throughput, and results must be written back to S3. Which service should be used?", options: ["Amazon EFS with Elastic throughput and a Regional file system","Amazon FSx for Lustre with a data repository association","Amazon FSx for Windows File Server with SSD storage","Amazon S3 File Gateway running on an EC2 instance"], answer: 1, explanation: "FSx for Lustre is a parallel file system built for HPC and machine learning, and it links to S3 so objects appear as files and results can be exported back. EFS is general-purpose NFS storage with no S3 link and lower peak throughput, and FSx for Windows serves SMB workloads.", domain: "saa3", section: "saa-16" },
  { id: "saa-q-133", question: "A company is migrating an on-premises multiprotocol storage array to AWS. The array serves the same data to Linux clients over NFS and Windows clients over SMB, and some servers mount iSCSI block volumes from it. Which AWS service requires the FEWEST changes?", options: ["Amazon FSx for NetApp ONTAP","Amazon FSx for OpenZFS","Amazon FSx for Windows File Server","Amazon EFS with one access point per client"], answer: 0, explanation: "FSx for NetApp ONTAP supports NFS, SMB, and iSCSI from one file system, with snapshots and SnapMirror replication, so a multiprotocol array moves with few changes. FSx for OpenZFS serves NFS only, FSx for Windows File Server serves SMB only, and EFS supports NFS only.", domain: "saa3", section: "saa-16" },
  { id: "saa-q-134", question: "A company runs Windows applications on EC2 that need a shared file system with SMB access, NTFS permissions, Microsoft Active Directory integration, and DFS Namespaces. The file system must stay available if an Availability Zone fails. Which solution meets these requirements?", options: ["Amazon FSx for Windows File Server with a Single-AZ deployment","Amazon EFS with a Regional file system and mount targets","Amazon FSx for Lustre with a persistent deployment type","Amazon FSx for Windows File Server with a Multi-AZ deployment"], answer: 3, explanation: "FSx for Windows File Server provides native SMB, NTFS permissions, Active Directory integration, and DFS Namespaces, and a Multi-AZ deployment fails over to a standby file server in another Availability Zone. Single-AZ cannot survive an AZ failure, EFS is NFS storage for Linux, and Lustre targets HPC.", domain: "saa2", section: "saa-16" },
  { id: "saa-q-135", question: "An on-premises application needs iSCSI block storage with low-latency local access to its entire dataset. The data must be backed up asynchronously to AWS as point-in-time snapshots for disaster recovery. Which AWS Storage Gateway configuration should be used?", options: ["Volume Gateway with cached volumes","S3 File Gateway with an NFS share","Volume Gateway with stored volumes","Tape Gateway with virtual tapes"], answer: 2, explanation: "Stored volumes keep the full dataset on premises for low latency and back it up asynchronously to AWS as EBS snapshots. Cached volumes keep primary data in S3 and cache only frequently used data locally. File Gateway presents file shares and Tape Gateway presents a virtual tape library, not general block volumes.", domain: "saa2", section: "saa-16" },
  { id: "saa-q-136", question: "A company must migrate 60 TB of files from an on-premises NFS server to Amazon EFS over an existing 10 Gbps AWS Direct Connect link. File permissions and metadata must be preserved, and changes must be synced on a schedule until cutover. Which solution meets these requirements?", options: ["AWS Transfer Family with an SFTP endpoint","AWS DataSync task with an agent and an EFS location","AWS Snowball Edge Storage Optimized devices","S3 File Gateway with an NFS file share"], answer: 1, explanation: "DataSync uses an on-premises agent to copy NFS data directly into EFS, preserving permissions and metadata, and scheduled tasks move only changes until cutover. Transfer Family serves SFTP users, Snowball is for offline transfer when bandwidth is too limited, and S3 File Gateway writes to S3, not EFS.", domain: "saa3", section: "saa-16" },
  { id: "saa-q-137", question: "A company's backup software writes to an on-premises physical tape library. The company wants to stop handling physical tapes, keep its existing backup software and processes, and move older backups to durable archive storage in AWS. What should a solutions architect recommend?", options: ["Storage Gateway Volume Gateway with cached volumes for the backups","AWS DataSync tasks that copy backup files into S3 Glacier Deep Archive","Storage Gateway Tape Gateway that archives tapes to S3 Glacier Deep Archive","Storage Gateway S3 File Gateway with an SMB share for the backups"], answer: 2, explanation: "Tape Gateway presents a virtual tape library over iSCSI, so existing backup software keeps working unchanged, and archived tapes move to Glacier Flexible Retrieval or Deep Archive. Volume Gateway, File Gateway, and DataSync would all force the company to replace its tape-based backup workflow.", domain: "saa2", section: "saa-16" },
  { id: "saa-q-138", question: "Hundreds of external partners upload files to a company using SFTP clients and cannot change their tools. The company wants to store the files in Amazon S3, authenticate partners with its existing identity provider, and avoid managing servers. Which solution meets these requirements?", options: ["EC2 instances running an SFTP server in an Auto Scaling group","AWS DataSync agents installed at each partner location","S3 presigned upload URLs emailed to each partner","AWS Transfer Family server with Amazon S3 as its storage"], answer: 3, explanation: "Transfer Family is a fully managed SFTP, FTPS, FTP, and AS2 service that stores files in S3 or EFS and can authenticate through existing or custom identity providers. Self-managed EC2 SFTP servers add operational work, DataSync needs agents partners will not run, and presigned URLs require new partner tools.", domain: "saa2", section: "saa-16" },
  { id: "saa-q-139", question: "A research lab must move 400 TB of archival data to AWS within 4 weeks. Its 100 Mbps internet connection is shared with daily operations. The data will rarely be read and must be stored at the lowest possible cost. Which TWO steps should a solutions architect take? (Choose TWO.)", options: ["Import the data into an S3 bucket using AWS Snowball Edge devices","Enable S3 Transfer Acceleration and upload over the internet","Use AWS DataSync over the existing internet connection","Add an S3 Lifecycle rule to transition objects to S3 Glacier Deep Archive","Configure Snowball Edge to write directly into an S3 Glacier vault"], answer: [0,3], explanation: "At 100 megabits per second, 400 terabytes would take about a year online, so ship it on Snowball Edge devices into S3, then use a lifecycle rule to move it to Deep Archive. Snowball cannot import straight into Glacier, and Transfer Acceleration or DataSync still depend on the slow link.", domain: "saa4", section: "saa-16" },
  { id: "saa-q-140", question: "An application uses an Amazon SQS standard queue. Consumers on Amazon EC2 take about 4 minutes to process each message and delete it when finished. The team notices that some orders are processed twice. What should a solutions architect do to reduce the duplicate processing?", options: ["Enable long polling by setting the receive wait time to 20 seconds","Increase the visibility timeout to longer than the processing time","Configure a delay queue so new messages stay hidden for 5 minutes","Increase the message retention period of the queue to 14 days"], answer: 1, explanation: "A received message becomes visible again when the visibility timeout, 30 seconds by default, expires before the consumer deletes it, so another consumer processes it too. Raising the timeout above the processing time, or calling ChangeMessageVisibility, fixes this. A delay queue only postpones the first delivery, and long polling only reduces empty receives.", domain: "saa2", section: "saa-17" },
  { id: "saa-q-141", question: "Worker instances poll an Amazon SQS queue in a tight loop. Most ReceiveMessage calls return no messages, and SQS request charges are higher than expected. Which change will MOST cost-effectively reduce the number of API calls?", options: ["Add more consumer instances so that messages are received sooner","Enable long polling by setting ReceiveMessageWaitTimeSeconds to 20","Increase the visibility timeout of the queue to 12 hours","Convert the queue to an SQS FIFO queue and receive in batches"], answer: 1, explanation: "With long polling, a receive request waits up to 20 seconds for a message instead of returning empty immediately, which cuts empty responses and request charges. Adding consumers creates even more empty polls, the visibility timeout only controls how long a received message stays hidden, and batching does not help when the queue is empty.", domain: "saa4", section: "saa-17" },
  { id: "saa-q-142", question: "An e-commerce platform sends order events to Amazon SQS. Events for the same customer must be processed in the exact order they were sent, while events for different customers should be processed in parallel to maximize throughput. Which solution meets these requirements?", options: ["An SQS standard queue with a sequence number in each message attribute","An SQS FIFO queue that uses one fixed message group ID for all messages","An SQS FIFO queue that uses the customer ID as the message group ID","An Amazon SNS standard topic with one SQS standard queue per consumer"], answer: 2, explanation: "FIFO queues keep strict order within each message group, and different groups can be consumed in parallel, so grouping by customer ID gives per-customer ordering with high throughput. A single fixed group ID forces every message through one ordered lane, and standard queues and topics offer only best-effort ordering.", domain: "saa3", section: "saa-17" },
  { id: "saa-q-143", question: "A payment application reads messages from an Amazon SQS queue. A few malformed messages fail every time and keep returning to the queue, wasting consumer capacity. The team wants these messages set aside automatically for later investigation. What should a solutions architect do?", options: ["Reduce the message retention period so failed messages expire sooner","Enable long polling so consumers skip messages that failed before","Set the visibility timeout to zero so failed messages return at once","Configure a dead-letter queue and set a maximum receive count"], answer: 3, explanation: "A redrive policy moves a message to the dead-letter queue after it has been received maxReceiveCount times without being deleted, isolating poison messages for debugging and later redrive. Shortening retention silently loses data, long polling does not track failures, and a zero visibility timeout makes the problem worse.", domain: "saa2", section: "saa-17" },
  { id: "saa-q-144", question: "A company uploads images to an Amazon S3 bucket. Every upload event must be processed independently by a thumbnail service and an analytics service, and each service reads from its own Amazon SQS queue. Which TWO actions should a solutions architect take? (Choose TWO.)", options: ["Configure the S3 event notification to publish to an Amazon SNS topic","Create two S3 event notifications with the same event type and prefix","Subscribe both queues to the topic and allow it in each queue access policy","Configure the thumbnail service to forward each message to the other queue","Enable S3 Cross-Region Replication so each service has its own bucket"], answer: [0,2], explanation: "S3 rejects two notification rules with the same event type and overlapping prefixes, so publish once to SNS and fan out. Each subscribed queue receives its own copy, but its access policy must allow the SNS topic to send messages. Forwarding messages between services recreates the tight coupling you wanted to avoid.", domain: "saa2", section: "saa-17" },
  { id: "saa-q-145", question: "A gaming company collects player events in real time. Three separate applications must read the same events, events for each player must stay in order, and the data must be replayable for up to 7 days. Which service should a solutions architect choose?", options: ["Amazon SQS FIFO queue","Amazon Data Firehose","Amazon Kinesis Data Streams","Amazon SNS standard topic"], answer: 2, explanation: "Kinesis Data Streams keeps records for up to 365 days, orders them per partition key such as the player ID, and lets several consumers read and replay the same data. SQS deletes a message once it is consumed, and Firehose delivers data to destinations without storing it for replay.", domain: "saa3", section: "saa-17" },
  { id: "saa-q-146", question: "A company wants to capture clickstream data from its website and store it in Amazon S3 in Apache Parquet format for Amazon Athena queries. The solution must scale automatically with the LEAST operational overhead. Which solution meets these requirements?", options: ["Amazon Data Firehose with record format conversion delivering to Amazon S3","Amazon Kinesis Data Streams with a custom consumer on EC2 that writes Parquet","An Amazon SQS queue with an Auto Scaling group of EC2 workers writing Parquet","An Amazon MQ broker with a Lambda function that batches records into Parquet"], answer: 0, explanation: "Firehose is fully managed, scales automatically, and can convert JSON records to Parquet before delivering them to S3, with no consumer code to write. Kinesis Data Streams or SQS with EC2 consumers would work, but you would have to build, scale, and patch the processing fleet yourself.", domain: "saa3", section: "saa-17" },
  { id: "saa-q-147", question: "A company is migrating an on-premises application to AWS. The application uses Apache ActiveMQ with the AMQP and MQTT protocols. The company wants a managed broker, does not want to change its messaging code, and needs the broker to stay available if an Availability Zone fails. Which solution meets these requirements?", options: ["Amazon MQ for ActiveMQ with a single-instance broker and daily backups","Amazon SQS FIFO queues accessed through the SQS Extended Client Library","Amazon SNS FIFO topics with Amazon SQS FIFO queues as the subscribers","Amazon MQ for ActiveMQ using the active and standby deployment mode"], answer: 3, explanation: "Amazon MQ runs managed ActiveMQ and RabbitMQ brokers that speak open protocols such as AMQP and MQTT, so existing code keeps working, and the active and standby deployment fails over across Availability Zones. A single-instance broker has no failover, and SQS or SNS would require rewriting the messaging code.", domain: "saa2", section: "saa-17" },
  { id: "saa-q-148", question: "A healthcare company sends patient records through an Amazon SQS queue. Compliance rules require encryption at rest with a key that the company controls, can disable at any time, and whose every use is logged in AWS CloudTrail. What should a solutions architect configure?", options: ["Server-side encryption with SQS managed keys, known as SSE-SQS","A queue policy that denies requests where aws:SecureTransport is false","Server-side encryption with an AWS KMS customer managed key","An interface VPC endpoint for SQS with a restrictive endpoint policy"], answer: 2, explanation: "A customer managed KMS key lets the company own the key policy, disable or rotate the key, and audit each use in CloudTrail. SSE-SQS also encrypts at rest, but with keys SQS manages that the company cannot control. The SecureTransport condition and VPC endpoints protect data in transit and network paths, not data at rest.", domain: "saa1", section: "saa-17" },
  { id: "saa-q-149", question: "An image processing application runs on an Auto Scaling group of EC2 instances that pull jobs from an Amazon SQS queue. During peak hours, jobs wait in the queue for a long time even though average CPU utilization stays moderate. How should a solutions architect scale the workers?", options: ["Use target tracking on average CPU utilization with a lower target value","Use target tracking on the SQS queue backlog per instance in CloudWatch","Increase the visibility timeout so each instance holds messages longer","Add a scheduled scaling action that doubles capacity every morning"], answer: 1, explanation: "Backlog per instance, the ApproximateNumberOfMessagesVisible metric divided by the number of running instances, measures pending work directly, so scaling on it adds workers as jobs pile up. CPU can stay moderate while the queue keeps growing, and a fixed schedule cannot react to unpredictable peaks.", domain: "saa3", section: "saa-17" },
  { id: "saa-q-150", question: "A company runs two services on the same Amazon ECS cluster using the EC2 launch type. The orders service needs write access to an Amazon DynamoDB table, and the reports service needs read access to an Amazon S3 bucket. How should permissions be granted following the principle of least privilege?", options: ["Attach both permissions to the instance profile of the container instances","Create an IAM task role for each task definition with only its access","Add both permissions to the task execution role shared by the two services","Store IAM user access keys for each service as environment variables"], answer: 1, explanation: "Task roles give each task definition its own temporary credentials, so each service gets only the access it needs. The instance profile would give every container on the host both permissions, and the task execution role is used by ECS itself to pull images, send logs, and fetch secrets, not by application code.", domain: "saa1", section: "saa-18" },
  { id: "saa-q-151", question: "An application running on Amazon ECS with AWS Fargate needs a database password at startup. Security policy forbids storing the password in the container image or in plaintext in the task definition. Which solution meets these requirements?", options: ["Reference an AWS Secrets Manager secret in the task definition","Store the password as a plaintext environment variable in the task definition","Bake the password into the image and restrict pulls with a repository policy","Pass the password as a command-line argument in the container definition"], answer: 0, explanation: "When the task definition references a Secrets Manager secret by its ARN, ECS injects the value into the container at startup, and only the task execution role needs permission to read it. Environment variables and command arguments written in the task definition are stored and displayed in plaintext, and baking it into the image breaks the policy.", domain: "saa1", section: "saa-18" },
  { id: "saa-q-152", question: "A company runs nightly data processing jobs as containers on Amazon ECS. The jobs are stateless and can simply be restarted if interrupted. The company does not want to manage servers. Which compute option is the MOST cost-effective?", options: ["Fargate Spot through an ECS capacity provider","Fargate with a one-year Compute Savings Plan","The EC2 launch type with On-Demand Instances","The EC2 launch type with Dedicated Instances"], answer: 0, explanation: "Fargate Spot runs interruption-tolerant tasks on spare capacity at up to a 70 percent discount, with no servers to manage. A Savings Plan gives a smaller discount and needs a commitment, and both EC2 launch type options require managing the container instances.", domain: "saa4", section: "saa-18" },
  { id: "saa-q-153", question: "A company stores container images in a private Amazon ECR repository. The security team requires that images are automatically checked for operating system and programming language package vulnerabilities, and that only the build pipeline's IAM role can push images. Which TWO actions meet these requirements? (Choose TWO.)", options: ["Add a lifecycle policy that expires untagged images after 7 days","Enable ECR enhanced scanning with Amazon Inspector for the repository","Enable cross-Region replication for the repository to a second Region","Enable basic scanning on push for the repository","Add a repository policy that denies push to all but the pipeline role"], answer: [1,4], explanation: "Enhanced scanning uses Amazon Inspector to scan images continuously for operating system and language package vulnerabilities, while basic scanning checks operating system packages only. A repository policy that denies push to every principal except the pipeline role controls who can publish. Lifecycle policies and replication manage cost and availability, not security.", domain: "saa1", section: "saa-18" },
  { id: "saa-q-154", question: "A Java 21 AWS Lambda function behind Amazon API Gateway has slow cold starts because its framework takes several seconds to initialize. Traffic is unpredictable. The company wants to reduce startup latency with the LEAST additional cost. What should a solutions architect do?", options: ["Configure provisioned concurrency on the function alias for peak traffic","Configure reserved concurrency equal to the expected peak request rate","Increase the function memory to the maximum of 10,240 MB","Enable Lambda SnapStart and invoke a published function version"], answer: 3, explanation: "SnapStart snapshots the initialized execution environment when a version is published and resumes from that snapshot, cutting cold start time, with no extra charge for Java runtimes. Provisioned concurrency also removes cold starts, but you pay to keep environments warm all the time. Reserved concurrency does not initialize anything.", domain: "saa3", section: "saa-19" },
  { id: "saa-q-155", question: "A company runs many AWS Lambda functions in one account and Region. During a campaign, a batch processing function scaled up and used most of the account concurrency, and the critical checkout function was throttled. How can a solutions architect ensure the checkout function can always scale to 200 concurrent executions?", options: ["Enable Lambda SnapStart on the checkout function","Increase the memory allocated to the checkout function","Configure reserved concurrency of 200 on the checkout function","Configure a dead-letter queue for the checkout function"], answer: 2, explanation: "Reserved concurrency sets aside 200 executions from the account pool that no other function can use, at no extra charge, so checkout is never starved. SnapStart and more memory only speed up execution, and a dead-letter queue only captures failed asynchronous events after the fact.", domain: "saa2", section: "saa-19" },
  { id: "saa-q-156", question: "A global website served through Amazon CloudFront must add security headers to every response and rewrite some URLs before the cache lookup. The logic is simple JavaScript with no network calls, and it must handle millions of requests per second. Which solution is the MOST cost-effective?", options: ["CloudFront Functions on the viewer request and viewer response events","Lambda@Edge functions on the origin request and origin response events","An Application Load Balancer with listener rules in front of the origin","AWS WAF rules with custom request handling on the CloudFront distribution"], answer: 0, explanation: "CloudFront Functions run lightweight JavaScript on viewer events with sub-millisecond startup and scale to millions of requests per second at a fraction of the Lambda@Edge price. Lambda@Edge suits heavier logic that needs network access or origin events, and an origin load balancer acts only after the cache lookup.", domain: "saa4", section: "saa-19" },
  { id: "saa-q-157", question: "An AWS Lambda function must query an Amazon RDS database in private subnets and also call a partner's public HTTPS API. The database must not be exposed to the internet. Which TWO actions should a solutions architect take? (Choose TWO.)", options: ["Connect the function to the private subnets used by the database","Attach the function to a public subnet so that it receives a public IP address","Make the database publicly accessible and allow only the Lambda IP ranges","Route the private subnets' internet traffic through a NAT gateway in a public subnet","Create a gateway VPC endpoint so that the function can reach the partner API"], answer: [0,3], explanation: "Attaching Lambda to the VPC places its network interfaces in your subnets so it can reach the private database. Those interfaces never get public IP addresses, even in a public subnet, so internet calls need a NAT gateway. Gateway endpoints only reach Amazon S3 and DynamoDB, not third-party APIs.", domain: "saa1", section: "saa-19" },
  { id: "saa-q-158", question: "A mobile app lets users sign in with their social media accounts and then upload photos directly to Amazon S3. Each user must only be able to write to their own prefix in the bucket, and no long-term credentials may be stored in the app. What should a solutions architect use?", options: ["An Amazon Cognito user pool whose JWT tokens are used to sign S3 requests","An IAM user for each app user, with access keys stored in the app","An S3 bucket policy that allows uploads from the app's public IP range","An Amazon Cognito identity pool whose role uses an identity policy variable"], answer: 3, explanation: "Identity pools exchange a signed-in identity for temporary AWS credentials, and the IAM role can use the Cognito identity ID policy variable to limit each user to their own prefix. User pool tokens authenticate users to your app or API but cannot sign S3 requests, and IAM users mean long-term keys in the app.", domain: "saa1", section: "saa-19" },
  { id: "saa-q-159", question: "A company exposes a REST API through Amazon API Gateway backed by AWS Lambda. Only customers who sign in through the company's existing Amazon Cognito user pool may call the API. Which solution requires the LEAST custom code?", options: ["Configure a Lambda authorizer that validates each user's token","Require an API key and associate it with a usage plan","Configure an Amazon Cognito user pool authorizer on the API","Use IAM authorization with Signature Version 4 signed requests"], answer: 2, explanation: "API Gateway validates Cognito user pool tokens natively through a Cognito authorizer, so no code is needed. A Lambda authorizer also works, but you must write and maintain the validation logic. API keys identify clients for usage plans without authenticating users, and IAM authorization suits AWS principals rather than app customers.", domain: "saa1", section: "saa-19" },
  { id: "saa-q-160", question: "An application stores orders in an Amazon Aurora MySQL DB cluster. Each time a new order row is inserted, an AWS Lambda function must process it within seconds, and the team wants to avoid polling the database. What should a solutions architect do?", options: ["Subscribe the function to RDS event notifications for the DB cluster","Invoke the function from an Aurora trigger that runs on each insert","Run the function every minute with EventBridge Scheduler to find new rows","Create an EventBridge rule that matches CloudTrail events for the cluster"], answer: 1, explanation: "Aurora MySQL can invoke Lambda directly from a trigger or stored procedure, given an IAM role and outbound network access to Lambda. RDS event notifications only report instance-level events such as failovers or backups, never data changes. A scheduled function is polling, and CloudTrail records API calls rather than inserted rows.", domain: "saa2", section: "saa-19" },
  { id: "saa-q-161", question: "A company's order workflow calls several AWS Lambda functions in sequence, needs automatic retries with backoff on failures, and must pause for a manager's approval that can take up to 3 days. Which solution meets these requirements with the LEAST operational overhead?", options: ["An AWS Step Functions Express workflow","Lambda functions that invoke each other directly","An Amazon SQS delay queue between each function","An AWS Step Functions Standard workflow"], answer: 3, explanation: "Standard workflows can run for up to one year, provide built-in retries and error handling, and can wait on a task token until a person approves. Express workflows stop after five minutes, and chaining functions or delay queues means hand-building retries and state tracking yourself.", domain: "saa2", section: "saa-19" },
  { id: "saa-q-162", question: "A company is building an internal REST API with Amazon API Gateway. The API must be reachable only from applications inside the company's VPC and never from the public internet. What should a solutions architect do?", options: ["Create a private API with a resource policy and an interface VPC endpoint","Create an edge-optimized API and allow only the VPC through an AWS WAF IP rule","Create a Regional API and attach a security group that allows only the VPC CIDR","Create a Regional API that requires an API key from each internal application"], answer: 0, explanation: "A private API is reachable only through an interface VPC endpoint for API Gateway, and its resource policy can restrict access to specific VPCs or endpoints. Edge-optimized and Regional endpoints remain public, API keys are not an authorization control, and API Gateway APIs do not support security groups.", domain: "saa1", section: "saa-19" },
  { id: "saa-q-163", question: "An application stores user session data in an Amazon DynamoDB table. Sessions are useless after 24 hours. The company wants expired items removed automatically at the LOWEST cost. What should a solutions architect do?", options: ["Enable DynamoDB TTL on an attribute that stores each session's expiry time","Run a scheduled Lambda function that scans the table and deletes old items","Export the table to Amazon S3 daily and apply an S3 Lifecycle expiration rule","Create a new table each day and delete the table from the previous day"], answer: 0, explanation: "TTL deletes items in the background after the timestamp in the chosen attribute passes, without consuming write capacity, so the cleanup is free. A scheduled scan and delete function pays for every read and write, and an S3 Lifecycle rule only affects the exported copy, not the table.", domain: "saa4", section: "saa-19" },
  { id: "saa-q-164", question: "A company distributes large software update files from EC2 instances in an Auto Scaling group behind an Application Load Balancer, with the files stored on Amazon EFS. On release days, worldwide demand spikes and costs rise sharply. The files change only when a new version ships. What is the MOST cost-effective change that requires minimal changes to the architecture?", options: ["Add AWS Global Accelerator in front of the Application Load Balancer","Move the instances to larger types with more network bandwidth","Add an Amazon ElastiCache cluster to hold the files in memory","Put an Amazon CloudFront distribution in front of the load balancer"], answer: 3, explanation: "The update files are static, so CloudFront caches them at edge locations and serves most downloads without reaching EC2 or EFS, letting the fleet scale far less. Global Accelerator improves routing but caches nothing, and larger instances or ElastiCache still push every download through the application tier.", domain: "saa4", section: "saa-20" },
  { id: "saa-q-165", question: "A serverless mobile app uses Amazon API Gateway, AWS Lambda, and Amazon DynamoDB. Read traffic has grown tenfold, and most requests fetch the same popular items. Which TWO changes will improve read performance and reduce backend load with the fewest code changes? (Choose TWO.)", options: ["Enable DynamoDB Streams on the table","Increase the Lambda timeout to 15 minutes","Enable response caching on the API stage","Convert the table to a DynamoDB global table","Place a DAX cluster in front of the table"], answer: [2,4], explanation: "API Gateway caching answers repeated requests without invoking Lambda at all, and DAX serves repeated DynamoDB reads from memory in microseconds through a compatible API. Streams capture writes, a longer timeout speeds up nothing, and global tables help users in other Regions rather than hot reads in one Region.", domain: "saa3", section: "saa-20" },
  { id: "saa-q-166", question: "A company must give administrators shell access to Amazon EC2 instances in private subnets. Security policy forbids opening inbound port 22, running bastion hosts, or sharing SSH keys, and every session must be logged. Which solution meets these requirements?", options: ["Deploy a bastion host in a public subnet and record sessions in CloudWatch Logs","Use EC2 Instance Connect to push temporary SSH keys and log calls in CloudTrail","Use AWS Systems Manager Session Manager and send session logs to Amazon S3","Connect over an AWS Site-to-Site VPN and capture sessions with VPC Flow Logs"], answer: 2, explanation: "Session Manager connects through the SSM Agent over outbound HTTPS, so no inbound ports, bastion hosts, or SSH keys are needed, and full session logs can go to S3 or CloudWatch Logs. EC2 Instance Connect still needs inbound port 22, a bastion is forbidden, and a VPN still relies on SSH.", domain: "saa1", section: "saa-30" },
  { id: "saa-q-167", question: "Developers must deploy AWS CloudFormation stacks that create IAM roles and Lambda functions. Following least privilege, the developers themselves must not have permission to create IAM roles. What should a solutions architect do?", options: ["Give CloudFormation a service role with those permissions and let developers pass that role","Attach the AdministratorAccess policy to developers and remove it after each deployment","Enable termination protection and drift detection on every stack the developers deploy","Deploy the stacks through StackSets from the organization management account instead"], answer: 0, explanation: "A CloudFormation service role holds the permissions to create the resources, and developers only need CloudFormation access plus the iam:PassRole permission for that role. AdministratorAccess breaks least privilege. Termination protection and drift detection do not delegate permissions, and StackSets are for deploying across accounts and Regions.", domain: "saa1", section: "saa-30" },
  { id: "saa-q-168", question: "A web application runs on Amazon EC2 instances behind an Application Load Balancer, with Amazon CloudFront in front of the load balancer. The security team must block requests from a list of specific malicious IP addresses. Which solution meets this requirement?", options: ["Add deny rules for the IP addresses to the network ACL of the load balancer subnets","Add deny rules for the IP addresses to the security group of the load balancer","Enable CloudFront geographic restrictions for the listed IP address ranges","Associate an AWS WAF web ACL with an IP set rule to the CloudFront distribution"], answer: 3, explanation: "Behind CloudFront, the load balancer and its subnets only see CloudFront IP addresses, so network ACL rules on client addresses never match. AWS WAF on the distribution inspects the original client IP and can block an IP set. Security groups cannot contain deny rules, and geographic restrictions block countries, not individual addresses.", domain: "saa1", section: "saa-29" },
  { id: "saa-q-169", question: "A company must detect any security group that allows inbound SSH from any IP address and automatically remove the offending rule, using the least custom code. Which solution meets these requirements?", options: ["Enable Amazon GuardDuty and send its findings to an Amazon SNS topic for the team","Use an AWS Config managed rule that triggers an SSM Automation runbook","Enable CloudTrail Insights and have an administrator review unusual events each week","Run AWS Trusted Advisor security checks and delete the rules that the report lists"], answer: 1, explanation: "AWS Config continuously evaluates resource configurations, and its restricted SSH managed rule flags open security groups. Automatic remediation runs a Systems Manager Automation runbook that removes the rule. GuardDuty detects threats rather than configuration problems, and Trusted Advisor and CloudTrail Insights only report, so a person must still fix the rule.", domain: "saa1", section: "saa-24" },
  { id: "saa-q-170", question: "The security team wants an email notification within minutes whenever anyone calls the DeleteBucket or PutBucketPolicy API on any Amazon S3 bucket in the account. Which solution meets this requirement with the LEAST operational effort?", options: ["Enable S3 server access logging and query the logs with Amazon Athena every hour","Create a CloudWatch alarm on the S3 BucketSizeBytes metric for every bucket","Create an EventBridge rule that matches those CloudTrail API calls and targets an SNS topic","Enable AWS Config and review each bucket configuration timeline in the console"], answer: 2, explanation: "CloudTrail records these management API calls and delivers them to EventBridge, where a rule can match the event names and notify an SNS email subscription in near real time. Hourly Athena queries add delay and effort, storage metrics do not show API calls, and the Config timeline needs manual review.", domain: "saa1", section: "saa-24" },
  { id: "saa-q-171", question: "A financial company uses AWS Backup to protect Amazon RDS databases and Amazon EFS file systems. Regulators require that no one, including the root user, can delete the backups or shorten their retention during the seven-year retention period. What should a solutions architect configure?", options: ["An IAM policy that denies backup:DeleteRecoveryPoint to every user in the account","A backup plan rule that copies every recovery point to a second AWS Region","Cross-account copies of the backups to a vault owned by a separate security account","AWS Backup Vault Lock in compliance mode on the vault that stores the backups"], answer: 3, explanation: "Vault Lock in compliance mode makes the vault write once, read many. After its grace period ends, nobody, including the root user, can delete recovery points early or change the retention settings. IAM policies do not restrict the root user, and copies in other Regions or accounts can still be deleted there.", domain: "saa1", section: "saa-28" },
  { id: "saa-q-172", question: "An auditor requires proof that AWS CloudTrail log files were not modified after delivery, and the log files must be protected from deletion for one year. Which TWO actions meet these requirements? (Choose TWO.)", options: ["Enable log file integrity validation on the trail","Enable CloudTrail Insights events on the trail","Encrypt the log files with a customer managed AWS KMS key","Enable S3 Object Lock in compliance mode on the log bucket","Send the trail to CloudWatch Logs with a metric filter"], answer: [0,3], explanation: "Integrity validation writes signed digest files, so you can prove whether any log file was changed or deleted after delivery. S3 Object Lock blocks deletion or overwrite during the retention period. KMS encryption controls who can read the files but proves nothing about changes, and Insights and metric filters only detect activity.", domain: "saa1", section: "saa-24" },
  { id: "saa-q-173", question: "A company needs a disaster recovery plan in a second AWS Region. If the primary Region fails, the application must keep serving users within minutes, even at reduced capacity while it scales up. The company wants to spend less than an active-active design would cost. Which strategy fits BEST?", options: ["Pilot light","Warm standby","Backup and restore","Multi-site active-active"], answer: 1, explanation: "Warm standby keeps a scaled-down but fully working copy of the whole stack running, so it can take traffic immediately and then scale out. Pilot light keeps only core pieces such as a replicated database, so servers must be launched first, which takes longer. Multi-site also works but costs the most.", domain: "saa2", section: "saa-28" },
  { id: "saa-q-174", question: "An application database must be continuously replicated to a second AWS Region so that only a few minutes of data could be lost. A recovery time of a few hours is acceptable, and to keep costs low no application servers should run in the second Region until a disaster occurs. Which disaster recovery strategy should be used?", options: ["Pilot light","Warm standby","Multi-site active-active","Backup and restore"], answer: 0, explanation: "Pilot light keeps only the core, such as a continuously replicated database, running in the recovery Region and launches application servers from AMIs or templates during a disaster. Backup and restore relies on periodic backups instead of continuous replication, and warm standby keeps servers running, which costs more than required.", domain: "saa2", section: "saa-28" },
  { id: "saa-q-175", question: "A company runs 50 on-premises physical and virtual servers. It wants disaster recovery on AWS with continuous block-level replication, a recovery point objective of seconds, and a recovery time objective of minutes, while paying only for low-cost staging resources until a failover. Which service should it use?", options: ["AWS Application Migration Service","AWS Backup with an hourly backup plan","AWS DataSync with scheduled tasks","AWS Elastic Disaster Recovery"], answer: 3, explanation: "Elastic Disaster Recovery continuously replicates servers into a low-cost staging area and launches recovery instances within minutes, with an RPO of seconds. Application Migration Service uses similar replication but is built for one-time migrations. Hourly backups cannot reach seconds of data loss, and DataSync copies files, not whole servers.", domain: "saa2", section: "saa-28" },
  { id: "saa-q-176", question: "An online store runs its production database on an Amazon RDS for MySQL DB instance. The company wants to move to an Amazon Aurora MySQL DB cluster for better read scaling, and the store must stay available with minimal downtime during the move. Which approach should a solutions architect recommend?", options: ["Export with mysqldump and import into a new Aurora cluster","Replicate the instance with AWS Application Migration Service","Create an Aurora read replica of the instance, then promote it","Restore the latest RDS snapshot into a new Aurora cluster"], answer: 2, explanation: "An Aurora read replica stays in sync with the RDS for MySQL source, so writes pause only briefly while it catches up and is promoted. Snapshot restores and mysqldump capture a single point in time, so later writes are lost unless writes stop for the whole copy. Application Migration Service replicates servers, not RDS instances.", domain: "saa2", section: "saa-28" },
  { id: "saa-q-177", question: "A company is migrating an on-premises Oracle database to Amazon Aurora PostgreSQL. The source database must stay online during the migration, and downtime at cutover must be minimal. Which TWO actions should a solutions architect take? (Choose TWO.)", options: ["Rehost the database server with AWS Application Migration Service","Convert the schema and code objects with DMS Schema Conversion","Copy the Oracle data files to Amazon S3 with AWS DataSync","Restore an Oracle RMAN backup directly into Aurora PostgreSQL","Run an AWS DMS task with full load and change data capture"], answer: [1,4], explanation: "A migration between different engines needs schema conversion first, which DMS Schema Conversion or the Schema Conversion Tool handles. DMS then copies the data with a full load and keeps it in sync with change data capture until cutover. Application Migration Service rehosts servers and cannot change the database engine.", domain: "saa2", section: "saa-28" },
  { id: "saa-q-178", question: "A legacy application runs on a single Amazon EC2 instance that uses an Elastic IP address and only EBS volumes. If the underlying AWS hardware fails, the instance must come back automatically with the same instance ID, private IP address, and Elastic IP address. What should a solutions architect do?", options: ["Create a CloudWatch alarm on StatusCheckFailed_System with the EC2 recover action","Place the instance in an Auto Scaling group with a minimum and maximum of one","Create a CloudWatch alarm on StatusCheckFailed_Instance with the EC2 reboot action","Create a daily AMI with Data Lifecycle Manager and relaunch it using AWS Lambda"], answer: 0, explanation: "The recover action moves the instance to healthy hardware and keeps its instance ID, private IP addresses, Elastic IP address, and metadata. An Auto Scaling group launches a new instance with a new ID and private IP. Rebooting does not fix a host failure, and relaunching from an AMI creates a new instance.", domain: "saa2", section: "saa-24" },
  { id: "saa-q-179", question: "A company plans to move 200 on-premises VMware virtual machines to Amazon EC2 without changing the applications. Cutover downtime must be minimal, and the team wants the LEAST manual effort. Which service should it use?", options: ["VM Import and Export with manually exported disk images for each VM","AWS Application Migration Service with continuous replication","AWS Database Migration Service with change data capture","AWS DataSync agents that copy each VM file system to Amazon EFS"], answer: 1, explanation: "Application Migration Service is the recommended lift-and-shift tool. It continuously replicates source servers at the block level, lets you launch test instances, and cuts over with minutes of downtime. VM Import and Export is a manual one-time image import with more downtime, DMS moves only databases, and DataSync copies files, not bootable servers.", domain: "saa2", section: "saa-28" },
  { id: "saa-q-180", question: "An operations team needs CloudWatch alarms on memory utilization and free disk space for a fleet of Amazon EC2 Linux instances, but these metrics do not appear in CloudWatch. What should the team do?", options: ["Enable detailed monitoring on the instances to publish one-minute metrics","Create CloudWatch Logs metric filters on the system log groups of the instances","Enable AWS Config to record the memory and disk configuration of the instances","Install and configure the unified CloudWatch agent on the instances"], answer: 3, explanation: "Memory and disk space usage are only visible inside the operating system, so the default EC2 metrics do not include them. The unified CloudWatch agent collects them as custom metrics and can also send log files. Detailed monitoring only makes the default metrics more frequent, every minute instead of every five minutes.", domain: "saa3", section: "saa-24" },
  { id: "saa-q-181", question: "Application logs are sent to Amazon CloudWatch Logs. The security team needs the log events delivered in near real time to an Amazon Kinesis data stream for analysis by a partner tool. Which solution meets this requirement?", options: ["Schedule a CloudWatch Logs export task to Amazon S3 every hour","Create a CloudWatch Logs subscription filter with the stream as its destination","Run a CloudWatch Logs Insights query every minute and save the results","Create a metric filter and a CloudWatch alarm that writes to the stream"], answer: 1, explanation: "A subscription filter streams matching log events in near real time to Kinesis Data Streams, Amazon Data Firehose, or Lambda. Export tasks are batch jobs for archiving to S3 and can take hours. Logs Insights is for interactive queries, and a metric filter turns log lines into numbers, not a stream of events.", domain: "saa3", section: "saa-24" },
  { id: "saa-q-182", question: "A tightly coupled simulation using MPI runs on Amazon EC2 instances that are already in a cluster placement group. Each run reads a 200 TB input dataset stored in Amazon S3, and both messaging between nodes and file reads are bottlenecks. Which TWO actions will MOST improve performance? (Choose TWO.)", options: ["Attach an Elastic Fabric Adapter to each instance","Move the instances into a spread placement group","Mount an Amazon FSx for Lustre file system linked to the S3 bucket","Copy the dataset to one gp3 EBS volume attached to every instance","Route traffic between the nodes through AWS Global Accelerator"], answer: [0,2], explanation: "Elastic Fabric Adapter adds operating-system-bypass networking that cuts MPI latency, and FSx for Lustre linked to S3 gives parallel, very high-throughput file access. A gp3 volume cannot attach to many instances, spread groups add latency, and Global Accelerator serves internet users.", domain: "saa3", section: "saa-29" },
  { id: "saa-q-183", question: "A company records thousands of customer support calls each day. It wants to convert the recordings to text and then determine whether each customer was positive or negative, without building machine learning models. Which TWO services should it use? (Choose TWO.)", options: ["Amazon Polly","Amazon Transcribe","Amazon Translate","Amazon Comprehend","Amazon Textract"], answer: [1,3], explanation: "Transcribe converts speech to text, and Comprehend performs natural language processing such as sentiment analysis on that text. Polly does the opposite of Transcribe by turning text into speech, Translate changes the language of text, and Textract extracts text from scanned documents and images.", domain: "saa3", section: "saa-23" },
  { id: "saa-q-184", question: "A social media app lets users upload photos. The company must automatically flag images that contain explicit or violent content before they are published, with the LEAST development effort. Which solution meets this requirement?", options: ["Train a custom image classifier with Amazon SageMaker AI","Analyze each image with Amazon Comprehend for unsafe content","Call Amazon Rekognition content moderation for each upload","Extract image details with Amazon Textract and apply rules"], answer: 2, explanation: "Rekognition content moderation detects explicit, suggestive, and violent content in images through a pre-trained API, so no ML expertise is needed. SageMaker AI would work but requires building and training a model. Comprehend analyzes text, not images, and Textract extracts text, forms, and tables from documents.", domain: "saa3", section: "saa-23" },
  { id: "saa-q-185", question: "An online retailer wants to show each shopper real-time product recommendations based on that user's browsing and purchase history. The team has no machine learning experience. Which AWS service should it use?", options: ["Amazon Personalize","Amazon SageMaker AI","Amazon Comprehend","Amazon Kendra"], answer: 0, explanation: "Personalize is a fully managed service that trains real-time recommendation models on your user interaction data, with no ML expertise required. SageMaker AI could build a recommender but needs data science skills. Comprehend analyzes text, and Kendra is a document search service.", domain: "saa3", section: "saa-23" },
  { id: "saa-q-186", question: "A company runs an internal reporting application that can tolerate up to 24 hours of data loss and 24 hours of downtime. It needs a disaster recovery plan in another AWS Region at the LOWEST cost. Which strategy should it use?", options: ["Pilot light with a continuously replicated database","Warm standby with a scaled-down copy of the stack","Multi-site active-active across both Regions","Backup and restore with cross-Region backup copies"], answer: 3, explanation: "With an RPO and RTO of a full day, backup and restore is enough and is the cheapest strategy, because you only pay to store backups until a disaster happens. Pilot light, warm standby, and multi-site keep resources running in the second Region, which shortens recovery but costs more than this workload needs.", domain: "saa4", section: "saa-28" },
  { id: "saa-q-187", question: "A company's development and test EC2 instances and RDS databases are used only from 8 AM to 6 PM on weekdays, but they run all the time. Which solution will reduce cost with the LEAST operational overhead?", options: ["Purchase a Compute Savings Plan that covers the development and test instances","Deploy Instance Scheduler on AWS to stop and start them on a tag-based schedule","Use AWS Compute Optimizer to right-size the instances and databases every month","Buy Reserved Instances for the development EC2 instances and RDS databases"], answer: 1, explanation: "Instance Scheduler on AWS is a ready-made solution that stops and starts tagged EC2 and RDS instances on a schedule, so you stop paying for compute outside working hours. Savings Plans and Reserved Instances discount always-on usage but still charge for idle hours, and right-sizing does not stop instances at night.", domain: "saa4", section: "saa-30" },
  { id: "saa-q-188", question: "A company wants to be alerted automatically when its AWS spending shows unusual spikes, such as a runaway workload, without defining fixed budget thresholds for every service. Which solution meets this requirement?", options: ["Create an AWS Budget for each service with an 80 percent alert threshold","Review the AWS Cost Explorer daily cost graph every morning","Set up AWS Cost Anomaly Detection monitors with SNS alert subscriptions","Export cost data with AWS Data Exports and query it with Amazon Athena"], answer: 2, explanation: "Cost Anomaly Detection uses machine learning to learn your normal spending pattern, flags unusual spikes with likely root causes, and alerts through email or SNS. AWS Budgets needs fixed thresholds that you set yourself, while Cost Explorer and Data Exports are analysis tools that someone must review manually.", domain: "saa4", section: "saa-30" },
  { id: "saa-q-189", question: "A research team runs thousands of containerized jobs each night. Each job takes about 2 hours and can be retried if interrupted. The team wants AWS to manage job queuing and compute provisioning at the LOWEST cost. Which solution fits BEST?", options: ["AWS Batch with a managed compute environment that uses Spot Instances","AWS Lambda functions invoked by Amazon SQS messages for each job","An Amazon EC2 On-Demand fleet running a self-managed job scheduler","AWS Step Functions Express Workflows that run each job as a state"], answer: 0, explanation: "AWS Batch queues jobs and provisions compute automatically, and Spot Instances cut costs for interruptible, retryable work. Lambda functions stop after 15 minutes and Express Workflows after 5 minutes, so neither can run two-hour jobs. A self-managed scheduler on On-Demand instances costs more and adds operational work.", domain: "saa4", section: "saa-30" },
  { id: "saa-q-190", question: "Compliance rules require a company to keep records of all AWS API activity for 5 years. Auditors query the records only a few times each year. Which solution is the MOST cost-effective?", options: ["Rely on the CloudTrail Event history in the console for all audit queries","Send the trail to CloudWatch Logs with 5-year retention and use Logs Insights","Load the CloudTrail log files into an Amazon Redshift cluster for the auditors","Create a trail that writes to Amazon S3 and query the logs with Amazon Athena"], answer: 3, explanation: "A trail stores log files cheaply in S3, where lifecycle rules can move older files to lower-cost storage classes, and Athena charges only for the data each query scans. Event history keeps just 90 days of management events. CloudWatch Logs ingestion and storage cost more, and a running Redshift cluster is expensive for rare queries.", domain: "saa4", section: "saa-24" },
  { id: "saa-q-191", question: "A company wants to review its main workload against AWS best practices, starting with the Cost Optimization pillar. It wants to answer structured questions about the architecture, record the risks found, and track an improvement plan with milestones. Which AWS service should it use?", options: ["AWS Trusted Advisor","AWS Compute Optimizer","AWS Well-Architected Tool","AWS Cost Explorer"], answer: 2, explanation: "The Well-Architected Tool walks you through the framework questions for each pillar, records high and medium risks, and tracks improvement plans and milestones over time. Trusted Advisor runs automated checks on account resources, Compute Optimizer recommends resource sizes, and Cost Explorer visualizes spend, but none of them review a workload design.", domain: "saa4", section: "saa-31" },
  { id: "saa-q-192", question: "A security team wants to trim an IAM user's permissions down to least privilege. It needs to see which AWS services the user's policies allow and when each service was last used. Which IAM feature provides this information?", options: ["IAM Access Advisor on the user's permissions","The IAM credential report for the account","AWS Trusted Advisor security checks","The IAM policy simulator for the user"], answer: 0, explanation: "Access Advisor shows the services a user is allowed to reach and when each was last accessed, so unused permissions can be removed. The credential report is account-wide and covers passwords, MFA, and access keys, not service usage.", domain: "saa1", section: "saa-04" },
  { id: "saa-q-193", question: "An auditor asks for a single downloadable file that lists every IAM user in the account with password status, MFA status, and when each access key was last rotated and last used. Which solution provides this with the LEAST effort?", options: ["Query AWS CloudTrail events for every IAM user","Review IAM Access Advisor for each user","Generate and download the IAM credential report","Export the AWS Config inventory of IAM users"], answer: 2, explanation: "The credential report is one account-level CSV covering passwords, MFA, and access key age and use. Access Advisor is per user and shows service last-accessed data, not credential status.", domain: "saa1", section: "saa-04" },
  { id: "saa-q-194", question: "Administrators need to run AWS CLI commands against their account from a browser. Company policy forbids installing the CLI on laptops and storing long-term access keys on any device. Which solution meets these requirements?", options: ["Launch an EC2 instance with the CLI and a key pair","Use AWS CloudShell from the AWS Management Console","Create an IAM user with access keys for a shared laptop","Store access keys in AWS Secrets Manager for each administrator"], answer: 1, explanation: "CloudShell is a browser-based shell with the CLI preinstalled that uses the signed-in console credentials, so no keys are stored. A self-managed EC2 instance still needs credentials and patching, and storing access keys anywhere breaks the policy.", domain: "saa1", section: "saa-04" },
  { id: "saa-q-195", question: "An IAM policy allows the action s3 GetObject with the resource set to the ARN of the bucket named reports, with no object path. Users with this policy receive access denied when downloading objects from the bucket. What is the cause?", options: ["The policy must also allow the s3 ListBucket action","The bucket must have S3 Versioning enabled","The policy needs a Principal element that names the user","The resource must be the bucket ARN followed by slash star"], answer: 3, explanation: "Object actions such as GetObject apply to object ARNs, so the resource must be the bucket ARN followed by slash star. ListBucket applies to the bucket itself and is not needed to download a known key, and identity-based policies never contain a Principal.", domain: "saa1", section: "saa-04" },
  { id: "saa-q-196", question: "A startup's deployment script uses access keys that belong to the AWS account root user. A security review flags this as a critical risk. Which action should a solutions architect take FIRST to follow IAM best practices?", options: ["Rotate the root access keys every 90 days","Enable MFA on the root user and keep the keys","Give the script an IAM role and delete the root access keys","Store the root access keys in Systems Manager Parameter Store"], answer: 2, explanation: "The root user should have no access keys and be used only for tasks that require it. Give the script its own least-privilege identity, ideally a role, then delete the root keys. Rotating or hiding root keys still leaves unrestricted credentials in use.", domain: "saa1", section: "saa-04" },
  { id: "saa-q-197", question: "A web server on an Amazon EC2 instance in a public subnet is running and listening on port 80. Browsers time out when connecting to the instance's public IP address. The subnet uses the default network ACL. What is the MOST likely fix?", options: ["Add an inbound security group rule allowing HTTP on port 80","Add an outbound security group rule allowing HTTP on port 80","Associate an Elastic IP address with the instance","Change the instance to a larger instance type"], answer: 0, explanation: "A timeout usually means a security group is blocking traffic. Security groups allow no inbound internet traffic by default, so an inbound rule for port 80 is needed. Security groups are stateful, so return traffic needs no extra outbound rule.", domain: "saa1", section: "saa-05" },
  { id: "saa-q-198", question: "A company runs an analytics engine on Amazon EC2 that holds very large datasets entirely in RAM. It needs a high ratio of RAM to vCPU. Which EC2 instance family is the BEST fit?", options: ["Compute optimized instances such as the C family","Storage optimized instances such as the I family","Memory optimized instances such as the R family","Burstable general purpose instances such as the T family"], answer: 2, explanation: "Memory optimized instances such as R are built for workloads that process large datasets in memory, like in-memory databases and real-time analytics. Compute optimized instances favor CPU over RAM, and storage optimized instances target high local disk throughput.", domain: "saa3", section: "saa-05" },
  { id: "saa-q-199", question: "A partner firewall allows traffic only from one fixed IP address. The company's integration server on Amazon EC2 received a new public IP address after it was stopped and started, which broke the integration. Which solution keeps the same public IP address across stops and starts?", options: ["Enable auto-assign public IPv4 addresses on the subnet","Allocate an Elastic IP address and associate it with the instance","Add a secondary private IP address to the network interface","Launch the instance into a cluster placement group"], answer: 1, explanation: "An Elastic IP address is a static public IPv4 address that stays with the instance through stop and start. An auto-assigned public IP is released when the instance stops, and a private IP is not reachable from the internet.", domain: "saa3", section: "saa-06" },
  { id: "saa-q-200", question: "A company runs six critical EC2 instances in one Availability Zone. Each instance must run on distinct underlying hardware so that a single hardware failure affects at most one instance. Which placement strategy meets this requirement?", options: ["A cluster placement group","A partition placement group with two partitions","A spread placement group","Dedicated Instances with default placement"], answer: 2, explanation: "A spread placement group puts each instance on a distinct rack, supporting up to seven running instances per Availability Zone. A partition group with two partitions places several instances on shared hardware, and a cluster group packs instances close together.", domain: "saa2", section: "saa-06" },
  { id: "saa-q-201", question: "A stateless web application runs on several EC2 instances. Route 53 has an A record listing each instance's Elastic IP address with a one-hour TTL. When instances are replaced, some users keep reaching terminated instances for up to an hour. Which design fixes this with the LEAST ongoing manual work?", options: ["Lower the A record TTL to 60 seconds and update it on each change","Add the Elastic IP addresses of standby instances to the A record","Use multivalue answer routing with the Elastic IP addresses","Use an Auto Scaling group behind a load balancer with an alias record"], answer: 3, explanation: "An Auto Scaling group behind a load balancer replaces instances transparently, and the alias record points at the load balancer, so DNS never lists instance IPs. A lower TTL shortens the problem but still needs manual record updates whenever instances change.", domain: "saa2", section: "saa-11" },
  { id: "saa-q-202", question: "A company runs a web application in an AWS Elastic Beanstalk web server environment. Some requests generate PDF reports that take several minutes, which ties up the web servers and causes other requests to time out. Users can receive the reports by email later. Which solution meets these requirements with the LEAST operational overhead?", options: ["Queue the report jobs in Amazon SQS for a Beanstalk worker environment","Raise the load balancer idle timeout so that report requests can finish","Add more instances to the web server environment's Auto Scaling group","Call an AWS Lambda function synchronously from the web server per report"], answer: 0, explanation: "A worker environment pulls jobs from an Amazon SQS queue and runs long tasks in the background, so the web tier responds right away. A longer idle timeout or more instances still tie up web servers during long requests, and a synchronous Lambda call keeps each request waiting.", domain: "saa2", section: "saa-11" },
  { id: "saa-q-203", question: "A company creates new test environments several times a week. Each needs an Amazon RDS database already loaded with 500 GB of reference data. Loading the data with scripts takes hours. Which approach makes new environments ready fastest?", options: ["Run the load scripts from EC2 user data at boot","Restore each database from an RDS snapshot that contains the data","Create a read replica of production and keep it running","Export the data to Amazon S3 and import it with AWS Glue"], answer: 1, explanation: "Restoring from an RDS snapshot creates a new database with the schema and data already in place, far faster than loading it with scripts. A read replica is read-only, so testers cannot change it, and it keeps costing money between tests.", domain: "saa3", section: "saa-11" },
  { id: "saa-q-204", question: "A company hosts a static website on Amazon S3 using a newly created bucket with static website hosting enabled. Visitors receive a 403 Forbidden error. Which change allows public access to the website?", options: ["Enable S3 Versioning and set an index document for the bucket","Add a CORS configuration that allows requests from all origins","Grant public read access with an object ACL on each file","Turn off Block Public Access and add a public read bucket policy"], answer: 3, explanation: "New buckets have Block Public Access on and ACLs disabled, so Block Public Access must be turned off for the bucket, and the account if set there, plus a bucket policy granting public GetObject. Object ACLs cannot be used while ACLs are disabled, and CORS only affects cross-origin requests.", domain: "saa1", section: "saa-12" },
  { id: "saa-q-205", question: "A company uses S3 Cross-Region Replication from bucket A to bucket B, and a second replication rule from bucket B to bucket C. Objects uploaded directly to bucket B appear in bucket C, but objects uploaded to bucket A never reach bucket C. Every new object in bucket A must be copied to both other buckets automatically. What should a solutions architect do?", options: ["Add a replication rule on bucket A that uses bucket C as a second destination","Enable delete marker replication on the rule from bucket A to bucket B","Turn on S3 Replication Time Control for the rule from bucket B to bucket C","Enable S3 Versioning on bucket C so that it can accept replicated objects"], answer: 0, explanation: "S3 replication does not chain: objects that arrive in bucket B as replicas are not replicated again, so bucket A needs its own rule to bucket C. Replication Time Control only speeds up replication, and bucket C already receives objects, so versioning is on.", domain: "saa2", section: "saa-12" },
  { id: "saa-q-206", question: "A web API runs as an Amazon ECS service on AWS Fargate behind an Application Load Balancer. Traffic rises and falls throughout the day, and the number of running tasks must follow the load automatically. Which solution meets this requirement?", options: ["Configure ECS Service Auto Scaling with target tracking on service CPU utilization","Attach a target tracking policy to an EC2 Auto Scaling group that backs the ECS cluster","Increase the CPU and memory values in the task definition to handle the peak traffic","Schedule an AWS Lambda function to update the service desired count every hour"], answer: 0, explanation: "ECS Service Auto Scaling adjusts the task count using target tracking on CPU, memory, or load balancer requests per target. With Fargate there are no EC2 instances, so an EC2 Auto Scaling group policy does not apply. Bigger tasks or hourly updates do not track real demand.", domain: "saa3", section: "saa-18" },
  { id: "saa-q-207", question: "A company runs an Amazon ECS service on the EC2 launch type. Service Auto Scaling adds tasks during peaks, but new tasks stay in the pending state because the cluster has no free CPU or memory. Which solution fixes this with the LEAST operational overhead?", options: ["Add a scheduled action that grows the Auto Scaling group before expected peaks","Create a CloudWatch alarm on instance CPU that triggers a Lambda function to add instances","Use an Auto Scaling group capacity provider with managed scaling enabled for the cluster","Switch the service to host networking mode so that more tasks fit on each instance"], answer: 2, explanation: "A capacity provider with managed scaling watches task placement and launches EC2 instances when tasks cannot be placed, then scales in when idle. Scheduled actions miss unexpected peaks, and a custom alarm plus Lambda adds code to maintain. Host networking does not create more CPU or memory.", domain: "saa2", section: "saa-18" },
  { id: "saa-q-208", question: "A company runs its applications on a self-managed Kubernetes cluster on premises and wants to move them to AWS. It wants to keep its existing Kubernetes manifests and tooling, and it does not want to provision, patch, or scale worker nodes. Which solution meets these requirements?", options: ["Amazon ECS with the AWS Fargate launch type","Kubernetes installed on Amazon EC2 instances in an Auto Scaling group","Amazon EKS with self-managed nodes in an Auto Scaling group","Amazon EKS with pods running on AWS Fargate"], answer: 3, explanation: "Amazon EKS runs standard Kubernetes, and running pods on Fargate removes all worker node management. Amazon ECS on Fargate is also serverless, but it would mean rewriting the Kubernetes manifests into ECS task definitions. Self-managed nodes and a do-it-yourself cluster still require patching and scaling servers.", domain: "saa2", section: "saa-18" },
  { id: "saa-q-209", question: "A development team pushes a new container image to a private Amazon ECR repository on every build. Storage costs keep rising. The team wants to keep only the 20 most recent tagged images and delete untagged images older than 7 days, with no custom code. What should a solutions architect do?", options: ["Enable enhanced scanning on the repository to remove outdated images","Create Amazon ECR lifecycle policy rules on the repository","Add an S3 Lifecycle rule to the bucket that stores the ECR images","Run a scheduled Lambda function that deletes images with the AWS SDK"], answer: 1, explanation: "ECR lifecycle policies expire images automatically by count or age, for tagged or untagged images. ECR stores images in Amazon S3 behind the scenes, but that bucket is not visible to customers, so S3 Lifecycle rules cannot be applied. A Lambda function works but is custom code.", domain: "saa4", section: "saa-18" },
  { id: "saa-q-210", question: "A company receives large video files in an Amazon S3 bucket. Each file must be processed by a containerized job that runs for up to 45 minutes. The company does not want any tasks or servers running while no files arrive. Which solution meets these requirements?", options: ["Configure S3 Event Notifications to invoke an AWS Lambda function that processes each file","Run an Amazon ECS service with one Fargate task that polls the bucket for new objects","Create an Amazon EventBridge rule for new S3 objects that runs an Amazon ECS task on Fargate","Configure S3 Event Notifications to start an Amazon ECS service on an EC2 cluster directly"], answer: 2, explanation: "An EventBridge rule can react to S3 object created events and run an ECS task on Fargate, so compute exists only while a file is processed. Lambda is tempting but stops at 15 minutes. A polling service runs all the time, and S3 Event Notifications cannot target ECS directly.", domain: "saa3", section: "saa-18" },
  { id: "saa-q-211", question: "A serverless video course site stores its lessons in a private Amazon S3 bucket that is served only through Amazon CloudFront with origin access control. Only paying subscribers may watch, and each subscriber must stream many lesson files without the site changing its URLs. Which solution meets these requirements?", options: ["Have a Lambda function check the subscription and then issue CloudFront signed cookies to the subscriber","Have a Lambda function generate an S3 presigned URL for each lesson and send users to the bucket","Attach an AWS WAF rule to the distribution that allows only the IP addresses of known subscribers","Configure CloudFront geographic restrictions so that only countries with subscribers can reach the site"], answer: 0, explanation: "CloudFront signed cookies grant access to many restricted files without changing their URLs, and a Lambda function can issue them after checking the subscription. S3 presigned URLs are tempting, but they bypass CloudFront while the bucket only accepts CloudFront requests. IP lists and geographic restrictions cannot identify paying subscribers.", domain: "saa1", section: "saa-20" },
  { id: "saa-q-212", question: "A serverless blog stores photos that users upload to an Amazon S3 bucket. Each photo needs a thumbnail created automatically soon after upload, and the solution must scale with traffic without managing servers. Which solution meets these requirements?", options: ["Run a cron job on an Amazon EC2 instance that lists the bucket every minute and resizes new photos","Configure an S3 event notification that invokes an AWS Lambda function to create each thumbnail","Use CloudFront Functions to resize each photo when a viewer first requests it from the edge","Schedule an AWS Glue job every hour that converts the new photos into thumbnails"], answer: 1, explanation: "An S3 event notification invokes Lambda for every new object, which scales automatically and needs no servers. CloudFront Functions are tempting, but they are lightweight and cannot read or transform the image body. An EC2 cron job needs a server, and an hourly Glue job is slow and meant for data processing.", domain: "saa2", section: "saa-20" },
  { id: "saa-q-213", question: "A company splits its application into microservices. Mobile clients need one public HTTPS entry point that sends requests for the users path to an AWS Lambda function and requests for the orders path to an Amazon ECS service. Each client must get its own request quota enforced with an API key. Which solution meets these requirements?", options: ["An Application Load Balancer with path-based rules for the Lambda function and the ECS service","An Amazon CloudFront distribution with a separate cache behavior for each path","Amazon Route 53 weighted records that point to each microservice endpoint","An Amazon API Gateway REST API with usage plans, routing each path to its backend"], answer: 3, explanation: "API Gateway REST APIs route each resource path to a backend and enforce per-client throttling and quotas through usage plans and API keys. An Application Load Balancer can route paths to Lambda and ECS, but it has no API keys or per-client quotas. CloudFront and Route 53 do not provide per-client quotas either.", domain: "saa3", section: "saa-20" },
  { id: "saa-q-214", question: "A company runs a self-managed MongoDB replica set on Amazon EC2. The team spends too much time on patching, backups, and replacing failed nodes. It wants a managed, highly available database with minimal application code changes. Which AWS service should it use?", options: ["Amazon DynamoDB with on-demand capacity","Amazon Keyspaces for Apache Cassandra","Amazon Neptune with read replicas","Amazon DocumentDB with MongoDB compatibility"], answer: 3, explanation: "Amazon DocumentDB is a managed document database compatible with MongoDB drivers and APIs, with storage replicated across three Availability Zones. DynamoDB also stores JSON-like items, but moving to it means rewriting data access code. Keyspaces is for Cassandra and Neptune is for graphs.", domain: "saa2", section: "saa-21" },
  { id: "saa-q-215", question: "A company runs Apache Cassandra on Amazon EC2 for an IoT workload. It wants to stop managing Cassandra nodes and keep using its existing Cassandra Query Language code, while paying only for the reads and writes it uses. Which solution meets these requirements?", options: ["Amazon Keyspaces with on-demand capacity mode","Amazon DynamoDB with on-demand capacity mode","Amazon Timestream for InfluxDB with a single instance","Amazon Aurora Serverless v2 with PostgreSQL compatibility"], answer: 0, explanation: "Amazon Keyspaces is a serverless, Cassandra-compatible service that accepts existing Cassandra Query Language code, and on-demand mode bills per request. DynamoDB is also serverless and pay per request, but it would require rewriting the data access layer. Timestream and Aurora are different database engines.", domain: "saa2", section: "saa-21" },
  { id: "saa-q-216", question: "An online game must show a global leaderboard that ranks millions of players by score. Scores update constantly, and the top 100 must be returned in under a millisecond. Which solution is the BEST fit?", options: ["An Amazon RDS for MySQL table with an index on the score column","Amazon ElastiCache for Valkey using sorted sets keyed by player","An Amazon Redshift table sorted by score and queried on demand","An Amazon DynamoDB table with a global secondary index on score"], answer: 1, explanation: "Valkey and Redis OSS sorted sets keep members ordered by score in memory, so ranking queries return in microseconds even with constant updates. DynamoDB is fast but is not built to rank a whole table by score, and RDS and Redshift cannot reliably deliver sub-millisecond rankings under constant writes.", domain: "saa3", section: "saa-21" },
  { id: "saa-q-217", question: "A media application stores video files of up to 5 gigabytes each. Users must quickly search the videos by uploader and upload date. Which design is the MOST suitable and scalable?", options: ["Store each video and its metadata together as a single item in Amazon DynamoDB","Store each video as a binary large object in an Amazon RDS for PostgreSQL table","Store the videos in Amazon S3 and index their metadata in Amazon DynamoDB","Store the videos on Amazon EFS and encode the metadata in each file name"], answer: 2, explanation: "Amazon S3 is built for large objects, and a DynamoDB table holding each object key with its uploader and date gives fast, scalable lookups. DynamoDB items are limited to 400 kilobytes, so videos cannot be stored there. Large binary objects in RDS are costly and slow, and file names are not a searchable index.", domain: "saa3", section: "saa-21" },
  { id: "saa-q-218", question: "A clinic wants callers to its phone line to book appointments by speaking naturally with a virtual agent, which understands their intent and asks follow-up questions. The clinic wants a cloud contact center without building machine learning models. Which combination of services meets these requirements?", options: ["Amazon Polly with Amazon Transcribe","Amazon Comprehend with Amazon SNS","Amazon Translate with Amazon Pinpoint","Amazon Lex with Amazon Connect"], answer: 3, explanation: "Amazon Lex builds conversational bots that recognize intent and prompt for missing details, and Amazon Connect is the cloud contact center that routes calls to the bot. Transcribe and Polly convert speech and text but do not manage a conversation or a phone line.", domain: "saa3", section: "saa-23" },
  { id: "saa-q-219", question: "An accounts payable team receives thousands of scanned supplier invoices as PDF files each week. It needs the vendor name, invoice total, and line item tables extracted automatically into a database, without training a model. Which AWS service should it use?", options: ["Amazon Textract","Amazon Rekognition","Amazon Comprehend","Amazon Kendra"], answer: 0, explanation: "Amazon Textract extracts printed and handwritten text, form fields, and tables from scanned documents, and has a specialized feature for invoices and receipts. Rekognition finds objects and faces in images rather than document structure, and Comprehend analyzes text that has already been extracted.", domain: "saa3", section: "saa-23" },
  { id: "saa-q-220", question: "A real estate company has ten years of its own sales data and wants its data scientists to build, train, and deploy a custom model that predicts house prices, using a fully managed platform that handles the training and hosting infrastructure. Which AWS service should it use?", options: ["Amazon Personalize","Amazon SageMaker AI","Amazon Comprehend","Amazon Forecast"], answer: 1, explanation: "Amazon SageMaker AI is the managed platform to label data, build, train, tune, and deploy custom machine learning models. Personalize only builds recommendation models, Comprehend analyzes text, and Forecast is for time series predictions and is closed to new customers.", domain: "saa3", section: "saa-23" },
  { id: "saa-q-221", question: "S3 event notifications invoke an AWS Lambda function asynchronously to process each uploaded file. A few invocations still fail after the built-in retries, and those events are lost. The team must keep every failed event with its error details for later reprocessing, without changing the function code. Which solution meets these requirements?", options: ["Increase the function timeout and memory so that the invocations stop failing","Enable S3 Versioning on the bucket so that failed files can be processed again","Set reserved concurrency on the function so that failed events wait for a retry","Configure an on-failure destination that sends failed events to an SQS queue"], answer: 3, explanation: "For asynchronous invocations, Lambda retries twice, and an on-failure destination then sends the event with its error details to an SQS queue for reprocessing. Versioning is tempting, but it keeps old object copies, not failed events. More memory or time does not fix every failure, and reserved concurrency does not store events.", domain: "saa2", section: "saa-29" },
  { id: "saa-q-222", question: "A legacy application must run on exactly one Amazon EC2 instance, and clients connect to it through an Elastic IP address. The application must recover automatically even if its Availability Zone fails. Which solution meets these requirements?", options: ["Use a one-instance Auto Scaling group across two Availability Zones that reattaches the Elastic IP address","Create a CloudWatch alarm with the EC2 recover action on the instance, keeping the same Elastic IP address","Place the instance in a spread placement group so that it runs on distinct hardware in the Availability Zone","Take hourly EBS snapshots and restore the instance manually in another Availability Zone if a failure occurs"], answer: 0, explanation: "An Auto Scaling group with minimum, maximum, and desired of one spanning two zones replaces a failed instance in the healthy zone, and user data with an instance role reattaches the Elastic IP address. The recover action is tempting, but it only recovers within the same zone. Manual restores are not automatic.", domain: "saa2", section: "saa-29" },
  { id: "saa-q-223", question: "A research team runs an on-premises high performance computing cluster that schedules jobs with Slurm. It wants to move to AWS, keep its existing Slurm job scripts, define the cluster in a configuration file, and have compute nodes scale up for queued jobs and down to zero when idle. Which solution meets these requirements?", options: ["Run the jobs with AWS Batch using a managed compute environment","Deploy the cluster with AWS ParallelCluster using the Slurm scheduler","Launch the nodes with an Auto Scaling group in a cluster placement group","Process the jobs on an Amazon EMR cluster with instance fleets and Spot"], answer: 1, explanation: "AWS ParallelCluster builds HPC clusters from a configuration file, supports the Slurm scheduler, and scales compute nodes with the job queue, down to zero. AWS Batch is tempting because it also scales with queued jobs, but it uses its own job definitions instead of Slurm scripts. An Auto Scaling group has no scheduler, and EMR is for big data frameworks.", domain: "saa3", section: "saa-29" },
  { id: "saa-q-224", question: "A company wants an automated dashboard that continuously checks its AWS account and flags idle EC2 instances, unassociated Elastic IP addresses, security groups with unrestricted ports, and services close to their quotas. Which AWS service provides these checks?", options: ["AWS Well-Architected Tool","AWS Compute Optimizer","AWS Trusted Advisor","Amazon Inspector"], answer: 2, explanation: "Trusted Advisor runs automated best practice checks across cost optimization, security, fault tolerance, performance, service limits, and operational excellence. The Well-Architected Tool is tempting, but it is a guided questionnaire. Compute Optimizer covers right-sizing and idle resources only, not open ports or quotas, and Inspector scans for software vulnerabilities.", domain: "saa4", section: "saa-31" },
  { id: "saa-q-225", question: "During a Well-Architected review, a team decides to move workloads to AWS Graviton instances, delete data nobody uses, and maximize utilization, with the main goal of minimizing the environmental impact of its cloud workloads. Which pillar of the AWS Well-Architected Framework does this goal belong to?", options: ["Cost Optimization","Performance Efficiency","Operational Excellence","Sustainability"], answer: 3, explanation: "The Sustainability pillar focuses on reducing the environmental impact of workloads, including maximizing utilization, using efficient hardware such as Graviton, and removing unneeded data. These actions also save money, which makes Cost Optimization tempting, but the stated goal is environmental impact.", domain: "saa4", section: "saa-31" },
  { id: "saa-q-226", question: "A company replaces one very large EC2 instance with several smaller instances behind a load balancer, so that a single instance failure affects only a small part of the traffic. It also regularly tests how the system recovers from failures. Which Well-Architected pillar do these design principles mainly support?", options: ["Security","Performance Efficiency","Reliability","Cost Optimization"], answer: 2, explanation: "Scaling horizontally to reduce the impact of a single failure and testing recovery procedures are design principles of the Reliability pillar. Performance Efficiency is tempting because more instances can add capacity, but it focuses on selecting and using resources efficiently, not on limiting failure impact.", domain: "saa2", section: "saa-31" },
];

